/* ─────────────────────────────────────────────────────────────
   app.js — AI-Ready Architecture core module
   ─────────────────────────────────────────────────────────────
   Extracted from the single-file build. Holds state, routing,
   and every screen still rendered inline (readiness, steps,
   phases, outcomes, tech-stack dashboard, insights, coach,
   notes, team chat, voice, assignment, architectural diagram).

   Home and Learn are migrated out to the per-screen pattern:
     home.html + home.js   → renderHome(container)
     learn.html + learn.js → renderLearn(container)
   Shared plumbing for those lives in screen-loader.js; the
   render() dispatcher routes to them via SCREEN_MODULES.

   Load order (index.html):
     templates-local.js → screen-loader.js → home.js, learn.js
     → app.js (this file — boots the app at the bottom)
   ───────────────────────────────────────────────────────────── */

/* ═══ DATA & STATE ═══ */
/* ═══ MULTI-ORG TENANCY ═══
   Each organization has its own isolated data environment
   (key: architecture-org-data::<orgId>). A registry lists all
   orgs (architecture-orgs). currentOrgId selects the active one.
   Ported from the AI Innovation Pipeline app. */
/* 28 Sep 2026 (audit D-A4): the module-level SK constant, which nothing read, is removed; the Store's LEGACY_KEY is the one legacy key */
function emptyData(){return{settings:{aiGuide:false,voice:false} /* 2 Oct 2026 (Spec §25.2, Rollout item 81): the AI features start off */,commitmentChecks:{},computeResources:[], /* 30 Sep 2026 (Paul): the migration machinery is gone — nothing converts a record on load or on render; every record the current build creates is already in its final shape */assessments:{},dataEstate:[],integrations:[],identities:{},aiModels:[],aiApplications:[],flows:[],connections:[],connTypes:[],vendors:[],riskScenarios:[],dataGovernance:{},apiPolicy:{},apiCatalog:[],integrationRetirement:[],circuitBreakers:{},identityPlan:{},agentRegistry:[],shadowRemediation:[],modelGovernance:{},observability:{},computePlan:{},deployment:{},deployments:[],securityTests:[],cascadeTests:[],alignmentReviews:{} /* P31: keyed by deployment id; P34: the dead alignmentChecklist store swept (0 readers) */,reviewBoard:{},rbOrg:{},rbRaci:{},skillsInventory:[],reviewResults:{},sovereignty:{noExternalDependencies:false},aiDependencies:[],sovereigntyTests:[],sovereigntyOps:{},sovProgram:{items:{},actions:[],monitor:{}} /* Rung 0 (Paul's ruling, 2 Sep 2026): the sovereignty program — status per item, steps, monitoring */,completedSteps:{},stepDoneAt:{},stepDue:{},startDate:'',completedSections:{},notes:[],assigns:{},roster:[],enterprise:{}}}
var data=emptyData();
/* ============================================================
   Store - the single persistence seam (Phase 1: server-prep).
   Every durable read/write goes through this module. Backed by
   localStorage today; to move to a server, the dev team repoints
   the ADAPTER block below (raw get/set/del, the org-blob methods,
   and the discrete-op methods) at their API - call sites do not
   change.

   Local backing preserves today's behavior: readOrg/writeOrg move
   the whole org record (localStorage has no partial write). The
   discrete ops (patch / setPath / removeRec) are the server-shaped
   write vocabulary; Phase 2 reroutes the field/record write helpers
   onto them so a server can apply each as a PATCH on one record
   instead of rewriting the blob.
   ============================================================ */
var Store = (function(){
  /* -- ADAPTER: the one place to repoint to a server -- */
  function rawGet(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } }
  function rawSet(k,v){ try{ localStorage.setItem(k,v); return true; }catch(e){ return false; } }
  function rawDel(k){ try{ localStorage.removeItem(k); }catch(e){} }
  function readJSON(k,f){ var s=rawGet(k); if(s==null) return f; try{ return JSON.parse(s); }catch(e){ return f; } }
  function writeJSON(k,v){ return rawSet(k, JSON.stringify(v)); }

  /* -- keys (one source of truth) -- */
  var ORGS_KEY='architecture-orgs', CURRENT_ORG_KEY='architecture-current-org',
      REMEMBER_KEY='architecture-remember', ADMIN_KEY='architecture-admin';
  function orgKey(id){ return 'architecture-org-data::'+id; }
  function prefKey(name){ return 'architecture-'+name; }

  /* -- org data blob (wholesale today; the future server record) -- */
  function readOrg(id){ return readJSON(orgKey(id), null); }
  function orgRaw(id){ return rawGet(orgKey(id)); }
  /* -- revisioned writes (multi-user prep, July 8) --------------------
     Every persisted blob carries schemaVersion and a monotonic rev. The
     local store never rejects a write; the server enforces optimistic
     concurrency: PUT {baseRev, blob} → 200 {rev: baseRev+1} when its
     stored rev === baseRev, else 409 {stale:true, rev} – and on a 409
     the server adapter calls handleStaleWrite() below. revKey mirrors
     the blob's rev in a tiny record so change-polling never parses the
     whole blob (server equivalent: GET /org/{id}/rev). */
  var SCHEMA_VERSION=1;
  function revKey(id){ return 'architecture-org-rev::'+id; }
  function orgRev(id){ var v=parseInt(rawGet(revKey(id)),10); return isNaN(v)?0:v; }
  function writeOrg(id,obj){     if(orgDeleted(id)){ if(typeof currentOrgId!=='undefined' && id===currentOrgId) orgGone(); return false; } /* 1 Oct 2026 (QA Sweep 3): every save passes here, so none can recreate a deleted organization */     if(obj && typeof obj==='object'){ obj.schemaVersion=SCHEMA_VERSION; obj.rev=(obj.rev||0)+1; }
    var _wo=obj; if(obj&&Array.isArray(obj.aiDependencies)&&obj.aiDependencies.some(function(d){return d&&d._new})){ _wo={}; for(var _wk in obj) if(Object.prototype.hasOwnProperty.call(obj,_wk)) _wo[_wk]=obj[_wk]; _wo.aiDependencies=obj.aiDependencies.filter(function(d){return !(d&&d._new)}); } /* 16 Oct 2026 (Paul, UAT Round 3): a new dependency is saved only once it has a name */
    var okW=writeJSON(orgKey(id), _wo);
    if(okW && obj) rawSet(revKey(id), String(obj.rev||0));
    return okW;
  }
  function removeOrg(id){ rawDel(orgKey(id)); rawDel(revKey(id)); }

  /* -- discrete write vocabulary (server-shaped; Phase 2 targets) --
     Local impl mutates the active replica `data`, then persists it
     whole; a server maps each call to a PATCH on one record. */
  /* dirty-record set: commit() marks which record changed, then persists.
     Locally the whole blob is rewritten (localStorage has no partial write);
     a server adapter flushes the dirty records and calls clearDirty(), so each
     write - and each lock - is scoped to a single record. Scaffolding the devs
     can build on or replace. */
  var _dirty={};
  function recKey(collection, id){ return collection + (id==null ? '' : ('::'+id)); }
  function orgDeleted(id){ try{ return JSON.parse(rawGet('architecture-deleted-orgs')||'[]').indexOf(id)>=0; }catch(e){ return false; } } function orgGone(){ if(typeof window!=='undefined'&&window.__orgGoneBusy) return; try{ if(typeof window!=='undefined') window.__orgGoneBusy=true; if(typeof signOutNow==='function') signOutNow(); }catch(e){} finally{ if(typeof window!=='undefined') window.__orgGoneBusy=false; } } /* 1 Oct 2026 (QA Sweep 3): a session in a deleted organization writes nothing and lands on sign-in */ function persistActive(){ if(typeof _readOnlyRender!=='undefined'&&_readOnlyRender>0) return; if(typeof currentOrgId!=='undefined' && currentOrgId){ if(orgDeleted(currentOrgId)){ orgGone(); return; } writeOrg(currentOrgId, data); try{ if(typeof refreshGateInPlace==='function') refreshGateInPlace(); }catch(e){} } } /* 1 Oct 2026 (QA Sweep 3, N-3, N-9): every commit refreshes the gates at once, whatever route made it */ /* 28 Sep 2026 (the consolidated re-audit, C02) */
  function commit(collection, id){ if(typeof _readOnlyRender!=='undefined'&&_readOnlyRender>0) return; _dirty[recKey(collection,id)]=true; persistActive(); } /* 28 Sep 2026 (the consolidated re-audit, C02) */
  function patch(collection, id, fields){
    if(!data[collection]) data[collection]={};
    var rec = (id==null) ? data[collection] : (Array.isArray(data[collection]) ? (data[collection].find(function(x){return x&&x.id===id})||null) : (data[collection][id] || (data[collection][id]={}))); if(rec===null) return; /* 23 Sep 2026 (stable identity R2): on an array collection, id is a record's identity, never a subscript; an unknown id writes nothing */
    for(var k in fields){ if(Object.prototype.hasOwnProperty.call(fields,k)) rec[k]=fields[k]; }
    commit(collection, id);
  }
  function setPath(path, value){
    var parts=(''+path).split('.'), o=data, i;
    for(i=0;i<parts.length-1;i++){ if(o[parts[i]]==null || typeof o[parts[i]]!=='object') o[parts[i]]={}; o=o[parts[i]]; }
    o[parts[parts.length-1]]=value; commit(parts[0], parts.length>1 ? parts[1] : null);
  }
  function removeRec(collection, id){ var c=data[collection]; if(Array.isArray(c)){ data[collection]=c.filter(function(x){return !(x&&x.id===id)}); } else if(c){ delete c[id]; } commit(collection, id); } /* 23 Sep 2026 (R2): by identity */

  /* -- multi-user client machinery (July 8) ---------------------------
     refreshOrg(): adopt a newer stored blob for the active org without
     losing the edit in progress. The focused field's value and caret are
     captured before the re-render and restored after, so a user typing
     mid-refresh keeps typing and their value commits on blur exactly as
     it would have. Reuses loadData() so the schema-normalization
     migrations run on every adopted blob. Returns true when a newer
     blob was adopted. */
  function captureFocus(){
    try{ var a=document.activeElement;
      if(!a || !a.id || !('value' in a)) return null;
      return { id:a.id, value:a.value,
               s:(typeof a.selectionStart==='number')?a.selectionStart:null,
               e:(typeof a.selectionEnd==='number')?a.selectionEnd:null };
    }catch(e){ return null; }
  }
  function restoreFocus(f){
    try{ if(!f) return; var el=document.getElementById(f.id); if(!el) return;
      el.value=f.value; el.focus();
      if(f.s!=null && el.setSelectionRange) el.setSelectionRange(f.s, f.e==null?f.s:f.e);
    }catch(e){}
  }
  function refreshOrg(){
    if(typeof currentOrgId==='undefined' || !currentOrgId) return false;
    if(orgRev(currentOrgId) <= ((data&&data.rev)||0)) return false;
    var f=captureFocus();     loadData(); applyTeamRoster();     try{ if(typeof currentUserId!=='undefined' && currentUserId && !(USERS||[]).some(function(u){return u&&u.id===currentUserId}) && typeof signOutNow==='function'){ signOutNow(); return true; } }catch(e){} /* 1 Oct 2026 (QA Sweep 3): a member an adopted save removed is signed out in this tab too */
    /* Self-heal (15 Aug 2026, defect found in Paul's visual pass): a foreign or legacy writer
       (the pre-conformance build shares this module's storage prefix under file://) can leave the
       stored blob with no rev while the mirror record keeps one - without this line the tab adopts
       that blob every poll cycle forever, re-rendering the page every 5 seconds. After adopting,
       align the in-memory rev to the mirror so the comparison settles; the next legitimate write
       re-stamps blob and mirror together. Donor-side flag: the item-57 store head has the same hole. */
    if(!(data&&typeof data.rev==='number'&&data.rev>=orgRev(currentOrgId))){ if(data) data.rev=orgRev(currentOrgId); }
    _adoptPaint=true;
    try{ render(); }catch(e){}
    _adoptPaint=false;
    restoreFocus(f);
    return true;
  }

  /* stale-write recovery: re-pull, overlay the local dirty records onto
     the fresh blob, persist, clear the dirty set. Unreachable in local
     mode (the local store never rejects a write); the server adapter
     calls it on a 409. Record-level last-writer-wins, per the blob-PUT
     ruling – optimize only if contention demands. The dirty set means
     'changed since the last successful sync': the server adapter clears
     it on every 200 (locally it is scaffolding and accumulates). */
  function mergeDirtyInto(fresh, local, dirtyKeys){
    (dirtyKeys||[]).forEach(function(k){
      var i=k.indexOf('::');
      if(i<0){ fresh[k]=local[k]; }
      else { var col=k.slice(0,i), id=k.slice(i+2);         if(Array.isArray(local[col])){ /* 23 Sep 2026 (R2): an array record merges by its id; a record deleted locally is deleted in the merge */           if(!Array.isArray(fresh[col])) fresh[col]=[];           var lr=local[col].find(function(x){return x&&x.id===id}); var fi=fresh[col].findIndex(function(x){return x&&x.id===id});           if(lr){ if(fi>=0) fresh[col][fi]=lr; else fresh[col].push(lr); } else if(fi>=0){ fresh[col].splice(fi,1); }         } else {         if(!fresh[col] || typeof fresh[col]!=='object') fresh[col]={};         fresh[col][id]=(local[col]||{})[id]; } }
    });
    return fresh;
  }
  function handleStaleWrite(id){
    var fresh=readOrg(id); if(!fresh) return false;
    if(fresh.resetAt&&fresh.resetAt!==(data&&data.resetAt)){ _dirty={}; data=fresh; try{applyTeamRoster();render()}catch(e){} return true; } /* Sweep 4R item 19: an adopted reset discards local drafts and writes nothing */ mergeDirtyInto(fresh, data, Object.keys(_dirty));
    data=fresh;
    /* module schema normalizers hook (none yet for this module) */
    var okW=writeOrg(id, data);
    if(okW) _dirty={};
    try{ applyTeamRoster(); render(); }catch(e){}
    return okW;
  }

  /* change signal: storage events are the local channel (another tab's
     write fires them); polling is the fallback. A server build pushes
     the same nudge over the Collab channel (its read/write adapter
     lines) and keeps this polling as the fallback. Cheap: compares the
     mirrored rev record, never the blob. Both hooks no-op in the test
     probe, where addEventListener and setInterval are stubs. */
  var CHANGE_POLL_MS=5000;
  function checkRemote(){
    try{
      if(typeof currentOrgId==='undefined' || !currentOrgId) return false;       if(orgDeleted(currentOrgId)){ orgGone(); return false; }       if(orgRev(currentOrgId) > ((data&&data.rev)||0)) return refreshOrg();
    }catch(e){}
    return false;
  }
  function startChangeSignal(){
    try{ window.addEventListener('storage', function(ev){
      try{ if(ev && currentOrgId && (ev.key===orgKey(currentOrgId) || ev.key===revKey(currentOrgId))) checkRemote(); }catch(e){}
    }); }catch(e){}
    try{ setInterval(function(){
      try{ if(typeof document!=='undefined' && document.hidden) return; }catch(e){}
      checkRemote();
    }, CHANGE_POLL_MS); }catch(e){}
  }

  /* -- boot readiness (async loader, July 8) --------------------------
     ready(cb) is the seam the boot sequence waits on. Local mode:
     localStorage needs no fetch, so cb fires synchronously in the same
     tick and boot is the shipped behavior unchanged (the harness
     depends on this). Server mode: warm an in-memory cache here – the
     org list, the current org blob and its rev, the remember record,
     the admin record – then fire cb. Every synchronous Store getter
     serves from that warm cache afterward, so no other call site
     changes. Device-local prefs (getPref/setPref: zoom, sidebar state)
     stay on localStorage in every mode and may be read at eval time. */
  function ready(cb){ cb(); }

  return {
    raw:{ get:rawGet, set:rawSet, del:rawDel },
    orgKey:orgKey,
    readOrg:readOrg, orgRaw:orgRaw, writeOrg:writeOrg, removeOrg:removeOrg,
    patch:patch, setPath:setPath, removeRec:removeRec, commit:commit, persistActive:persistActive,
    dirtyRecords:function(){ return Object.keys(_dirty); }, clearDirty:function(){ _dirty={}; },
    refreshOrg:refreshOrg, orgRev:orgRev, checkRemote:checkRemote, startChangeSignal:startChangeSignal, ready:ready,
    mergeDirtyInto:mergeDirtyInto, handleStaleWrite:handleStaleWrite,
    schemaVersion:function(){ return SCHEMA_VERSION; },
    getOrgs:function(){ return readJSON(ORGS_KEY, []); },
    setOrgs:function(list){ return writeJSON(ORGS_KEY, list); },
    getCurrentOrg:function(){ return rawGet(CURRENT_ORG_KEY); },
    setCurrentOrg:function(id){ id ? rawSet(CURRENT_ORG_KEY, id) : rawDel(CURRENT_ORG_KEY); },
    getRemember:function(){ return readJSON(REMEMBER_KEY, null); },
    setRemember:function(o){ o ? writeJSON(REMEMBER_KEY, o) : rawDel(REMEMBER_KEY); },
    getAdmin:function(){ return readJSON(ADMIN_KEY, null); },
    setAdmin:function(c){ writeJSON(ADMIN_KEY, c); },
    getPref:function(name,f){ var v=rawGet(prefKey(name)); return v==null?f:v; },
    setPref:function(name,v){ rawSet(prefKey(name), v); }
  };
})();
(function(){if(Store&&Store.commit&&!Store.__gateHooked){var _c=Store.commit;Store.commit=function(){var r=_c.apply(Store,arguments);try{scheduleGateRefresh()}catch(e){}return r};Store.__gateHooked=true}})(); /* 1 Oct 2026 (QA Sweep 2, N-1): the gate refresh follows every commit */

function getOrgs(){return Store.getOrgs();}
function saveOrgs(list){Store.setOrgs(list);}
function getOrg(id){return getOrgs().filter(function(o){return o.id===id;})[0]||null}
var currentOrgId=null; // assigned in bootApp() — reading the store is a boot-time act
function setCurrentOrg(id){if(typeof UI!=='undefined'&&UI.trace&&id!==currentOrgId)traceCancel();currentOrgId=id;Store.setCurrentOrg(id);}
var currentPage='home',currentStep=null,currentPhase=null;
var coachOpen=false,notesOpen=false;
var UI={sec:'A',addForm:false,editIdx:null,assignOpen:null,orgAddForm:false,orgEditId:null,orgSelected:null,orgZoom:1};var UI_PRISTINE=JSON.stringify(UI); /* 1 Oct 2026 (Paul): the session's starting state, for a clean start at every change of organization or user */

