UI.navMore=false;
UI.zoom=(function(){try{var z=parseFloat(Store.getPref('zoom'));return(z&&z>=0.5&&z<=2.0)?z:1}catch(e){return 1}})();
function toggleNavMore(e){if(e)e.stopPropagation();UI.navMore=!UI.navMore;refreshNavMenus()}
function closeNavMore(){if(UI.navMore){UI.navMore=false;refreshNavMenus()}}
