  var branches='M '+X(0.42)+','+Y(0.46)+' L '+X(0.28)+','+Y(0.32)
    +' M '+X(0.42)+','+Y(0.40)+' L '+X(0.60)+','+Y(0.24)
    +' M '+X(0.42)+','+Y(0.56)+' L '+X(0.64)+','+Y(0.48)
    +' M '+X(0.42)+','+Y(0.52)+' L '+X(0.22)+','+Y(0.52);
