function localFlowDraw(sc){return buildLocalFlowSVG({ids:sc.ids,edges:sc.edges,picked:{},bright:{},pickable:{},ghost:false,anchor:sc.anchor,exactView:true})}
function localFlowKinds(comp,layerKey){var sc=localFlowViewScope(layerKey,comp,{}),seen={};sc.edges.forEach(function(e){seen[e.kind]=1});return allEdgeKinds().filter(function(k){return seen[k.k]})}
