function traceStart(appId){if(!compById(appId))return;provClearStaleTraceClaims();provRelease(traceOwner());UI.trace=traceInitialState(appId,null,null,0,false);traceBeat(); /* 5 Oct 2026 (Sweep 4R item 1): a trace beats the moment it starts, so its claim is never taken for stale */traceFirstInstructions();traceEnterLayer();render()}
