function tracePrevPicks(){var t=UI.trace;if(!t)return [];for(var i=t.hop-1;i>=0;i--){var p=t.picks[FLOW_HOPS[i].layer];if(p&&p.length)return p}return [t.anchorId||t.appId].filter(Boolean)}
