    if(!ccf||ccf.kind==='optmulti'||ccf.kind==='likert'||ccf.kind==='chklist'||ccf.kind==='stdlist'||ccf.kind==='derived'||ccf.kind==='cpgoals'||ccf.kind==='mgcriteria'||ccf.kind==='obsdesign'||ccf.kind==='rule'||ccf.kind==='igstd'||ccf.kind==='agrules'||ccf.kind==='jurmulti'||ccf.kind==='jurmark')return; /* JMAP (10 Sep 2026): tick-managed kinds */
    var ccReg=schemaRegister(ccs.registerPath),ccc=null;
    for(var cci=0;cci<ccReg.length;cci++){if(ccReg[cci].id===ccm[3]){ccc=ccReg[cci];break}}
    if(!ccc)return; if(ccm[1]==='dataEstate'&&ccm[2]==='tier'&&value==='Base system'&&dsHasSources(ccc)){if(!dsTierToBase(ccc)){ccc.tier='Derived store';var _te=document.getElementById('cc_'+f);if(_te){if(_te.removeAttribute)_te.removeAttribute('data-typed');_te.value='Derived store'}render();return}} /* P1R-06: a store with recorded sources becomes a base system only once the person has confirmed their deletion; cancelling leaves it a derived store */ ccc[ccm[2]]=value;
