/* ═══ COMPLETION ═══ */
function isStepDone(id){
  return !!(data.completedSteps && data.completedSteps[id]);
}

function getProgress(){var t=0,d=0;for(var i=0;i<4;i++){var ph=PH[i];for(var j=0;j<ph.steps.length;j++){t++;if(isStepDone(ph.steps[j].id))d++}}return{total:t,done:d,pct:t?Math.round(d/t*100):0}}

/* ═══ NAVIGATION ═══ */
var navHistory=[];
function go(page,step){if(page==='5.1'||(page==='step'&&step==='5.1')){page='phase5';step=undefined} /* 23 Sep 2026 (the Phase 5 review): 5.1 is the dashboard page wherever it is reached from */
  // Push current state to history before navigating
  if(currentPage)navHistory.push({page:currentPage,step:currentStep});
  if(navHistory.length>50)navHistory=navHistory.slice(-50);
  UI.auditMap=null; /* CL9: the 1.3 mirror flag never survives navigation — the stale-state leak Paul reproduced */
  if(step===undefined&&page!=='home'&&page!=='learn'&&page!=='readiness'&&page!=='insights'&&page!=='phase5'&&page!=='manage'&&page!=='archreview'&&page!=='archmap'&&page!=='archscores'&&page!=='stdData'&&page!=='dgreview'&&page!=='stdCompute'&&page!=='stdModel'&&page!=='stdInteg'&&page!=='stdApp'){ /* 3 Sep 2026: the standing Architecture Review page */
    var v=page;
    if(v.match(/^phase-(\d+)$/)){page='phaseHome';step=v.replace('phase-','');}
    else if(v.match(/^out-/)){page='outcome';step=v;}
    else if(v.match(/^\d+\.\d/)){page='step';step=v;}
  }
  currentPage=page;currentPhase=null;
  if(step)currentStep=step;else if(page!=='step'&&page!=='outcome')currentStep=null;
  if(currentStep){
    for(var i=0;i<PH.length;i++){
      for(var j=0;j<PH[i].steps.length;j++){if(PH[i].steps[j].id===currentStep){currentPhase=PH[i];break}}
      if(!currentPhase&&PH[i].outcomes){for(var k=0;k<PH[i].outcomes.length;k++){if(PH[i].outcomes[k].id===currentStep){currentPhase=PH[i];break}}}
      if(currentPhase)break;
    }
  }
  render();if(!_suppressScroll)window.scrollTo(0,0);_suppressScroll=false;
}
var _suppressScroll=false;
function goBack(){
  if(!navHistory.length){go('phase5');return} /* 8 Sep 2026: a page opened cold goes back to the dashboard */
  var prev=navHistory.pop();
  // Set state directly without pushing to history
  currentPage=prev.page;currentStep=prev.step;currentPhase=null;
  if(currentStep){
    for(var i=0;i<PH.length;i++){
      for(var j=0;j<PH[i].steps.length;j++){if(PH[i].steps[j].id===currentStep){currentPhase=PH[i];break}}
      if(!currentPhase&&PH[i].outcomes){for(var k=0;k<PH[i].outcomes.length;k++){if(PH[i].outcomes[k].id===currentStep){currentPhase=PH[i];break}}}
      if(currentPhase)break;
    }
  }
  render();window.scrollTo(0,0);
}
function backBtn(){return '<button onclick="goBack()" style="display:inline-flex;align-items:center;gap:6px;padding:6px 14px;font-size:13px;font-family:var(--mono);letter-spacing:.05em;cursor:pointer;border:1px solid rgba(var(--fg-rgb),.12);background:rgba(var(--fg-rgb),.03);color:var(--stone);margin-bottom:16px">\u2190 Back</button>'} /* 8 Sep 2026 (Paul's ruling): the one back button, on every page */

