function confirmStepDone(sid){if((data.completedSteps||{})[sid])return true;return confirm('Mark this step complete? This will notify the team and can\u2019t be undone.')}
function confirmSectionDone(s){if((data.completedSections||{})[s])return true;return confirm('Mark this section complete? This can\u2019t be undone.')}
function markStepDone(id,pre){if(isStepDone(id))return;if(!stepGateOpen(id,'markStepDone'))return; /* QA Sweep 2, N-1: a stale button cannot complete a step whose gate is false */ /* 30 Sep 2026 (QA Sweep 1, F-24): re-clicking a completed step writes nothing */if(!confirmStepDone(id))return;if(typeof pre==='function')pre(); /* 23 Sep 2026: a step's save runs only once its confirmation is accepted; a cancel changes nothing */data.completedSteps[id]=true;stampStepDone(id);saveData();render()}

function saveSection11(secId,quiet){
  if(!quiet&&!confirmSectionDone(secId))return; /* item 43, 15 Aug 2026 */
  if(!data.assessments)data.assessments={};var a=data.assessments;
  if(!a.context)a.context={};var ctx=a.context;
  if(!a.techBaseline)a.techBaseline={};var tb=a.techBaseline;
  if(secId==='A'){if(!ctx.purpose)ctx.purpose={};if($('ac_mission'))ctx.purpose.mission=val('ac_mission');if($('ac_priority1'))ctx.purpose.priority1=val('ac_priority1');if($('ac_priority2'))ctx.purpose.priority2=val('ac_priority2');if($('ac_priority3'))ctx.purpose.priority3=val('ac_priority3');if($('ac_aiStrategy'))ctx.purpose.aiStrategy=val('ac_aiStrategy')}
  if(secId==='B'){if(!ctx.people)ctx.people={};if($('ac_teamComp'))ctx.people.teamComp=val('ac_teamComp')}
  if(secId==='C'){if(!ctx.process)ctx.process={};/* keySystems saved via addItemList */}
  if(secId==='D'){if(!tb.data)tb.data={};}
  if(secId==='E'){if(!tb.compute)tb.compute={};/* deployment-model select cut 25 Aug 2026: asked on 1.3's assessment card; this tab is pure scoring */}
  if(secId==='F'){if(!tb.model)tb.model={};/* model section now Likert only */}
  if(!data.completedSections)data.completedSections={};
  data.completedSections[secId]=true;
  /* Auto roll-up removed 15 Aug 2026 (Rollout item 54 / Spec 11): section completion never
     stamps the step; 1.1 completes through its own done button like every other step. */
  // Auto-advance to next section
  var order='ABCDEFGH';
  var idx=order.indexOf(secId);
  if(!quiet&&idx<order.length-1)UI.sec=({A:'A',B:'BC',C:'BC'})[order[idx+1]]||'TECH'; /* advance lands on the next section's TAB; quiet (per-tab) saves skip it */
  if(quiet)return; /* 23 Sep 2026 (Paul): a per-tab save renders and scrolls once, in saveTab11; the page no longer jumps to the top after the last tab */
  saveData();render();window.scrollTo(0,0);
}
function completeAssessmentStep(){if(isStepDone('1.1'))return; /* F-24 */if(!'ABCDEFGH'.split('').every(function(k){return !!(data.completedSections||{})[k]}))return;if(!confirmStepDone('1.1'))return;stampStepDone('1.1');saveData();render()} /* 23 Sep 2026 (Paul): the module's own step confirmation, and the family's completeStep: stay on the step and render, so the Milestone card appears beneath the button */
function saveTab11(tab){ /* per-tab Mark Complete, ruled 25 Aug 2026 */
  var map={A:['A'],BC:['B','C'],TECH:['D','E','F','G','H']};var secs=map[tab]||[];if(secs.length&&secs.every(function(x){return (data.completedSections||{})[x]}))return; /* F-24: an already-complete tab writes nothing */
  if(!secs.every(function(x){return (data.completedSections||{})[x]})&&!confirm('Mark this section complete? This can\u2019t be undone.'))return; /* the family sentence verbatim (Paul, 25 Aug 2026: no special status for grouped sections) */
  secs.forEach(function(x){saveSection11(x,true)});
  var nxt={A:'BC',BC:'TECH'}[tab];if(nxt)UI.sec=nxt;
  saveData();render();if(nxt)scrollToTabs(); /* 23 Sep 2026 (Paul): the next tab opens with the tab bar at the top of the view; the last tab does not move the page */
}


