  h+='<div style="flex:1"><div style="font-size:14px;font-weight:600;color:var(--paper)">'+esc(comp.name||'Unnamed')+'</div><div style="font-size:12px;color:var(--stone)">'+esc(st.sub||'')+'</div></div>';
