function aiToolCountFlag(){
  var nh=(data.identities||{}).nonHuman||{};
  var raw=(nh.aiTools==null?'':String(nh.aiTools)).trim();
  if(!raw)return'';
  var manual=countOf(raw);
  if(manual===null)return'';
  var nModels=(data.aiModels||[]).length;
  var nAgents=(data.agentRegistry||[]).length;
  var auto=nModels+nAgents;
  if(manual===auto)return'';
  if(!UI.aiCountDismissed)UI.aiCountDismissed={};
  var key='aitools|'+manual+'|'+auto;
  if(UI.aiCountDismissed[key])return'';
  var src=nModels+' in the AI Model Inventory, '+nAgents+' registered AI agent'+(nAgents===1?'':'s');
  return'<div class="ai-count-flag" data-aikey="'+key+'" style="margin:12px 0 4px;padding:12px 14px;background:rgba(122,107,74,.08);border-left:3px solid #7A6B4A;font-size:13px;color:var(--stone);display:flex;gap:12px;align-items:flex-start"><div style="flex:1;line-height:1.55">You entered <strong style="color:var(--paper)">'+manual+'</strong> AI tool'+(manual===1?'':'s')+' with access, but your inventories so far hold <strong style="color:var(--paper)">'+auto+'</strong> ('+src+'). It is worth checking that these line up.</div><button onclick="dismissAiCountFlag(this)" title="Dismiss" style="background:none;border:none;color:var(--stone);cursor:pointer;font-size:18px;line-height:1;padding:0 2px;flex-shrink:0">×</button></div>';
}
function dismissAiCountFlag(btn){
  if(!UI.aiCountDismissed)UI.aiCountDismissed={};
  var w=btn;while(w&&(' '+(w.className||'')+' ').indexOf(' ai-count-flag ')<0)w=w.parentNode;
  if(!w)return;
  UI.aiCountDismissed[w.getAttribute('data-aikey')]=1;
  w.style.display='none';
}

