function vendorProductDel(ref,name){var i=(function(){var L=data.vendors||[];for(var q=0;q<L.length;q++){if(L[q]&&L[q].id===ref)return q}return -1})();if(i<0)return; /* by id */var pi=vendorProducts((data.vendors||[])[i]).indexOf(name);if(pi<0)return;if(lockBlocked('vendors::'+ref))return; /* 28 Sep 2026: the vendor's own lock (a guard on the whole list could never meet a lock, since vendor fields lock by id) */ /* 23 Sep 2026 (the Phase 4 review): button-driven writes respect the record's lock */var v=(data.vendors||[])[i];if(!v)return;var ps=vendorProducts(v);var gone=ps.splice(pi,1)[0];v.products=ps;['reviewedProducts','aiProducts'].forEach(function(k){if(Array.isArray(v[k]))v[k]=v[k].filter(function(x){return x!==gone})});Store.commit('vendors',v.id);render()}
function vendorProdTick(ref,key,name,on){var i=(function(){var L=data.vendors||[];for(var q=0;q<L.length;q++){if(L[q]&&L[q].id===ref)return q}return -1})();if(i<0)return; /* by id */var pi=vendorProducts((data.vendors||[])[i]).indexOf(name);if(pi<0)return;if(lockBlocked('vendors::'+ref))return; /* 28 Sep 2026: the vendor's own lock (a guard on the whole list could never meet a lock, since vendor fields lock by id) */ /* 23 Sep 2026 (the Phase 4 review): button-driven writes respect the record's lock */var v=(data.vendors||[])[i];if(!v)return;var p=vendorProducts(v)[pi];if(!p)return;var arr=Array.isArray(v[key])?v[key].slice():[];var k=arr.indexOf(p);if(on&&k<0)arr.push(p);if(!on&&k>=0)arr.splice(k,1);v[key]=vendorProducts(v).filter(function(x){return arr.indexOf(x)>=0});Store.commit('vendors',v.id);render()}
