/* riskCallout retired 8 Sep 2026 (Paul's ruling): the From-your-risk-map insets are gone from every step */
var RISK_SCENARIOS=[
    {id:'hallucination',name:'Model Hallucination with Downstream Effect', /* AJ (Paul, 29 Aug 2026) */desc:'An AI model produces a confidently wrong output, and that output triggers an automated downstream action before any person reviews it.',q:'Where in your architecture could an AI output trigger an automated action without human review? What is the worst that could happen?'},
    {id:'credential',name:'AI Agent Credential Compromise',desc:'An AI agent operating in your environment has its credentials compromised. The route could be a breach at the AI provider, privileges that accumulated over time, or a supply-chain attack.',q:'What AI tools currently have access to your internal systems? What is the worst an attacker could do if the most privileged of those tools were compromised?'},
    {id:'cascade',name:'Cascade Failure from Shared Dependencies',desc:'Two or more AI applications that appear independent share an underlying data source or infrastructure component. When that shared dependency fails, the systems that depend on it can fail at the same time.',q:'Which of your systems share data sources or infrastructure? What is the worst chain of failures if that shared component goes down?'},
    {id:'dataQuality',name:'Data Quality Poisoning',desc:'AI systems are deployed on data that appears clean but contains systematic quality problems: duplicated records, inconsistent definitions, outdated information, or training data that carries historical biases.',q:'Where in your data estate are you least confident about quality? What is the worst decision AI could make from that data?'},
    {id:'ceiling',name:'Architectural Ceiling',desc:'The organization identifies a high-value AI use case, but the current architecture cannot support it. The data might not be accessible, the integrations might not exist, the compute might not be available, or the identity architecture might not be able to handle AI agents.',q:'What AI initiatives are you planning that your current architecture cannot support? What specific gaps would block them?'}
  ];
/* 23 Sep 2026, Phase 1 R16/R17: user-created records carry the same IDs as reports. */
function ensureRiskRecord(i){if(!RISK_SCENARIOS[i])return null;if(!data.riskScenarios)data.riskScenarios=[];for(var j=0;j<=i;j++){var _rc=false;if(!data.riskScenarios[j]){data.riskScenarios[j]={};_rc=true}if(!data.riskScenarios[j].id){data.riskScenarios[j].id=RISK_SCENARIOS[j].id;_rc=true}if(_rc)Store.commit('riskScenarios',data.riskScenarios[j].id)} /* 28 Sep 2026 (Paul: conform to the family standard, Rollout item 9): a record is named only when it is created or given its id */return data.riskScenarios[i]}
/* 30 Sep 2026 (Paul): migrateRiskIds removed — switched off alone, it changed no record the current build creates */
function riskScoredCount(){return RISK_SCENARIOS.filter(function(sc){var r=(data.riskScenarios||[]).find(function(x){return x&&x.id===sc.id});return r&&['likelihood','impact','timeHorizon'].every(function(k){return +r[k]>=1&&+r[k]<=5})}).length}
function riskScenariosBody(){ /* 4 Sep 2026 (Paul's browser pass): 1.4's scenario cards, factored so the dashboard's Risk Scenarios register renders the same cards; the Save button and saveRiskScenarios come with them */
  var SCENARIOS=RISK_SCENARIOS;var scenarios=data.riskScenarios||[];if(!scenarios.length)scenarios=SCENARIOS.map(function(s){return{id:s.id,likelihood:0,impact:0,timeHorizon:0,notes:''}});var h='';
  SCENARIOS.forEach(function(sc,i){
    var scored=scenarios[i]||{};
    var composite=(scored.likelihood||0)+(scored.impact||0)+(scored.timeHorizon||0);
    h+='<div id="scenario_'+i+'"></div>';h+=card('<h3 style="font-size:15px;font-weight:700;margin:0 0 4px;color:var(--paper)">Scenario '+(i+1)+': '+sc.name+'</h3><div style="padding:10px 14px;background:rgba(90,125,138,.06);border-left:3px solid var(--gold);margin:10px 0 20px;font-size:14px;color:var(--text-body);line-height:1.6"><strong>The scenario:</strong> '+sc.desc+'</div>' /* 23 Sep 2026 (Paul): the scenario inside the box; the organization's questions under their heading, below */+likert('Likelihood','riskScenarios.'+i+'.likelihood',scored.likelihood,'Very unlikely','Very likely')+likert('Impact','riskScenarios.'+i+'.impact',scored.impact,'Minor','Catastrophic')+likert('Time horizon','riskScenarios.'+i+'.timeHorizon',scored.timeHorizon,'Years away','Imminent')+ta('How does this apply to your organization?','rs_notes_'+i,scored.notes,'',3).replace('</label>','</label><p style="font-size:14px;color:var(--text-body);line-height:1.6;margin:2px 0 8px">'+sc.q+'</p>')+(composite?'<div style="text-align:right;font-family:var(--mono);font-size:13px;color:'+(composite>=12?'#9B2D3F':composite>=8?'#8B5E3C':'var(--stone)')+'">Composite: '+composite+'/15</div>':''))
  });
  h+='<div style="margin-top:8px">'+btn('Save scores','saveRiskScenarios();render()','bp','font-size:13px')+'</div>';
  return h;
}
function renderStep15(){
  var scenarios=data.riskScenarios||[];
  var done15=isStepDone('1.4'); /* FOLD: the risk step is 1.4 now */
  var SCENARIOS=RISK_SCENARIOS;

  var h='<h2 style="font-size:22px;font-weight:700;margin:0 0 4px">Architectural Risk Scenarios</h2><p style="color:var(--text-faint);margin:8px 0 20px;line-height:1.6;font-size:14px">Work through the worst cases before they happen. For each scenario, assess how likely it is in your organization, how severe the consequences would be, and how soon it could happen.</p>';
  /* AP2 OFF (29 Aug 2026): Aurora dormant, kept for restoration */ // h+=auroraToggle('1.4','<p style="margin:0 0 8px"><strong>Aurora Windows — Architectural Risk.</strong> Aurora scores five failure scenarios against what its own inventories just exposed, not in the abstract.</p><ul style="margin:0 0 8px;padding-left:20px"><li style="margin-bottom:5px"><strong>Data-quality poisoning</strong> and <strong>architectural ceiling</strong> score highest. Aurora\'s planned AI quoting engine — the initiative behind its revenue growth target — would run on customer-pricing data that currently sits in three systems that don\'t agree with each other. Aurora scores the ceiling 14/15: the architecture can\'t carry the engine until the data and integrations beneath it are fixed.</li><li style="margin-bottom:5px"><strong>Credential compromise</strong> scores high for a concrete reason: Aurora\'s audit turned up unmanaged API keys and a dozen-plus ungoverned ChatGPT sessions reaching company data. "What would an attacker gain?" is no longer hypothetical.</li><li style="margin-bottom:5px"><strong>Hallucination-with-action</strong> and <strong>cascade failure</strong> score lower today only because so little is automated yet — which itself becomes a warning as Aurora connects more systems.</li></ul><p style="margin:8px 0 0">Each score is anchored to something the audit actually found, and the two highest are the gaps to close first.</p>');
  if(!scenarios.length)scenarios=SCENARIOS.map(function(s){return{id:s.id,likelihood:0,impact:0,timeHorizon:0,notes:''}});
  h+=riskScenariosBody();
  var count=riskScoredCount(),allScored=count===RISK_SCENARIOS.length;
  h+=doneBtn('markStepDone(\'1.4\',saveRiskScenarios)',!allScored,null,isStepDone('1.4'),'Score all five scenarios to complete this step ('+count+' of 5 scored).');
  return h;
}

function saveRiskScenarios(){for(var _ri=0;_ri<RISK_SCENARIOS.length;_ri++){var _rk='riskScenarios::'+RISK_SCENARIOS[_ri].id;if(Collab.lockedByOther(_rk)&&document.getElementById('rs_notes_'+_ri)){lockBlocked(_rk);return}} /* 28 Sep 2026 (Paul: lock coverage, Rollout items 10 and 53) */RISK_SCENARIOS.forEach(function(sc,i){var el=document.getElementById('rs_notes_'+i);if(el&&el.tagName==='TEXTAREA'){var r=ensureRiskRecord(i);if(r.notes!==el.value){r.notes=el.value;Store.commit('riskScenarios',r.id)}}else if((data.riskScenarios||[])[i])ensureRiskRecord(i)}); /* 28 Sep 2026 (Paul: conform to the family standard, Rollout item 9) */}

