var SECTION_MIN={ /* 23 Sep 2026 (Paul, the Phase 2 review): one coherent minimum per section; an explicit answer (Keep as is, None, No) counts, a blank never does */
  '2.2_compute':function(){var cp=data.computePlan||{},m=[];if(!cp.targetModel)m.push('choose the target compute model');if(!(cp.goals||[]).some(function(x){return String(x||'').trim()}))m.push('write at least one compute goal');return m},
  '2.2_governance':function(){var mg=data.modelGovernance||{},m=[];if(!(mg.criteriaList||[]).length)m.push('write at least one evaluation criterion');if(!String(mg.guardrails||'').trim())m.push('write the guardrails');return m},
  '2.2_review':function(){var n=(data.aiModels||[]).filter(function(x){return x.usage!=='Shadow'&&!modelReviewed(x)}).length; /* a model in shadow use is governed by its 2.4 shadow verdict, not by the criteria review */return n?['give '+(n===1?'the remaining model':'each of the '+n+' remaining models')+' a criteria answer or an approval decision']:[]},
  '2.3_apis':function(){return String((data.apiPolicy||{}).default||'').trim()?[]:['write the default rule for new connections']},
  '2.3_circuit':function(){var cb=data.circuitBreakers||{},m=[];if(!String(cb.detection||'').trim())m.push('write how a failure is detected');if(!String(cb.recovery||'').trim())m.push('write how the connection recovers');return m},
  '2.3_retire':function(){var n=(data.integrations||[]).filter(function(g){return !g.retireVerdict}).length;return n?['give '+(n===1?'the remaining connection':'each of the '+n+' remaining connections')+' a verdict (Keep as is, Modernize or Retire)']:[]},
  '2.4_governance':function(){var g=agEnsure()||{},m=[];if(!g.mode)m.push('choose minimum standards or flexible guidelines');if(!(g.principles||[]).some(function(p){return String(typeof p==='string'?p:(p&&p.text)||'').trim()}))m.push('write at least one rule');return m},
  '2.4_review':function(){var a=(data.aiApplications||[]).filter(function(x){return !x.oversight}).length,b=(data.agentRegistry||[]).filter(function(x){return x.appId&&!x.humanLoop}).length,m=[];if(a)m.push('answer human oversight for '+(a===1?'the remaining application':'the '+a+' remaining applications'));if(b)m.push('answer whether a person is in the loop for '+(b===1?'the remaining workflow or agent':'the '+b+' remaining workflows and agents'));return m},
  '2.6_identity':function(){return countOf(((data.identities||{}).human||{}).totalAccounts)===null?['enter the total number of user accounts']:[]},
  '2.6_zt':function(){var ip=data.identityPlan||{},m=[];if(!String(ip.lifecycle||'').trim())m.push('write the identity lifecycle policy');if(!String(ip.pam||'').trim())m.push('write the privileged access policy');return m}
};
function step21Missing(){var dg=data.dataGovernance||{},m=[];if(!dg.cadence)m.push('set the review\u2019s cadence');if(!String(dg.authority||'').trim())m.push('write what the review may decide');if(!(dg.domains||[]).length)m.push('define at least one data domain');return m}
function tabDoneBtn(tabKey,saveFn,nextTab,stepPartKey,stepDoneId,gateReady){ return '<span data-gate="tabdone-'+escAttr(String(tabKey))+'" style="display:contents">'+tabDoneBtnInner(tabKey,saveFn,nextTab,stepPartKey,stepDoneId,gateReady)+'</span>'; } /* 5 Oct 2026 (Sweep 4R item 16, N-3): every tab's section button and helper refresh in place after a typed change */ function tabDoneBtnInner(tabKey,saveFn,nextTab,stepPartKey,stepDoneId,gateReady){ /* 23 Sep 2026 (Paul): a tab's button completes its tab and nothing more, as a family section button; the step is completed by its own button at the step's foot (tabbedStepFoot). stepDoneId and gateReady are kept in the signature for the callers and no longer used. */
  if(!data.completedTabs)data.completedTabs={};
  var done=data.completedTabs[tabKey];
  if(done)return doneBtn('',false,null,true,null,'section');
  var _miss=SECTION_MIN[tabKey]?SECTION_MIN[tabKey]():[];if(_miss.length)return doneBtn('',true,null,false,'To complete this section: '+_miss.join('; ')+'.','section');
  var advance=nextTab?stepPartKey+'=\''+nextTab+'\';':'';
  var act='if(!confirmTabDone(\''+tabKey+'\'))return;'+(saveFn?saveFn+';':'')+'if(!data.completedTabs)data.completedTabs={};data.completedTabs[\''+tabKey+'\']=true;'+advance+'saveData();render()'+(nextTab?';scrollToTabs()':'');
  return doneBtn(act,false,null,false,null,'section');
}
function confirmTabDone(k){if((data.completedTabs||{})[k])return true;if(SECTION_MIN[k]&&SECTION_MIN[k]().length)return false; /* QA Sweep 2, N-1: the section's own minimum, checked at the click */return confirm('Mark this section complete? This can\u2019t be undone.')} /* the family's section sentence */
var TABBED_STEPS={'1.3':['1.3_data','1.3_compute','1.3_model','1.3_orch','1.3_app'],'2.2':['2.2_compute','2.2_governance','2.2_review'],'2.3':['2.3_apis','2.3_circuit','2.3_retire'],'2.4':['2.4_governance','2.4_review'],'2.6':['2.6_identity','2.6_zt']}; /* 23 Sep 2026: the steps whose work is divided into tabs, each tab completed in its own right */
function tabbedStepFoot(sid){var ks=TABBED_STEPS[sid];if(!ks)return'';var ct=data.completedTabs||{};var all=ks.every(function(k){return !!ct[k]});var nw=ks.length===2?'both':'all '+({3:'three',4:'four',5:'five'}[ks.length]||String(ks.length));return doneBtn('completeTabbedStep(\''+sid+'\')',!all,null,isStepDone(sid),'Complete '+nw+' tabs to mark this step complete.','step')}
function completeTabbedStep(sid){if(isStepDone(sid))return; /* QA Sweep 2: F-24's remainder — an already-complete step writes nothing */if(!stepGateOpen(sid,'completeTabbedStep'))return; /* QA Sweep 2, N-1 */var ks=TABBED_STEPS[sid]||[];var ct=data.completedTabs||{};if(!ks.every(function(k){return !!ct[k]}))return;if(!confirmStepDone(sid))return;stampStepDone(sid);saveData();render()} /* the family's completeStep: confirm, stamp, stay and render so the Milestone card appears */
