/* \u2500\u2500 The identity baseline joins the zero-trust plan (Paul's ruling, 7 Sep 2026): each problem count draws its conclusion, and the plan offers an initiative for each non-zero count \u2500\u2500 */
function countOf(v){var t=String(v==null?'':v).trim();if(!t)return null;if(/^\d+$/.test(t)||/^\d{1,3}(,\d{3})+$/.test(t)||/^\d{1,3}( \d{3})+$/.test(t))return parseInt(t.replace(/[, ]/g,''),10);return null} /* 23 Sep 2026 (the Phase 2 review): a count is a whole number, with or without thousands separators; a range, a decimal, a negative or an estimate is not read as a count, never turned into a different number */
function idNum(v){return countOf(v)}
function idCountWarn(v){var t=String(v==null?'':v).trim();return (t&&countOf(t)===null)?'<p style="font-size:12px;color:#8B5E3C;margin:-8px 0 12px">Not read as a count. Enter a whole number, such as 1,200; ranges and estimates are not counted.</p>':''}
var ID_CONCLUSIONS=[
  {k:'human.sharedAccounts',label:'shared accounts',conclusion:'A shared account is an identity nobody owns: when it acts, no one can say who acted.',initiative:'Replace every shared account with individual, governed identities.',desc:'Retire each shared login and issue each user an identity of their own, with access reviewed on the way.'},
  {k:'human.dormantAccounts',label:'dormant accounts',conclusion:'A dormant account can still be used long after the reason for it has gone, and nobody is watching it.',initiative:'Disable every account unused for more than ninety days, and make it automatic.',desc:'Retire the dormant accounts found at the baseline and tie deactivation to the HR leaver process so new ones do not accumulate.'},
  {k:'nonHuman.apiKeys',label:'API keys in use',conclusion:'A key stays valid until someone makes it expire. Each key needs an owner, a scope, and a rotation schedule.',initiative:'Bring every API key under management: a named owner, a scoped permission, and scheduled rotation.',desc:'Inventory the keys, retire the ones nobody claims, and put the rest in a managed store with rotation.'},
  {k:'nonHuman.aiTools',label:'AI tools with access to internal systems',conclusion:'Every AI tool with access is a non-human identity acting on your systems. Each AI tool should appear on the census and log in as itself.',initiative:'Reconcile the AI tools with access against the census, and give each a governed identity of its own.',desc:'Match the count here to the models and agents on the map; anything missing is shadow use to be recorded, and anything on borrowed credentials moves to its own identity.'}];
function idConclusions(){var ids=data.identities||{};return ID_CONCLUSIONS.map(function(c){var parts=c.k.split('.');var v=idNum((ids[parts[0]]||{})[parts[1]]);return {k:c.k,label:c.label,n:v,conclusion:c.conclusion,initiative:c.initiative,desc:c.desc}}).filter(function(c){return c.n!==null&&c.n>0})}
function ztSuggested(){var ip=data.identityPlan||{};var have=(ip.ztInitiatives||[]).map(function(z){return (z.name||'').toLowerCase()});return idConclusions().filter(function(c){return !have.some(function(nm){return nm===c.initiative.toLowerCase()})})}
function ztAcceptSuggestion(key){if(lockBlocked('identityPlan'))return;var sug=ztSuggested().find(function(c){return c.k===key});if(!sug)return; /* 23 Sep 2026 (stable identity R2): a suggestion is accepted by its conclusion's key; the list shrinks as suggestions are accepted, so a position could accept the next one, and a suggestion already accepted is no longer offered */if(!data.identityPlan)data.identityPlan={};var ip=data.identityPlan;if(!ip.ztInitiatives)ip.ztInitiatives=[];ip.ztInitiatives.push({id:newUserCid(),name:sug.initiative,description:sug.desc,owner:'',date:'',status:'',timeline:''});Store.commit('identityPlan');render()}
function ztEnsure(){if(!data.identityPlan)data.identityPlan={};var ip=data.identityPlan;if(!ip.ztInitiatives)ip.ztInitiatives=[];ip.ztInitiatives.forEach(function(z){if(!z.id)z.id=newCid()});return ip}
function ztInitBody(ctx){ /* 7 Sep 2026 (Paul's ruling): the zero-trust initiatives as dated, owned steps with a status \u2014 the same form as the compute strategy plan; rendered at 2.5 and in the dashboard fold */
  var ip=ztEnsure();var today=todayIso();var h='';
  if(!ip.ztInitiatives.length)h+='<p style="font-size:13px;color:var(--stone);margin:0 0 8px">No initiative yet.</p>';
  ip.ztInitiatives.forEach(function(z){var xid='zti_'+z.id;var xo=UI.expandEdit===xid;var late=z.status!=='Done'&&z.date&&z.date<today;var col=z.status==='Done'?'#3D6B6E':late?'#6E4A5A':z.status==='Under way'?'#7A6B4A':'rgba(var(--fg-rgb),.25)';
    h+='<div style="border-left:3px solid '+col+';margin-bottom:4px;background:rgba(var(--fg-rgb),.02)"><div style="display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:center;padding:8px 12px">';
    h+='<div onclick="UI.expandEdit=UI.expandEdit===\''+xid+'\'?null:\''+xid+'\';render()" style="cursor:pointer"><div style="font-size:13px;font-weight:600;color:var(--paper)">'+(z.name?esc(z.name):'<span style="color:var(--stone)">New initiative</span>')+'</div><div style="font-size:11px;color:var(--stone);margin-top:2px">'+(z.owner?esc(z.owner):'No owner')+' \u00B7 '+(z.date?'target '+fmtD(z.date):(z.timeline?esc(z.timeline):'no target date'))+(late?' \u00B7 <span style="color:#6E4A5A;font-weight:600">past target</span>':'')+'</div></div>';
    h+='<select id="zti_'+z.id+'_status" onchange="fldSave(this.id,this.value)" style="font-size:12px;padding:4px 6px">'+[['','Not started'],['Under way','Under way'],['Done','Done']].map(function(o){return '<option value="'+o[0]+'"'+((z.status||'')===o[0]?' selected':'')+'>'+o[1]+'</option>'}).join('')+'</select>';
    h+='<span onclick="UI.expandEdit=UI.expandEdit===\''+xid+'\'?null:\''+xid+'\';render()" style="cursor:pointer;font-size:12px;color:var(--stone)">'+(xo?'\u25BE':'\u25B8')+'</span></div>';
    if(xo)h+='<div style="padding:4px 14px 12px;border-top:1px solid rgba(var(--fg-rgb),.06)">'+ta('Initiative','zti_'+z.id+'_name',z.name||'','What will be done.',1)+ta('What it accomplishes','zti_'+z.id+'_description',z.description||'','',2)+'<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:start"><div>'+ta('Owner','zti_'+z.id+'_owner',z.owner||'','Name and role',1)+'</div><div>'+dateField('Target date','zti_'+z.id+'_date',z.date||'','')+'</div></div>'+(z.timeline&&!z.date?'<p style="font-size:11px;color:var(--stone);margin:-6px 0 8px">Written before dates were required: \u201c'+esc(z.timeline)+'\u201d. Set the target date above.</p>':'')+'<div>'+btn('Remove','ztInitDel(\''+z.id+'\')','bg2','font-size:11px;padding:3px 10px;color:#6E4A5A')+'</div></div>';
    h+='</div>'});
  h+='<div style="margin-top:6px">'+btn('+ Add an initiative','ztInitAdd()','bs','font-size:12px')+'</div>';
  return h;
}
function ztInitAdd(){if(lockBlocked('identityPlan'))return; /* 28 Sep 2026 (Paul: lock coverage, Rollout items 10 and 53) */var ip=ztEnsure();var id=newUserCid();ip.ztInitiatives.push({id:id,name:'',description:'',owner:'',date:'',status:'',timeline:''});Store.commit('identityPlan');UI.expandEdit='zti_'+id;render()}
function ztInitDel(id){if(lockBlocked('identityPlan'))return; /* 28 Sep 2026 (Paul: lock coverage, Rollout items 10 and 53) */var ip=ztEnsure();if(!confirm('Remove this initiative?'))return;ip.ztInitiatives=ip.ztInitiatives.filter(function(z){return z.id!==id});Store.commit('identityPlan');render()}
function ztFigures(){var ip=ztEnsure();var today=todayIso();var zs=(ip.ztInitiatives||[]).filter(rowHasContent); /* QA Sweep 3, N-11: only rows with content */return{total:zs.length,done:zs.filter(function(z){return z.status==='Done'}).length,under:zs.filter(function(z){return z.status==='Under way'}).length,late:zs.filter(function(z){return z.status!=='Done'&&z.date&&z.date<today}).length,noOwner:zs.filter(function(z){return !(z.owner&&String(z.owner).trim())}).length}}
function dashZtBody(){var f=ztFigures();var h=gloss('The zero-trust initiatives, with their owners, target dates, and status. The Architecture Review checks them alongside the sovereignty program.');return h+ztInitBody('dashboard')}
function renderStep26(){
  if(!data.identityPlan)data.identityPlan={};var ip=data.identityPlan;
  if(!ip.ztInitiatives)ip.ztInitiatives=[];
  if(!data.agentRegistry)data.agentRegistry=[];
  if(!data.shadowRemediation)data.shadowRemediation=[];
  var ct=data.completedTabs||{};

  var h='<h2 style="font-size:22px;font-weight:700;margin:0 0 4px">Zero-Trust Architecture</h2><p style="color:var(--text-faint);margin:8px 0 20px;line-height:1.6;font-size:14px">Count every identity that can reach your systems, human and non-human, and judge how well each kind is governed. Then plan the move toward zero-trust, where nothing is trusted by default and every request is verified, as initiatives with owners and target dates. The identities your agents log in with are recorded at Step 2.4. The plan here covers them all.</p>';
  /* 7 Sep 2026 (Paul's ruling): the risk-map inset retired from every Phase 2 step; too narrow to earn its place */
  /* AP2 OFF (29 Aug 2026): Aurora dormant, kept for restoration */ // h+=auroraToggle('2.6','<p style="margin:0 0 8px"><strong>Aurora Windows — Identity & Security.</strong> Aurora brings its machines and tools under the same discipline as its people.</p><ul style="margin:0 0 8px;padding-left:20px"><li style="margin-bottom:5px"><strong>Zero trust</strong> — it assesses its maturity (low to start) and picks the initiatives that move it most: scoped credentials, an identity lifecycle, and privileged-access management for those shared admin accounts.</li><li style="margin-bottom:5px"><strong>Agent identities</strong> — the AI tools acting in Aurora\'s systems each get a distinct, monitored identity with scoped access, instead of borrowing a person\'s login or an unmanaged key.</li><li style="margin-bottom:5px"><strong>Shadow AI verdicts</strong> — every unsanctioned tool gets one decision, with an owner and a date: the dozen-plus staff on personal ChatGPT are moved onto a governed enterprise account; an unsanctioned browser extension summarizing customer calls is prohibited.</li></ul><p style="margin:8px 0 0">Every verdict carries an owner and a date. "Deal with it later" is not one of the options.</p>');
  /* P24 (Paul's ruling, 30 Aug 2026): the baseline becomes the FIRST tab — the two layered pages resolve into one tabbed page. The census still opens the step, now as its opening tab. */
  var part=UI.step26Part||'identity';
  h+='<div class="step-tabs" style="display:flex;gap:8px;margin-bottom:24px;flex-wrap:wrap">';
  [{id:'identity',l:'Identity Baseline',k:'2.6_identity'},{id:'zerotrust',l:'Zero-Trust Plan',k:'2.6_zt'}].forEach(function(t){
    h+='<button onclick="UI.expandEdit=null;UI.step26Part=\''+t.id+'\';render()" class="btn '+(part===t.id?'bp':'bs')+'">'+(ct[t.k]?'\u2713 ':'')+t.l+'</button>';
  });
  h+='</div>';
  if(part==='identity'){
    h+=renderIdentityBaseline();
    (function(){var cs=idConclusions();if(!cs.length)return;h+='<h3 style="font-size:15px;font-weight:700;margin:24px 0 8px">What the Counts Say</h3>'+gloss('The counts above that call for action, and why. The Zero-Trust Plan offers an initiative for each.');cs.forEach(function(c){h+='<div style="border-left:3px solid #6E4A5A;padding:8px 12px;margin-bottom:4px;background:rgba(var(--fg-rgb),.02)"><div style="font-size:13px;font-weight:600;color:var(--paper)">'+c.n+' '+c.label+'</div><div style="font-size:12px;color:var(--stone);line-height:1.5">'+esc(c.conclusion)+'</div></div>'})})(); /* 7 Sep 2026 (Paul's ruling): the baseline draws its conclusions */
  }

  if(part==='zerotrust'){
    h+='<h3 style="font-size:15px;font-weight:700;margin:0 0 12px">Zero-Trust Plan</h3>';
    h+=gloss('Zero-trust means that no user, device, or system is trusted automatically. Every access request is verified, every session is monitored, and privileges are limited to the minimum required.');
    h+=card(likert('Current zero-trust maturity','identityPlan.ztMaturity',ip.ztMaturity,'No zero-trust','Fully implemented','Where does your organization fall today? 1 = traditional perimeter security. 5 = every access request is verified regardless of origin.')+ta('Identity lifecycle policy','ipf_lifecycle',ip.lifecycle||'','How identities are created, reviewed, and decommissioned across the organization.',3)+ta('Privileged access management','ipf_pam',ip.pam||'','How elevated access is requested, granted, monitored, and revoked.',3));
    (function(){var sg=ztSuggested();if(!sg.length)return;h+='<h4 style="font-size:14px;font-weight:700;margin:24px 0 8px">Suggested from the Identity Baseline</h4>'+gloss('Each of these answers a count on the Identity Baseline. Add the ones you accept, and edit them as you like.');sg.forEach(function(c,i){h+='<div style="display:flex;justify-content:space-between;align-items:center;gap:12px;border-left:3px solid #7A6B4A;padding:8px 12px;margin-bottom:4px;background:rgba(var(--fg-rgb),.02)"><div><div style="font-size:13px;color:var(--paper)">'+esc(c.initiative)+'</div><div style="font-size:11px;color:var(--stone)">'+c.n+' '+c.label+' at the baseline</div></div>'+btn('+ Add','ztAcceptSuggestion(\''+c.k+'\')','bs','font-size:11px;padding:3px 10px;white-space:nowrap')+'</div>'})})(); /* 7 Sep 2026 (Paul's ruling): the plan offers an initiative for each problem count */
    h+='<h4 style="font-size:14px;font-weight:700;margin:24px 0 8px">Zero-Trust Initiatives ('+ip.ztInitiatives.filter(rowHasContent).length+')</h4>';
    h+=gloss('Add the initiatives that move your zero-trust maturity. Each has a name, what it accomplishes, an owner, and a target date. One initiative most organizations need: review how every AI agent and workflow logs in, as recorded at Step 2.4, against the lifecycle and privileged-access policies above.');
    h+=ztInitBody('2.6'); /* 7 Sep 2026 (Paul's ruling): initiatives as dated, owned steps */
    h+=tabDoneBtn('2.6_zt','saveZtOrgData()',null,null,'2.6',ct['2.6_identity']); /* 7 Sep 2026 (Paul's ruling): two tabs; the plan closes the step */ /* 7 Sep 2026 (Paul's ruling): the agent registry tab retired; the agent's identity is set on its card at 2.4 */
  }




  return h;
}
