function saveMgCritEdit(ref){if(lockBlocked('modelGovernance'))return; /* 23 Sep 2026 (the Phase 2 re-audit) */mgEnsureCriteria();var i=(function(){var L=(data.modelGovernance||{}).criteriaList||[];for(var q=0;q<L.length;q++){if(L[q]&&L[q].id===ref)return q}return -1})();if(i<0)return; /* 23 Sep 2026 (stable identity R2): addressed by the criterion's id */var c=data.modelGovernance.criteriaList[i];if(!c)return;var _cb=recSig(c); /* F-42 */if($('mcr_e_title')){var _mt=String(val('mcr_e_title')||'').trim();if(_mt)c.title=_mt} /* QA Sweep 3: a criterion is not renamed to blank */if($('mcr_e_desc'))c.desc=val('mcr_e_desc');if($('mcr_e_owner'))c.owner=val('mcr_e_owner');UI.expandEdit=null;if(recSig(c)!==_cb)Store.commit('modelGovernance'); /* F-42: nothing changed, nothing written */render()} /* CL4 */
