function arRR(){if(!data.reviewResults)data.reviewResults={};var rr=data.reviewResults;if(!rr.walk||typeof rr.walk!=='object')rr.walk={};if(!rr.rescores)rr.rescores={};['data','compute','model','orchestration','application'].forEach(function(k){if(typeof rr.rescores[k]==='number')rr.rescores[k]={};if(!rr.rescores[k])rr.rescores[k]={}});
  if(!Array.isArray(rr.decisions)){rr.decisions=[];delete rr.actions} /* 23 Sep 2026 (Paul, keeping his ruling of 8 Sep 2026): the Architecture Review keeps no decisions list; the layers' plans are the record */
  return rr}
function arDecisions(){return arRR().decisions}
function arWalk(key){if(lockBlocked('reviewResults'))return; /* 23 Sep 2026: agenda coverage is a write to the review */var rr=arRR();if(rr.walk[key])delete rr.walk[key];else{var u=(typeof getCurrentUser==='function')?getCurrentUser():null;rr.walk[key]={by:(u&&(u.name||u.username))||'',at:Date.now()}}Store.commit('reviewResults');render()}
function arCustomAgenda(){return rbCustomAgendaItems().map(function(a){return a.text})}
function arAllCovered(){var wk=arRR().walk;return ARCH_REVIEW_AGENDA.every(function(it){return !!wk[it.k]})&&arCustomAgenda().every(function(a,i){return !!wk[rbAgendaKey(i)]})}
function arLog(){return Array.isArray(data.archReviewLog)?data.archReviewLog:(data.archReviewLog=[])}
function arCadenceDays(c){return c==='Weekly'?7:c==='Biweekly'?14:c==='Monthly'?30:c==='Quarterly'?91:null} /* kept for elapsed-time comparisons */
function arCadenceNext(from,c){ /* 23 Sep 2026 (Paul, the Phase 4 review): a cadence falls on the calendar — the same day of the month, or three months on; a day that does not exist in the target month lands on its last day */
  var d=(from instanceof Date)?new Date(from.getTime()):new Date(from);if(isNaN(d))return null;
  if(c==='Weekly'||c==='Biweekly'){d.setDate(d.getDate()+(c==='Weekly'?7:14));return d}
  var months=c==='Monthly'?1:c==='Quarterly'?3:c==='Semiannual'?6:c==='Annual'?12:0;if(!months)return null;
  var day=d.getDate();var t=new Date(d.getFullYear(),d.getMonth()+months,1);var last=new Date(t.getFullYear(),t.getMonth()+1,0).getDate();
  t.setDate(Math.min(day,last));return t;
}
function arSchedule(){ /* the review's standing: cadence from the Board's charter, last from the log, next from the two */
  var rb=data.reviewBoard||{};var log=arLog();var last=log.length?log[log.length-1].at:null;var days=arCadenceDays(rb.cadence);
  var next=(last&&days)?(arCadenceNext(new Date(last),('arSchedule'==='arSchedule'?(data.reviewBoard||{}):(data.dataGovernance||{})).cadence)||new Date(last+days*864e5)):(rb.firstMeeting&&/^\d{4}-\d{2}-\d{2}$/.test(rb.firstMeeting)?new Date(rb.firstMeeting+'T12:00:00'):null); /* 5 Sep 2026 (Paul's ruling): the first meeting date stands until a review is logged */
  var overdue=!!(next&&next.getTime()<Date.now());
  return {cadence:rb.cadence||'',last:last,next:next,status:!log.length?(next?(overdue?'Overdue':'Scheduled'):'Not yet run'):(!days?'Running':(overdue?'Overdue':'On schedule')),days:days};
}
