function renderRadar(scores,paper){
  if(!scores||!scores.length)return '';
  var cx=320,cy=225,r=130,n=scores.length;
  var h='<div style="text-align:center;margin-bottom:'+(paper?0:24)+'px"><svg viewBox="0 0 640 '+(paper?440:470)+'" width="640" style="max-width:100%;height:auto;display:block;margin:0 auto">';
  // Concentric ring grid (5 rings) — polygon rings, Pipeline-style
  for(var ring=1;ring<=5;ring++){
    var pts='';
    for(var i=0;i<n;i++){
      var a=Math.PI*2*i/n-Math.PI/2;
      var rr=r*ring/5;
      pts+=(cx+rr*Math.cos(a))+','+(cy+rr*Math.sin(a))+' ';
    }
    h+='<polygon points="'+pts.trim()+'" fill="none" stroke="rgba(90,125,138,'+(ring===5?'.35':'.12')+')" stroke-width="1"/>';
  }
  // Axis lines + two-line labels + score values
  for(var i=0;i<n;i++){
    var a=Math.PI*2*i/n-Math.PI/2;
    var ex=cx+r*Math.cos(a),ey=cy+r*Math.sin(a);
    h+='<line x1="'+cx+'" y1="'+cy+'" x2="'+ex+'" y2="'+ey+'" stroke="rgba(90,125,138,.15)" stroke-width="1"/>';
    var lx=cx+(r+26)*Math.cos(a),ly=cy+(r+26)*Math.sin(a);
    var anchor=lx<cx-8?'end':lx>cx+8?'start':'middle';
    // Wrap "X & Y" names onto two lines so nothing truncates
    var nm=scores[i].name,l1=nm,l2='';
    if(nm.indexOf(' & ')>0){var sp=nm.split(' & ');l1=sp[0]+' &';l2=sp.slice(1).join(' & ');}
    var sv=scores[i].score==null?'Not assessed':Number(scores[i].score).toFixed(1)+'/5';
    var topY=l2?ly-8:ly-2;
    h+='<text x="'+lx+'" y="'+topY+'" text-anchor="'+anchor+'" dominant-baseline="middle" fill="'+(paper?'#333':'var(--stone)')+'" font-size="11" font-weight="600" font-family="var(--mono)" letter-spacing="0.04em">'+l1+'</text>';
    if(l2)h+='<text x="'+lx+'" y="'+(ly+6)+'" text-anchor="'+anchor+'" dominant-baseline="middle" fill="'+(paper?'#333':'var(--stone)')+'" font-size="11" font-weight="600" font-family="var(--mono)" letter-spacing="0.04em">'+l2+'</text>';
    h+='<text x="'+lx+'" y="'+(l2?ly+22:ly+14)+'" text-anchor="'+anchor+'" dominant-baseline="middle" fill="'+(paper?'#244A5E':'var(--paper)')+'" font-size="12" font-weight="700" font-family="var(--mono)">'+sv+'</text>';
  }
  h+=assessedSeriesSVG(scores.map(function(s){return s.score}),function(i,v){var a=Math.PI*2*i/n-Math.PI/2;return (cx+r*v/5*Math.cos(a))+','+(cy+r*v/5*Math.sin(a))},'#5A7D8A','rgba(90,125,138,.20)',false);
  h+='</svg></div>';
  return h;
}

function renderOutArchMap(){
  var estate=data.dataEstate||[];
  var integrations=data.integrations||[];
  var models=data.aiModels||[];
  var vendors=data.vendors||[];
  var identities=data.identities||{};

  var h=docHead('Architecture Map', /* 30 Sep 2026 (QA Sweep 1, F-36): the output's own name */'Phase 1: Map \u00b7 your current technical architecture across all five layers','out-archmap'); /* 21 Sep 2026 (Paul): the shared document header, and with it the Summary / Full control the other depthed outputs already carried; this page had its own header with only Save as PDF */

  /* AS3 (Paul's ruling, 29 Aug 2026): the five-stat block LEADS the page, above the diagram —
     the at-a-glance slot it replaces is deleted (AS2). */
  // Summary stats
  h+='<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:var(--rule);margin-bottom:32px">';
  var stats=[
    {n:estate.length,l:'Data Systems'},
    {n:integrations.length,l:'Integrations'},
    {n:models.length,l:'AI Models'},
    {n:vendors.length,l:'Vendors Recorded'} /* 28 Sep 2026 (the consolidated re-audit, C03; wording approved by Paul): the count is of vendors recorded, as the document says */,
    {n:(countOf((identities.nonHuman||{}).aiTools)==null?'\u2014':countOf((identities.nonHuman||{}).aiTools)),l:'AI Tools with Access'} /* 23 Sep 2026 (the Phase 2 re-audit): countOf, as elsewhere — 1,200 is not 1 */
  ];
  stats.forEach(function(s){
    h+='<div style="background:var(--ink);padding:20px;text-align:center"><div style="font-family:var(--serif);font-size:32px;font-weight:300;color:var(--gold)">'+s.n+'</div><div style="font-family:var(--mono);font-size:11px;letter-spacing:.12em;color:var(--stone);text-transform:uppercase;margin-top:4px">'+s.l+'</div></div>';
  });
  h+='</div>';


  /* §5.5 (B5, 26 Aug 2026): the output page is the diagram's REPORT view. The bare SVG embeds
     directly — no zoom, filter, fullscreen, or drag chrome — so the print path stays token-free
     per the item-62 law; the traced flows and any orphans print as static text beneath it. */
  h+='<div style="margin-bottom:32px">';
  
  h+='<h3 style="font-size:15px;font-weight:700;margin:0 0 12px">System Flow Diagram</h3>';
  h+=amConnBar(); /* 21 Sep 2026 (Paul): the output chooses which connections it shows, none until chosen; the choice is the document's and prints with it */
  var _rsvg=amFlowSVG();
  h+=_rsvg?('<div style="border:1px solid rgba(90,125,138,.15)">'+_rsvg+'</div>'):'';
  h+='<p style="font-size:12px;color:var(--stone);margin:8px 0 0">'+esc(amConnLine())+'</p>';
  h+='<div class="amp1brk"></div>'; /* AS6 (Paul's ruling, 29 Aug 2026): in print, stats + diagram are page one */
  /* AS4 (Paul's ruling, 29 Aug 2026): the Traced Flows list and its orphan note DROPPED from
     this output — tracing is a meta-mapping tool, not a report element */
  h+='</div>';
  // Layer 1: Data & Storage — AS6: each layer wraps whole; print packs one or two per page, never splitting one
  h+='<div class="amlayer">';
  h+=archMapLayer('Data & Storage',estate.length+' system'+(estate.length!==1?'s':'')+' mapped','1.3');
  if(estate.length){
    estate.forEach(function(s,i){
      var govColor=dataGovStatus(s)==='Formally governed'?'#3D6B6E':dataGovStatus(s)==='Ungoverned'?'#6E4A5A':'#7A6B4A';
      h+=archMapItem(s.name,esc(s.type==='Other'&&s.typeOther?'Other: '+s.typeOther:s.type||'')+' \u00B7 Owner: '+esc(s.owner||'Unassigned'),govColor,[esc(dataGovStatus(s)||'?'),esc(s.meets?'Standards: '+(dataMeetsStatus(s)==='meets'?'met':dataMeetsStatus(s)==='unassessed'?'not yet assessed':'not met'):'')],'dataEstate',i);
    });
  }else{h+=archMapEmpty('No data systems mapped yet.','1.3');}
  h+='</div>';

  /* AL1 (Paul's ruling, 29 Aug 2026): the compute layer joins the report — the register was
     promoted in the U-round and the report never gained its section. */
  var _crs=data.computeResources||[];
  h+='<div class="amlayer">';
  h+=archMapLayer('Compute & Acceleration',_crs.length+' resource'+(_crs.length!==1?'s':''),'1.3');
  if(_crs.length){
    _crs.forEach(function(cr,i){
      var cc=computeTypeColour(cr.type);
      var ctags=[];if(cr.type)ctags.push(esc(cr.type));
      h+=archMapItem(cr.name,esc(cr.purpose||'').substring(0,70)+(cr.owner?' · '+esc(cr.owner):''),cc,ctags,'computeResources',i);
    });
  }else{h+=archMapEmpty('No compute resources mapped yet.','1.3');}
  h+='</div>';

  // Layer 3: Model & Algorithm (moved above Identity)
  h+='<div class="amlayer">';
  h+=archMapLayer('Model & Algorithm',models.length+' model'+(models.length!==1?'s':'')+' mapped','1.3');
  if(models.length){
    models.forEach(function(m,i){
      var govColor=m.governance==='Formally governed'?'#3D6B6E':m.governance==='Ungoverned'?'#6E4A5A':'#7A6B4A';
      h+=archMapItem(m.name,esc(m.provider||'')+' \u00B7 '+esc(m.modelType||'')+' \u00B7 '+esc(m.usage||''),govColor,[esc(m.governance||'?')],'aiModels',i);
    });
  }else{h+=archMapEmpty('No AI models mapped yet.','1.3');}
  h+='</div>';

  // Layer 4: Orchestration & Tooling
  h+='<div class="amlayer">';
  h+=archMapLayer('Orchestration & Tooling',integrations.length+' integration'+(integrations.length!==1?'s':'')+' mapped','1.3');
  if(integrations.length){
    integrations.forEach(function(ig,i){
      var fragColor=ig.fragility==='Critical risk'?'#6E4A5A':ig.fragility==='Brittle'?'#7A6B4A':'#3D6B6E';
      var tags=[esc(ig.fragility||'?'),esc(ig.documented||'?')];
      if(ig.singlePerson==='Yes')tags.push('Single-person');
      h+=archMapItem(ig.name,esc(igSubtitle(ig)||'\u2014')+' \u00B7 '+esc(ig.type||'')+' \u00B7 '+esc(ig.frequency||''),fragColor,tags,'integrations',i);
    });
  }else{h+=archMapEmpty('No integrations mapped yet.','1.3');}
  h+='</div>';

  // Identity & Access
  var hu=identities.human||{};var nh=identities.nonHuman||{};
  /* FOLD (Paul's ruling, 28 Aug 2026): the identity section is GONE from the phase-1 report — the report is produced at the end of phase 1, and identity is counted on 2.3 now. A 2.3 output may exist later (deferred to phase-2 work). */
  // Layer 5: Application & Governance
  h+='<div class="amlayer">';
  h+=archMapLayer('Application & Governance','The AI watchlist and its workflows','1.3'); /* AL1 (Paul, 29 Aug 2026) */
  /* AI applications feed the layer (Paul's ruling, 25 Aug 2026: the layer must do something).
     B2 (26 Aug 2026): the rows open the shared componentCard — the archMapItem/aae_ editor for
     applications is superseded per Audit Spec Rev B §6. */
  var _apps=data.aiApplications||[];
  if(_apps.length){
    _apps.forEach(function(ap){
      var ac=ap.authority==='Autonomous'?'#6E4A5A':ap.authority==='Human-approved'?'#7A6B4A':'#3D6B6E';
      var tags=[];if(ap.aiStatus)tags.push(esc(ap.aiStatus));if(fieldShown('aiApplications','aiType',ap)&&listOf(ap.aiType).length)tags.push(esc(listOf(ap.aiType).join(', ')));if(ap.authority)tags.push(esc(ap.authority)); /* AL1: the watchlist status leads the tags */
      var xid='amapp_'+ap.id,xo=UI.expandEdit===xid; /* AS7 (Paul's print-test ruling, 29 Aug 2026, per item 62's escalation): this output prints unexpanded bars ONLY — law 4 stands for the fold-carrying outputs */
      h+='<div style="border-left:3px solid '+ac+';margin-bottom:4px;background:rgba(var(--fg-rgb),.02)">';
      h+='<div onclick="UI.expandEdit=UI._docAll||UI.expandEdit===\''+xid+'\'?null:\''+xid+'\';render()" style="display:flex;align-items:center;gap:12px;padding:10px 16px;cursor:pointer;transition:background .2s" onmouseover="this.style.background=\'rgba(90,125,138,.06)\'" onmouseout="this.style.background=\'transparent\'">';
      h+='<div style="flex:1"><div style="font-size:14px;font-weight:600;color:var(--paper)">'+esc(ap.name)+'</div><div style="font-size:12px;color:var(--stone)">'+esc(ap.purpose||'').substring(0,70)+(listOf(ap.audience).length?' \u00B7 '+esc(listOf(ap.audience).join(', ')):'')+'</div></div>';
      h+='<div style="display:flex;gap:4px;flex-wrap:wrap;align-items:center">';
      tags.forEach(function(t){if(t)h+='<span style="font-size:11px;padding:2px 6px;border:1px solid '+ac+';color:'+ac+'">'+t+'</span>'});
      h+='<span style="font-size:12px;color:var(--stone);margin-left:4px">'+(xo?'\u25BE':'\u25B8')+'</span>';
      h+='</div></div>';
      if(xo){var _ai=(data.aiApplications||[]).indexOf(ap);h+='<div data-ent="cc_'+ap.id+'" style="padding:12px 16px;border-top:1px solid rgba(90,125,138,.1);background:rgba(90,125,138,.03)">'+amRecordFold('aiApplications',_ai)+'</div>';} /* 21 Sep 2026 (Paul): read-only record, as every other row */
      h+='</div>';
    });
  }
  if(!_apps.length)h+=archMapEmpty('No applications on the watchlist yet.','1.3');
  /* AL1 (Paul's ruling, 29 Aug 2026): the battery-score card is GONE — those scores are the
     Readiness Report's territory (1.1 section H). The workflows join as their own subsection. */
  var _wfs2=data.agentRegistry||[];
  h+='<div style="font-family:var(--mono);font-size:11px;color:var(--stone);letter-spacing:.1em;text-transform:uppercase;margin:16px 0 8px">Workflows & agents ('+_wfs2.length+')</div>';
  if(_wfs2.length){
    componentAgentGroups(_wfs2).forEach(function(group){h+=componentAgentHeading(group.name);group.list.forEach(function(w){
      var wapp=compById(w.appId);
      var wc=w.autonomy==='Autonomous'?'#6E4A5A':'#7A6B4A';
      var wxid='amwf_'+w.id,wxo=UI.expandEdit===wxid; /* AS7 */
      h+='<div style="border-left:3px solid '+wc+';margin-bottom:4px;background:rgba(var(--fg-rgb),.02)">';
      h+='<div onclick="UI.expandEdit=UI._docAll||UI.expandEdit===\''+wxid+'\'?null:\''+wxid+'\';render()" style="display:flex;align-items:center;gap:12px;padding:10px 16px;cursor:pointer">';
      h+='<div style="flex:1"><div style="font-size:14px;font-weight:600;color:var(--paper)">'+esc(w.name||'Unnamed')+'</div><div style="font-size:12px;color:var(--stone)">'+(wapp?'Belongs to '+esc(wapp.name):'Unattached')+(w.scope?' \u00B7 '+esc(w.scope):'')+'</div></div>';
      h+='<div style="display:flex;gap:4px;align-items:center">'+(w.autonomy?'<span style="font-size:11px;padding:2px 6px;border:1px solid '+wc+';color:'+wc+'">'+esc(w.autonomy)+'</span>':'')+'<span style="font-size:12px;color:var(--stone);margin-left:4px">'+(wxo?'\u25BE':'\u25B8')+'</span></div>';
      h+='</div>';
      if(wxo){var _wi=(data.agentRegistry||[]).indexOf(w);h+='<div style="padding:12px 16px;border-top:1px solid rgba(90,125,138,.1)" onclick="event.stopPropagation()">'+amRecordFold('agentRegistry',_wi)+'</div>';} /* 21 Sep 2026 (Paul): read-only record */
      h+='</div>';
    })});
  }else{h+='<p style="font-size:13px;color:var(--stone)">No workflows or agents cataloged yet.</p>';}
  h+='</div>';

  return h;
}

/* Architecture Map helpers */
function renderStackLayer(lid){ /* 5 Sep 2026 (Paul's ruling): the stack view is a catalogue of the layer's components, the same tiles opening the same shared card, arranged in the sub-bands the diagram uses, with one line of what the layer's grammar cares about. The plan panels that used to sit here (compute current and target, circuit breakers, zero-trust, observability) were Phase 1 and 2 documents pasted under a layer with their own Save buttons; their fields live on the component cards or in the Governance Framework. The Approved Models duplicate and the governance-domains list go with them. */
  var tb=(data.assessments&&data.assessments.techBaseline)||{};var rs=(data.reviewResults||{}).rescores||{};
  var LK={data:'data',compute:'compute',model:'model',orch:'orchestration',app:'application'}[lid]||lid;
  var h='';var stat=activeLayerStats(LK),score=stat.score;
  h+='<div style="padding:12px 16px 4px;font-family:var(--mono);font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--stone)">Latest known score for this layer <span style="color:var(--paper);font-weight:600">'+esc(scoreLabel(stat))+'</span>'+(avgLayerScore(LK,rs)?' \u00B7 rescored':' \u00B7 baseline')+'</div>';
  var grid=function(items,tileFn){if(!items.length)return '';return '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:6px;padding:0 16px;margin-bottom:16px">'+items.map(tileFn).join('')+'</div>'};
  var vis=function(k){return componentRegisters()[k].filter(function(c){return componentVisibleOnViews(k,c)})};
  var gc=function(v,good,mid){return v===good?'#3D6B6E':v===mid?'#7A6B4A':v?'#6E4A5A':'#8A8278'};
  if(lid==='data'){
    var est=vis('dataEstate');var base=est.filter(function(e){return e.tier!=='Derived store'}),der=est.filter(function(e){return e.tier==='Derived store'});
    var tile=function(e){return stkTileC('dataEstate',e,(e.type||'')+(e.owner?' \u00B7 '+e.owner+(e.ownerDept?', '+e.ownerDept:''):(e.ownerDept?' \u00B7 '+e.ownerDept:'')),(govBegun('data')?gc(dataGovStatus(e),'Formally governed','Partially governed'):'#8A8278'),(govBegun('data')?(dataGovStatus(e)||'Not yet governed'):'')) /* 23 Sep 2026 (Paul): neutral and silent until data governance has begun */};
    if(base.length){h+=stkGrp('Base systems',base.length);h+=grid(base,tile)}
    if(der.length){h+=stkGrp('Derived stores',der.length);h+=grid(der,tile)}
    if(!est.length)h+=stkEmpty('No data systems mapped yet.');
  }
  if(lid==='compute'){
    var crs=vis('computeResources');
    h+=stkGrp('Compute resources',crs.length);
    h+=crs.length?grid(crs,function(c){return stkTileC('computeResources',c,(c.type||'')+(c.provider?' \u00B7 '+c.provider:''),(c.type?computeTypeColour(c.type):'#8A8278'),c.fit||c.type||'')}):stkEmpty('No compute resources mapped yet.');
  }
  if(lid==='model'){
    var mods=vis('aiModels');
    h+=stkGrp('AI models',mods.length);
    h+=mods.length?grid(mods,function(m){var st=m.shadowDecision||m.governance||'';return stkTileC('aiModels',m,(m.provider||'')+(m.modelType?' \u00B7 '+m.modelType:''),gc(m.governance,'Formally governed','Partially governed'),st||'') /* 23 Sep 2026: the field's own words (Governed and Partial never matched, so every answered model painted plum); no placeholder verdict when unanswered */}):stkEmpty('No models mapped yet.');
  }
  if(lid==='orch'){
    var igs=vis('integrations');
    h+=stkGrp('Integrations',igs.length);
    h+=igs.length?grid(igs,function(ig){var b=ig.breakerStatus||'';return stkTileC('integrations',ig,igSubtitle(ig)||'\u2014',ig.fragility==='Critical risk'?'#6E4A5A':ig.fragility==='Brittle'?'#8B5E3C':ig.fragility?'#3D6B6E':'#8A8278',(ig.fragility||'')+(b?(ig.fragility?' \u00b7 ':'')+'Breaker: '+b:'')) /* 23 Sep 2026 (Paul): the stack colours integrations by fragility, as the map does; the breaker joins the badge once answered */}):stkEmpty('No integrations mapped yet.');
  }
  if(lid==='app'){
    var apl=vis('aiApplications'),ags=vis('agentRegistry');
    if(apl.length){h+=stkGrp('Applications',apl.length);h+=grid(apl,function(ap){return stkTileC('aiApplications',ap,(fieldShown('aiApplications','aiType',ap)?listOf(ap.aiType):[]).join(', ')+(listOf(ap.audience).length?' \u00B7 '+listOf(ap.audience).join(', '):''),ap.authority==='Autonomous'?'#6E4A5A':ap.authority==='Human-approved'?'#7A6B4A':ap.authority?'#3D6B6E':'#8A8278',ap.authority||'Authority not set')})}
    if(ags.length){h+=stkGrp('Workflows & agents',ags.length);componentAgentGroups(ags).forEach(function(group){h+=componentAgentHeading(group.name);h+=grid(group.list,function(ag){return stkTileC('agentRegistry',ag,(ag.autonomy||'')+(ag.scope?' \u00B7 '+ag.scope:''),ag.autonomy==='Autonomous'?'#6E4A5A':ag.autonomy==='Human-approved'?'#7A6B4A':ag.autonomy?'#3D6B6E':'#8A8278',ag.credentialPosture||ag.autonomy||'')})})}
    if(!apl.length&&!ags.length)h+=stkEmpty('No applications or agents mapped yet.');
  }
  return h;
}
