function archMapLayer(title,subtitle,stepId){
  return '<div style="display:flex;align-items:center;justify-content:space-between;margin:24px 0 8px;padding-bottom:4px;border-bottom:2px solid var(--gold)"><div><h3 style="font-size:16px;font-weight:700;margin:0;color:#4A6E8A">'+title+'</h3><span style="font-size:13px;color:var(--stone)">'+subtitle+'</span></div></div>'; /* AS5 (Paul's ruling, 29 Aug 2026): the Go-to-Step button is GONE from every layer header — navigation has no place in an outcome document; stepId stays in the signature, unused */
}
function archMapItem(name,detail,borderColor,tags,editKey,editIdx){
  var itemId=editKey+'_'+editIdx;
  var isOpen=UI.archMapEdit===itemId;
  var h='<div style="border-left:3px solid '+borderColor+';margin-bottom:4px;background:rgba(var(--fg-rgb),.02)">';
  h+='<div onclick="var _aid=UI.archMapEdit===\''+itemId+'\'?null:\''+itemId+'\';UI.archMapEdit=_aid;render();if(_aid){setTimeout(function(){var _el=document.getElementById(\'ame_\'+_aid);if(_el)_el.scrollIntoView({behavior:\'smooth\',block:\'start\'})},150)}" style="display:flex;align-items:center;gap:12px;padding:10px 16px;cursor:pointer;transition:background .2s" onmouseover="this.style.background=\'rgba(90,125,138,.06)\'" onmouseout="this.style.background=\'transparent\'">';
  h+='<div style="flex:1"><div style="font-size:14px;font-weight:600;color:var(--paper)">'+esc(name)+'</div><div style="font-size:12px;color:var(--stone)">'+detail+'</div></div>';
  h+='<div style="display:flex;gap:4px;flex-wrap:wrap;align-items:center">';
  tags.forEach(function(t){if(t)h+='<span style="font-size:11px;padding:2px 6px;border:1px solid '+borderColor+';color:'+borderColor+'">'+t+'</span>'});
  h+='<span style="font-size:12px;color:var(--stone);margin-left:4px">'+(isOpen?'\u25BE':'\u25B8')+'</span>';
  h+='</div></div>';
  if(isOpen){
    h+='<div id="ame_'+itemId+'" data-ent="'+itemId+'" style="padding:12px 16px;border-top:1px solid rgba(90,125,138,.1);background:rgba(90,125,138,.03);scroll-margin-top:80px">';
    h+=amRecordFold(editKey,editIdx); /* 21 Sep 2026 (Paul): every row opens the component's full record, read-only, as the paper renderer lays it out; the old edit panels are withdrawn from this page */
    h+='</div>';
  }
  h+='</div>';
  return h;
}
function amRecordFold(key,idx){installComponentMaps();var rec=(data[key]||[])[idx];if(!rec)return '<p style="color:var(--stone)">Item not found.</p>';var body='';try{body=lyRender('comp:'+key,{i:idx,kind:key},'full',null)}catch(e){body=''}return body?'<div class="am-record" style="font-size:13px">'+body+'</div>':'<p style="color:var(--stone)">Nothing recorded for this component yet.</p>'} /* the record read-only: what the individual-component document prints */
