function docHead(title,sub,pid){ /* 18 Sep 2026: the Summary / Full control beside the Save as PDF where the document offers depth (§22.2.3) */return '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px"><div><h2 style="font-size:22px;font-weight:700;margin:0 0 4px">'+title+'</h2><p style="color:var(--stone);font-size:14px;margin:0">'+sub+'</p></div>'+((DEPTHED_OUTPUTS[pid]&&!UI._printing)?lyDepthCtl():'')+btn('\u25BE Save as PDF','printOutput(\''+pid+'\')','bg2','font-size:12px')+'</div>'}
function sevColor(sv){return sv==='Critical'?'#6E4A5A':sv==='Major'?'#7A6B4A':'#4A6E8A'}
function reportTestRefs(kind){
  var built=kind==='security'?SEC_AREAS:CAS_SCENARIOS;
  var custom=(kind==='security'?data.securityTestsX:data.cascadeTestsX)||[];
  return built.map(function(a,i){return {i:i}}).concat(custom.map(function(t,i){return {i:built.length+i,x:i}}));
}
function reportRemStatus(t){return t.remStatus||(t.status==='Resolved'?'Done':'Open')}
function reportTestNeedsRem(t,kind){return kind==='security'?(t.status==='Fail'||t.status==='Partial'):(t.grade==='Cascaded'||t.grade==='Contained with gaps')}
function reportTestHasRem(t,kind){return reportTestNeedsRem(t,kind)||!!(t.remediation||t.owner||t.date||t.severity||t.remStatus)}
function secTestSummary(){
 var r={pass:0,partial:0,fail:0,untested:0,tested:0};
 reportTestRefs('security').forEach(function(ref){var t=secRec(ref);if(t.status==='Pass'){r.pass++;r.tested++}else if(t.status==='Partial'){r.partial++;r.tested++}else if(t.status==='Fail'){r.fail++;r.tested++}else r.untested++});return r;
}
function casTestSummary(){var r={tested:0,contained:0,gaps:0,cascaded:0,untested:0};
 reportTestRefs('cascade').forEach(function(ref){var t=casRec(ref);if(t.grade==='Contained'){r.contained++;r.tested++}else if(t.grade==='Contained with gaps'){r.gaps++;r.tested++}else if(t.grade==='Cascaded'){r.cascaded++;r.tested++}else r.untested++});return r;
}
function recSig(o){return JSON.stringify(o===undefined?null:o,function(k,v){return v===''?undefined:v})} /* 30 Sep 2026 (QA Sweep 1, F-42): a record's content for a change test — a missing field and an empty one are the same */
function rowHasContent(o){return !!o&&Object.keys(o).some(function(k){return k!=='id'&&!isEmptyRec(o[k])})} /* 1 Oct 2026 (QA Sweep 2, N-4, N-11): a designed blank row may be listed but is never counted */
function isEmptyRec(o){if(o==null)return true;if(typeof o!=='object')return String(o).trim()==='';return Object.keys(o).every(function(k){return isEmptyRec(o[k])})} /* 30 Sep 2026 (QA Sweep 1, F-42): a record with nothing in it */
function remOpenCounted(){return remediationQueue().filter(function(r){return r.src!=='Sovereignty'&&r.remStatus!=='Done'})} /* 30 Sep 2026 (Paul's decision, QA Sweep 1, F-14): sovereignty rows are listed on 5.4 but left out of every open-remediation and past-target count */
function remediationQueue(){ /* the phase's one spine: failed and partial tests, uncontained scenarios, and sovereignty actions that did not solve their problem, each with an owner */
  var q=[];var secTests=data.securityTests||[],casTests=data.cascadeTests||[];
  SEC_AREAS.forEach(function(a,i){var t=secTests[i]||{};if((t.status==='Fail'||t.status==='Partial')){if(true)q.push({name:a.name,sev:t.severity||'Unranked',owner:t.owner||'',date:t.date||'',src:'Security and identity',key:'sec_remStatus_'+i,remStatus:t.remStatus||''})}});
  (data.securityTestsX||[]).forEach(function(t,i){if((t.status==='Fail'||t.status==='Partial')){if(true)q.push({name:t.name,sev:t.severity||'Unranked',owner:t.owner||'',date:t.date||'',src:'Security and identity',key:'secx_remStatus_'+(t.id||(t.id='sx'+uid())),remStatus:t.remStatus||''})}});
  CAS_SCENARIOS.forEach(function(a,i){var t=casTests[i]||{};if((t.grade==='Cascaded'||t.grade==='Contained with gaps')){if(true)q.push({name:a.name,sev:t.severity||'Unranked',owner:t.owner||'',date:t.date||'',src:'Cascade failure',key:'cas_remStatus_'+i,remStatus:t.remStatus||''})}});
  (data.cascadeTestsX||[]).forEach(function(t,i){if((t.grade==='Cascaded'||t.grade==='Contained with gaps')){if(true)q.push({name:t.name,sev:t.severity||'Unranked',owner:t.owner||'',date:t.date||'',src:'Cascade failure',key:'casx_remStatus_'+(t.id||(t.id='cx'+uid())),remStatus:t.remStatus||''})}});
  (data.deployments||[]).forEach(function(dp,di){(dp.findings||[]).forEach(function(f,fi){if(!f)return;if(f.status==='Resolved'&&!f.remStatus)f.remStatus='Done'; /* 23 Sep 2026 (Phase 3 review): an unowned or unranked issue is a gap to show, not a reason to leave it out */ /* 9 Sep 2026: an old Resolved reads as Done */q.push({name:(f.title||f.text||'Finding')+(dp.name||dp.useCase?' ('+(dp.name||dp.useCase)+')':''),sev:f.severity||'Unranked',owner:f.owner||'',date:f.date||'',src:'Deployment test',key:'dpfx_remStatus_'+dp.id+'_'+(f.id||(f.id='fd'+uid())),remStatus:f.remStatus||''})})}); /* 4 Sep 2026 (Paul's ruling): findings from every test kind join the one spine */
  sovProg().actions.forEach(function(a,_ai){if(a.done==='Completed'&&(a.worked==='Did not solve'||a.worked==='Partly solved')){var _later=sovProg().actions.some(function(b,_bi){return _bi>_ai&&b.item===a.item&&b.done==='Completed'&&b.worked==='Solved'});if(_later)return; /* 23 Sep 2026 (Paul, the Phase 5 review): a later action on the same question that solved it closes the earlier attempt in the queue; the attempt stays on record */var it=null;SOV_PROGRAM.forEach(function(x){if(x.k===a.item)it=x});q.push({name:(it?it.t+': ':'')+firstSentence(a.text||''),sev:'Unranked',owner:a.owner,date:a.date||'',src:'Sovereignty',key:'sovq_'+a.id,remStatus:'',sovLabel:(a.done||'')+(a.worked?' \u00B7 '+a.worked:''),sovDim:it?it.dim:''})}}); /* 9 Sep 2026 (Paul's ruling): sovereignty items appear on the register too; their status lives on the Center */
  (data.deployments||[]).forEach(function(dp,di){deployReadout(dp).filter(function(r){return r.color==='red'||r.color==='amber'}).forEach(function(r){var a=dpRowAct(dp,r);if(!(a.owner||a.act))return;q.push({name:r.text+(dp.name||dp.useCase?' ('+(dp.name||dp.useCase)+')':''),sev:'Unranked',owner:a.owner||'',date:a.hor||'',src:'Deployment conformance',key:'dpra_rem_'+dp.id+'_'+dpRowKey(r),remStatus:a.remStatus||''})});dpResolvedActions(dp).forEach(function(x){q.push({name:(x.a.text||'A resolved finding')+(dp.name||dp.useCase?' ('+(dp.name||dp.useCase)+')':''),sev:'Unranked',owner:x.a.owner||'',date:x.a.hor||'',src:'Deployment conformance',key:'dpra_done_'+dp.id+'_'+x.k+'_'+(x.oid||(x.hi!=null?'h'+x.hi:'cur')),remStatus:'Done'})})}); /* 23 Sep 2026 (Paul): resolved actions stay on the register, closed */ /* 23 Sep 2026 (Phase 3 review): an assigned action on an automatic finding joins the same follow-through */ var ord={Critical:0,Major:1,Minor:2,Unranked:3};q.sort(function(a,b){return (ord[a.sev]!==undefined?ord[a.sev]:3)-(ord[b.sev]!==undefined?ord[b.sev]:3)});return q;
}
