function scoreStats(values,total){var vals=values.filter(function(v){return v!==null&&v!==undefined&&v!==''&&isFinite(+v)&&+v>=1&&+v<=5}).map(Number);return {score:vals.length?Math.round(vals.reduce(function(a,b){return a+b},0)/vals.length*10)/10:null,answered:vals.length,total:total,state:!vals.length?'Not assessed':vals.length<total?'Partially assessed':'Scored'}}
function layerScoreStats(layerId,source){var l=RESCORE_LAYERS.find(function(x){return x[0]===layerId});return l?scoreStats(l[3].map(function(q){return reportScoreValue(source,layerId,q[0])}),l[3].length):scoreStats([],0)}
function scoreNote(s){return !s.answered?'Not assessed':s.answered<s.total?s.answered+' of '+s.total+' answered':''}
function scoreLabel(s,unit){return s.score===null?'— · Not assessed':s.score.toFixed(1)+(unit||' of 5')+(scoreNote(s)?' · '+scoreNote(s):'')}
function scoreMean(rows){var a=rows.filter(function(r){return r.score!==null&&r.score!==undefined});return {score:a.length?a.reduce(function(n,r){return n+r.score},0)/a.length:null,assessed:a.length,total:rows.length}}
function activeLayerStats(k){var re=layerScoreStats(k,(data.reviewResults||{}).rescores),ba=layerScoreStats(k,(data.assessments||{}).techBaseline);return re.score===null?ba:re}
function assessmentBars(rows,paper){var ink=paper?'#111':'var(--paper)',mute=paper?'#555':'var(--stone)',rule=paper?'#ddd':'rgba(var(--fg-rgb),.10)',bg=paper?'#eee':'rgba(var(--fg-rgb),.08)';return '<table class="assessment-score-bars" style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 16px"><colgroup><col style="width:40%"><col style="width:31%"><col style="width:29%"></colgroup><tbody>'+rows.map(function(r){var v=r.score,c=v===null?bg:v>=4?'#3D6B6E':v>=2.5?'#4A6E8A':'#6E4A5A',note=scoreNote(r);return '<tr style="break-inside:avoid"><td style="font-size:12.5px;padding:7px 8px 7px 0;color:'+ink+';border-bottom:1px solid '+rule+'">'+esc(r.name)+'</td><td style="padding:7px 10px;border-bottom:1px solid '+rule+'"><div style="height:7px;background:'+bg+';border-radius:3px"><div style="height:7px;width:'+(v===null?0:v*20)+'%;background:'+c+';border-radius:3px"></div></div></td><td style="padding:7px 0 7px 8px;text-align:right;font-size:12px;color:'+ink+';border-bottom:1px solid '+rule+'">'+(v===null?'—':v.toFixed(1)+' / 5')+(note?'<div style="font-size:11px;color:'+mute+';margin-top:2px">'+esc(note)+'</div>':'')+'</td></tr>'}).join('')+'</tbody></table>'}
/* Missing axes have no data point. A polygon is used only for a complete series. */
function assessedSeriesSVG(vec,point,color,fill,dash){var h='',known=vec.map(function(v){return v!==null&&v!==undefined&&isFinite(+v)&&+v>0}),attrs=' stroke="'+color+'" stroke-width="2"'+(dash?' stroke-dasharray="'+(typeof dash==='string'?dash:'5,4')+'"':'');if(known.every(Boolean))h='<polygon points="'+vec.map(function(v,i){return point(i,v)}).join(' ')+'" fill="'+(fill||'none')+'"'+attrs+'/>';else{vec.forEach(function(v,i){var j=(i+1)%vec.length;if(known[i]&&known[j]){var a=point(i,v).split(','),b=point(j,vec[j]).split(',');h+='<line x1="'+a[0]+'" y1="'+a[1]+'" x2="'+b[0]+'" y2="'+b[1]+'"'+attrs+'/>'}})}vec.forEach(function(v,i){if(!known[i])return;var p=point(i,v).split(',');h+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3" fill="'+color+'"/>'});return h}

