function renderManage(){
  var ph=PH.find(function(p){return p.id===5});
  var col=ph?ph.color:'#5A6B7A';
  var h='<div class="content-area"><div class="content-inner">';
  h+=backBtn();
  // Phase Five · Manage overview video (drop arch-phase5.mp4 beside index.html)
  h+='<div class="overview-video-card mb-6"><div class="overview-video-label" style="color:'+col+'">Phase Five \u00b7 Manage</div>'
   +'<video class="overview-video" controls preload="auto" playsinline><source src="../../../assets/media/ai-architecture/arch-phase5.mp4" type="video/mp4">Your browser does not support embedded video.</video></div>';
  // Header
  h+='<div style="display:flex;align-items:center;gap:16px;margin-bottom:20px"><div style="width:56px;height:56px;border-radius:28px;background:'+col+';color:#fff;display:flex;align-items:center;justify-content:center;font-size:24px;font-weight:700;flex-shrink:0">5</div><div><div style="display:flex;align-items:center;gap:8px"><div style="font-family:var(--serif);font-size:28px;font-weight:300">Manage</div>'+badge('Ongoing',col)+'</div><p style="font-size:14px;color:var(--stone);line-height:1.5;margin:4px 0 0">The 90-day program is the ignition. Managing your AI-ready architecture is continuous \u2014 monitor health, govern change, and review on a regular cadence. The dashboard below is your living instrument.</p></div></div>';
  // Link to the standalone Architecture Dashboard
  h+=card('<div style="display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap"><div style="display:flex;align-items:center;gap:12px"><div style="width:40px;height:40px;border-radius:8px;background:'+col+';color:#fff;display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0">\u25A3</div><div><div style="font-size:15px;font-weight:700;color:var(--paper)">Architecture Dashboard</div><div style="font-size:13px;color:var(--stone)">Live health metrics, layer scores, and the review tracker.</div></div></div>'+btn('Open Dashboard \u2192','go(\'phase5\')','bp','padding:10px 18px')+'</div>','margin-bottom:16px');
  // Outputs
  (ph.outcomes||[]).forEach(function(o){h+='<div onclick="go(\''+o.id+'\')" style="display:flex;align-items:center;gap:10px;padding:12px 16px;background:rgba(var(--fg-rgb),.02);border:1px solid rgba(var(--fg-rgb),.06);margin-bottom:6px;cursor:pointer;border-left:3px solid '+col+';transition:background .15s" onmouseover="this.style.background=\'rgba(var(--fg-rgb),.05)\'" onmouseout="this.style.background=\'rgba(var(--fg-rgb),.02)\'"><span style="font-size:14px;font-weight:600;flex:1">'+esc(o.name)+'</span><span style="color:var(--stone);font-size:13px">\u2192</span></div>'});
  h+='</div></div>';
  return h;
}

function dashFold(key,title,summary,bodyFn,open0){ /* 4 Sep 2026 (Paul's ruling): the standing registers on the dashboard fold, Governance-style */
  UI.dbFold=UI.dbFold||{};var open=(key in UI.dbFold)?UI.dbFold[key]:!!open0;
  var h='<div onclick="UI.dbFold=UI.dbFold||{};UI.dbFold[\''+key+'\']='+(open?'false':'true')+';render()" style="display:flex;align-items:center;gap:12px;cursor:pointer"><span style="font-size:14px;color:var(--stone)">'+(open?'\u25BE':'\u25B8')+'</span><h3 style="font-size:15px;font-weight:700;margin:0;flex:1">'+title+'</h3>'+(summary?'<span style="font-size:12px;color:var(--stone)">'+summary+'</span>':'')+'</div>';
  if(open)h+='<div style="margin-top:14px" onclick="event.stopPropagation()">'+bodyFn()+'</div>';
  return '<div id="fold_'+key+'">'+card(h,'margin-bottom:12px')+'</div>';
}
var STACK_GATEWAYS={data:{page:'stdData',label:'Data domains and standards'},compute:{page:'stdCompute',label:'Compute goals and strategy'},model:{page:'stdModel',label:'Model rules'},orch:{page:'stdInteg',label:'Integration standards'},app:{page:'stdApp',label:'Application and agent governance'}}; /* 6 Sep 2026 (Paul's ruling): the stack's layer bars open each layer's standards home; the other four layers follow once their pages exist */
function stackViewBody(DIMS){ /* 5 Sep 2026 (Paul's ruling): the five-layer stack, factored so the dashboard's hero and 5.2's stack view render one body */
  var h='';
    var stackTab=UI.stackLayer||null;
    var dByK={},dStats={};DIMS.forEach(function(d){dByK[d.k]=d.score;dStats[d.k]=d});
    var LAYERS=[{id:'app',name:'Application & Governance',color:'#5A7D8A',score:dByK['application']},{id:'orch',name:'Orchestration & Tooling',color:'#6E4A5A',score:dByK['orchestration']},{id:'model',name:'Model & Algorithm',color:'#7A6B4A',score:dByK['model']},{id:'compute',name:'Compute & Acceleration',color:'#3D6B6E',score:dByK['compute']},{id:'data',name:'Data & Storage',color:'#4A6E8A',score:dByK['data']}];
    LAYERS.forEach(function(layer,li){
      var isOpen=stackTab===layer.id;
      if(li>0)h+='<div style="display:flex;justify-content:center"><div style="width:2px;height:16px;background:rgba(90,125,138,.3)"></div></div>';
      h+='<div onclick="UI.stackLayer=UI.stackLayer===\''+layer.id+'\'?null:\''+layer.id+'\';render()" style="display:flex;align-items:center;gap:16px;padding:16px 20px;background:'+layer.color+';cursor:pointer;transition:opacity .2s;border-radius:4px" onmouseover="this.style.opacity=\'0.9\'" onmouseout="this.style.opacity=\'1\'">';
      h+='<div style="flex:1"><div style="font-size:15px;font-weight:700;color:#fff">'+layer.name+'</div>'+(STACK_GATEWAYS[layer.id]?'<div style="margin-top:4px"><span onclick="event.stopPropagation();UI.backTo=currentPage===\'step\'?currentStep:currentPage;go(\''+STACK_GATEWAYS[layer.id].page+'\')" style="font-family:var(--mono);font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.85);border:1px solid rgba(255,255,255,.35);padding:2px 8px;cursor:pointer">'+STACK_GATEWAYS[layer.id].label+' \u2192</span></div>':'')+'</div>'; /* 6 Sep 2026 (Paul's ruling): each layer's bar is the gateway to that layer's standards home */
      h+='<div style="text-align:center;min-width:50px"><div style="font-family:var(--serif);font-size:24px;font-weight:300;color:#fff">'+(layer.score==null?'—':Number(layer.score).toFixed(1))+'</div><div style="font-size:10px;color:rgba(255,255,255,.85)">'+(layer.score==null?'Not assessed':'/5')+'</div>'+(layer.score!=null&&(dStats[({app:'application',orch:'orchestration'})[layer.id]||layer.id]||{}).note?'<div style="font-size:10px;color:#fff">'+esc(dStats[({app:'application',orch:'orchestration'})[layer.id]||layer.id].note)+'</div>':'')+'</div>';
      h+='<span style="font-size:12px;color:rgba(255,255,255,.6)">'+(isOpen?'\u25BE':'\u25B8')+'</span></div>';
      if(isOpen){h+='<div style="padding:16px 0;margin:0 20px;border-left:2px solid '+layer.color+';border-right:2px solid '+layer.color+'">'+renderStackLayer(layer.id)+'</div>'}
    });
  return h;
}
