  var kinds=[['deploy','Deployment Testing','One real application flow at a time, run from the data it reads to the action it takes, and judged against the organization\u2019s own rules.'],['security','Security and Identity','The architecture tested the way an attacker would use it, through the access the organization has already granted.'],['cascade','Cascade Failures','What happens to the rest of the architecture when one part of it fails.'],['risk','Risk Scenarios','The risks scored in Phase 1, checked against what the tests found.']];
  h+='<div style="display:flex;gap:8px;flex-wrap:wrap;margin:0 0 14px">'+kinds.map(function(k){var on=k[0]===sub;return '<button onclick="UI.atlTestKind=\''+k[0]+'\';render()" class="btn '+(on?'bp':'bs')+'">'+k[1]+'</button>'}).join('')+'</div>';
  var cur=kinds.filter(function(k){return k[0]===sub})[0]||kinds[0];
