  h+=ring(pr.done,pr.total,ANA.teal,'program steps complete');h+=ring(ej.judged,ej.total,ANA.gold,'components assessed');h+=ring(dg,dgT,ANA.blue,'data systems meeting their standards');h+=ring(shD,sh.length,ANA.brown,'shadow tools with a verdict');h+=ring(cov.tested,cov.flows,ANA.high,'traced flows tested');h+=ring(sov.met||0,sov.applicable||0,ANA.green,'sovereignty conditions met');
