function anSpark(vals,color){var W=180,H=44,P=4;var N=vals.length;var v=vals.filter(function(x){return x!==null&&x!==undefined}); /* 23 Sep 2026 (the Phase 5 re-audit, round 4): each run of measured days is its own line, a lone measurement is a point, and a missing day is a gap; nothing is drawn across what was not measured */
  if(!v.length)return '<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;display:block"></svg>';var mx=Math.max.apply(null,v),mn=Math.min.apply(null,v);if(mx===mn){mx+=1;mn-=1}
  var xy=function(x,i){return [(P+(N>1?i/(N-1):0.5)*(W-2*P)).toFixed(1),(H-P-(x-mn)/(mx-mn)*(H-2*P)).toFixed(1)]};var runs=[],cur=[];vals.forEach(function(x,i){if(x===null||x===undefined){if(cur.length)runs.push(cur);cur=[]}else cur.push(xy(x,i))});if(cur.length)runs.push(cur);
  var out='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;display:block">';runs.forEach(function(r){if(r.length===1)out+='<circle cx="'+r[0][0]+'" cy="'+r[0][1]+'" r="2.5" fill="'+color+'"/>';else out+='<polyline points="'+r.map(function(p){return p.join(',')}).join(' ')+'" fill="none" stroke="'+color+'" stroke-width="2" stroke-linejoin="round"/>'});
  var lastRun=runs[runs.length-1],lp=lastRun[lastRun.length-1];out+='<circle cx="'+lp[0]+'" cy="'+lp[1]+'" r="3" fill="'+color+'"/>';return out+'</svg>' }
function anTrends(){ /* the Governance module's trends, with the first value beside the last so the movement reads */
  var S=data.anSnapshots||[];if(S.length<2)return anEmpty('Trends build over time. A snapshot of key metrics is recorded automatically each day you open Analytics. Come back tomorrow to see movement.',null,'');
  var series=[{n:'Readiness Index',k:'ari',c:ANA.blue,good:1},{n:'Sovereignty Index',k:'sov',c:ANA.gold,good:1},{n:'Sov. questions open',k:'att',c:ANA.high,good:-1},{n:'Open remediation',k:'open',c:ANA.med,good:-1},{n:'Security passed',k:'pass',c:ANA.teal,good:1},{n:'Policy coverage %',k:'cov',c:ANA.green,good:1}];
  var h='<div style="font-size:12px;color:'+ANA.ink+';margin-bottom:10px">'+S.length+' snapshots \u00b7 '+esc(S[0].d)+' \u2192 '+esc(S[S.length-1].d)+'</div>';
  series.forEach(function(s){var vals=S.map(function(x){return x[s.k]==null?null:x[s.k]});var v=vals.filter(function(x){return x!==null});if(!v.length)return;var cur=vals[vals.length-1],first=vals[0],miss=(cur===null||first===null);var delta=miss?null:cur-first;var up=delta>0,flat=delta===0; /* 23 Sep 2026 (the Phase 5 re-audit): a missing endpoint stays missing, never an unchanged earlier value */var deltaCol=flat?ANA.ink:(delta*s.good>0?ANA.teal:ANA.high);
    h+='<div style="display:grid;grid-template-columns:118px 40px 1fr 44px 56px;gap:10px;align-items:center;padding:13px 0;border-top:1px solid rgba(var(--fg-rgb),.05)"><div style="font-size:12px;color:'+ANA.txt+'">'+s.n+'</div><div style="font-family:var(--mono);font-size:12px;color:'+ANA.ink+';text-align:right">'+(first===null?'\u2014':first)+'</div><div>'+anSpark(vals,s.c)+'</div><div style="font-family:var(--mono);font-size:14px;font-weight:700;color:var(--paper);text-align:right"'+(cur===null?' title="Not assessed at the latest snapshot; last known '+v[v.length-1]+'"':'')+'>'+(cur===null?'\u2014':cur)+'</div><div style="font-family:var(--mono);font-size:12px;color:'+(miss?ANA.ink:deltaCol)+';text-align:right">'+(miss?'Not assessed':(flat?'\u2192 0':(up?'\u25b2 +':'\u25bc ')+delta))+'</div></div>'});   return h+'<div style="font-size:12px;color:var(--stone);margin-top:6px">'+S.length+' daily snapshot'+(S.length===1?'':'s')+', recorded automatically when Analytics is opened. Snapshots are kept as they were recorded. Coverage taken before 23 September 2026 counted applications rather than traced flows.</div>'; /* 23 Sep 2026 (Paul, the Phase 5 review): the ruled caption, carried from the removed duplicate */ }
