function renderNotesPanel(){
  var panel=$('notesPanel');if(!panel)return;
  var notes=data.notes||[];
  var h='<div class="notes-header"><div style="font-family:var(--serif);font-size:18px;font-weight:300;color:var(--paper)">\u2738 Notes</div><button class="coach-close" onclick="toggleNotes()">\u00D7</button></div>';
  h+='<div class="notes-list" id="notesList">';
  if(!notes.length){
    h+='<div class="notes-empty">No notes yet.<br>Capture a thought \u2014 it\u2019s saved with the screen you\u2019re on, so you can jump back later.</div>';
  }else{
    for(var i=notes.length-1;i>=0;i--){
      var n=notes[i];
      var navAttr=n.page?(' onclick="goToNote(\''+esc(n.id)+'\')"'):'';
      h+='<div class="note-item"><button class="note-del" title="Delete note" onclick="deleteNote(\''+esc(n.id)+'\')">\u00D7</button>'+
         '<div class="note-item-text">'+esc(n.text)+'</div>'+
         '<div class="note-item-meta"><span class="note-where"'+navAttr+'>'+esc(notesWhereFor(n.page,n.step))+'</span>'+(n.ts?' \u00B7 '+fmt(n.ts):'')+(n.byName?' \u00B7 '+esc(n.byName):'')+'</div></div>';
    }
  }
  h+='</div>';
  h+='<div class="notes-input-row"><textarea id="noteInput" placeholder="Add a note\u2026" onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();addNote()}"></textarea><button class="notes-add" onclick="addNote()">+ Add</button></div>';
  panel.innerHTML=h;
}
function addNote(){if(!currentUserId||!getCurrentUser())return; /* F-08: nothing is written with no one signed in */
  var inp=$('noteInput');if(!inp||!inp.value.trim())return;
  var cu=getCurrentUser();
  if(!data.notes)data.notes=[];
  var _nid=uid();data.notes.push({id:_nid,text:inp.value.trim(),by:cu?cu.id:null,byName:cu?cu.name:null,page:currentPage,step:currentStep,where:notesWhere(),ts:Date.now()});
  inp.value='';
  Store.commit('notes',_nid) /* 28 Sep 2026 (Paul: conform to the family standard, Rollout item 9): the save names the record it changed */;renderNotesPanel();updateNotesCount();
}
function deleteNote(id){
  data.notes=(data.notes||[]).filter(function(n){return n.id!==id});
  Store.commit('notes',id) /* 28 Sep 2026 (Paul: conform to the family standard, Rollout item 9): the save names the record it changed */;renderNotesPanel();updateNotesCount();
}
function goToNote(id){
  var n=(data.notes||[]).find(function(x){return x.id===id});if(!n||!n.page)return;
  if(n.page==='step'&&n.step)go('step',n.step);
  else if(n.page==='phaseHome'&&n.step)go('phaseHome',n.step);
  else if(n.page==='outcome'&&n.step)go('outcome',n.step);
  else go(n.page);
}

