  h+='<div class="coach-ctx"><div class="coach-ctx-txt">Context: '+esc(currentPage==='step'&&currentStep?('Step '+currentStep):notesWhere())+'</div></div>';
  h+='<div class="coach-msgs" id="coachMsgsEl">';
  for(var i=0;i<coachMsgs.length;i++){
    var m=coachMsgs[i];
    h+='<div class="coach-msg '+(m.role==='user'?'user':'ai')+'">'+esc(m.text)+'</div>';
  }
  if(_coachThinking)h+='<div class="coach-msg ai" style="opacity:.6">Thinking\u2026</div>';
  h+='</div>';
  h+='<div class="coach-presets">';
  var presets=['Where do I start?','Help with this step','What is zero-trust identity?','Explain the five layers','Shadow AI remediation?'];
  for(var i=0;i<presets.length;i++)h+='<button class="coach-preset" onclick="sendCoachPreset(\''+presets[i].replace(/'/g,"\\'")+'\')">'+presets[i]+'</button>';
  h+='</div>';
  h+='<div class="coach-input-row"><textarea id="coachInput" placeholder="Ask about any step, layer, or decision\u2026" onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();sendCoach()}"></textarea><button class="coach-send" onclick="sendCoach()">\u2192</button></div>';
  panel.innerHTML=h;
