'out-dgreview':function(){return printDocFromScreen(renderOutDgReview,'Data Governance Review Report','What the Data Governance Review Forum found and decided at its latest meeting, and the record of the meetings before it.',dgLog().length+' review'+(dgLog().length===1?'':'s')+' logged')}, /* 6 Sep 2026 */
  'out-embedreview':function(){return printDocFromScreen(renderOutEmbedReview,'Architecture Review Report','How far the organization\u2019s architecture moved in ninety days, what its review board decided, and what it committed to next.',arLog().length+' review'+(arLog().length===1?'':'s')+' logged')}, /* 3 Sep 2026 (Paul's ruling): no portfolio gate; the report reads the logged review */
