/* Phase 3/4 reporting, 22 September 2026. These helpers add report-specific layout to
   the existing output model. They do not change any Phase 1/2 output composition. */
function standingReportStyles(){return '<style>.report-v2{overflow-wrap:anywhere;--paper:#111;--stone:#555;--ink:#fff;--text-faint:#555;--text-muted:#555;--fg-rgb:17,17,17;--head-blue:#076D9E}.report-v2 .report-section{margin:0 0 22px;break-inside:auto}.report-v2 .report-kick{break-after:avoid;page-break-after:avoid}.report-v2 .ly-group{break-inside:avoid;page-break-inside:avoid}.report-v2 table{overflow-wrap:anywhere}.report-v2 thead{display:table-header-group}.report-v2 tr{break-inside:avoid;page-break-inside:avoid}.report-v2 .ly-rec{break-before:auto!important;page-break-before:auto!important}.report-v2 .report-table{table-layout:fixed}.report-v2 .report-table td{white-space:pre-line}.report-v2 .report-table th{break-after:avoid}.report-v2 svg{max-width:100%;height:auto}.report-v2 .report-figure{break-inside:avoid;page-break-inside:avoid}.report-v2 .report-table-wrap{overflow:visible}.report-v2 .report-record-note{font-size:12px;color:#555}.report-v2 .report-record-card>div:not(:first-child){white-space:pre-line}.report-v2 .er-figs{gap:8px}.report-v2 .ly-rec td{white-space:pre-line;padding:4px 8px!important;font-size:12px!important;line-height:1.45!important}.report-v2 .report-sub{display:block;font-size:11.5px;font-weight:400;color:#666;margin-top:3px;line-height:1.5}.report-v2 .report-table td:first-child{font-weight:600}.report-v2 .report-table th,.report-v2 .report-table td{padding:7px 8px}.report-v2 .report-table th{font:10px var(--mono,monospace);letter-spacing:.05em;text-transform:uppercase;color:#444;border-bottom:2px solid #111}.report-v2 .report-table td{font-size:12px;line-height:1.5;color:#111;border-bottom:1px solid #ddd;vertical-align:top}</style>'}
function reportTable(it,paper){
 var ink=paper?'#111':'var(--paper)',mute=paper?'#555':'var(--stone)';
 var h='<div class="report-table-wrap"><table class="report-table" style="width:100%;border-collapse:collapse;margin:0 0 16px;table-layout:fixed">';
 if(it.widths)h+='<colgroup>'+it.widths.map(function(w){return '<col style="width:'+Number(w)+'%">'}).join('')+'</colgroup>';
 h+='<thead><tr>'+it.cols.map(function(c){return '<th scope="col" style="text-align:left;vertical-align:bottom;padding:7px 8px;font-family:var(--mono,monospace);font-size:10px;color:'+mute+';border-bottom:2px solid '+ink+'">'+esc(c)+'</th>'}).join('')+'</tr></thead><tbody>';
 (it.rows||[]).forEach(function(r){h+='<tr>'+r.map(function(v,i){var o=(v&&typeof v==='object'&&!Array.isArray(v))?v:{text:lyText(v)};return '<td style="padding:7px 8px;vertical-align:top;font-size:12.5px;line-height:1.5;overflow-wrap:anywhere;white-space:pre-line;color:'+ink+';border-bottom:1px solid '+(paper?'#ddd':'rgba(var(--fg-rgb),.12)')+';'+(i===0?'font-weight:600;':'')+'">'+esc(o.text||'Not recorded')+(o.sub?'<span class="report-sub" style="display:block;font-weight:400;font-size:11.5px;line-height:1.5;color:'+mute+';margin-top:3px">'+esc(o.sub)+'</span>':'')+'</td>'}).join('')+'</tr>'});
 return h+'</tbody></table></div>';
}
function reportDate(v){if(!v)return '';if(/^\d{4}-\d{2}-\d{2}$/.test(String(v)))return lyDate(String(v)+'T12:00:00');return lyDate(v)}
function reportPlain(v){return String(v||'').replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&nbsp;/g,' ')}
function reportGateLabel(dp){var g=gateState(dp);return {open:'Proceed',conditional:'Conditional',blocked:'Blocked',unanswered:'Unanswered',undecided:'Decision pending'}[g.s]||'Not recorded'}
function reportFlowCoverage(){var fs=(data.flows||[]).filter(function(f){return f&&f.appId});var linked={};(data.deployments||[]).forEach(function(d){if(d.flowId&&fs.some(function(f){return f.id===d.flowId&&f.appId===d.appId}))linked[d.flowId]=1});return {total:fs.length,linked:Object.keys(linked).length}}
function reportDeploymentFlow(dp){return (data.flows||[]).find(function(f){return f.id===dp.flowId&&f.appId===dp.appId})||null}
function reportDeploymentIssues(dp){
 var result=[];deployReadout(dp).filter(function(r){return r.color==='red'||r.color==='amber'}).forEach(function(r){var a=dpRowAct(dp,r);result.push({title:r.text,tag:r.color==='red'?'Rule breach':'Architectural risk',col:r.color==='red'?'#6E4A5A':'#7A6B4A',source:'Automatic check of the current record',description:'',action:a.act||'',owner:a.owner||'',date:'',horizon:a.hor||'',status:'Present in the current record',kind:'derived'})});
 (dp.findings||[]).filter(Boolean).forEach(function(f){result.push({title:f.title||f.text||'Issue',tag:f.severity||'Severity not recorded',col:sevColor(f.severity),source:'Logged issue'+(f.layer?' · '+f.layer:''),description:f.description||'',action:f.remediation||'',owner:f.owner||'',date:f.date||'',horizon:'',status:reportRemStatus(f),kind:'manual'})});return result;
}
function reportFlowDiagram(dp,paper){
 var fl=reportDeploymentFlow(dp);if(!fl)return '';
 var sc=dpFlowScope(dp);if(!sc)return '';var ids={};ids[dp.appId]=1;(fl.steps||[]).forEach(function(st){ids[st.componentId]=1;(st.srcPicks||[]).forEach(function(x){ids[x]=1})}); /* 23 Sep 2026 (the Phase 3 re-audit): the upstream sources the trace selected, and only those, as in the working diagram and the conformance check */
 Object.keys(ids).forEach(function(id){var c=compById(id);if(compLayerKey(id)==='aiModels'&&c)(c.computeLinks||[]).forEach(function(x){ids[x]=1})});
 var svg=buildLocalFlowSVG({ids:ids,edges:sc.edges.filter(function(e){return ids[e.from]&&ids[e.to]}),picked:{},bright:{},pickable:{},ghost:false,direct:{},anchor:dp.appId,reveal:true});
 svg=lyStripControls(svg);
 // The drawn geometry is the working map's; report labels are slightly larger, and full names
 // are also printed in the component list so the diagram is never the sole source of a name.
 svg=svg.replace(/font-size="(\d+(?:\.\d+)?)"/g,function(m,n){return 'font-size="'+(Number(n)<9?9:Number(n))+'"'});if(paper)svg=svg.replace(/var\(--paper\)/g,'#111').replace(/var\(--stone\)/g,'#555').replace(/var\(--ink\)/g,'#fff');
 return '<div class="report-figure">'+svg+'</div>';
}
function reportAnswerLines(a){a=a||{};return 'Answer: '+(a.answer||a.a||'Not recorded')+'<br>Evidence: '+(a.evidence||a.ev||'Not recorded')+(a.gaps?'<br>Gaps or remediation: '+a.gaps:'')}
function reportFindingLines(f){if(typeof f==='string')return f;return ['Issue: '+(f.title||f.text||'Not recorded'),'Severity: '+(f.severity||'Not recorded'),f.layer?'Layer: '+f.layer:'','Description: '+(f.description||'Not recorded'),'Remediation: '+(f.remediation||'Not recorded'),'Owner: '+(f.owner||'Not recorded'),f.date?'Target date: '+reportDate(f.date):'','Remediation status: '+reportRemStatus(f)].filter(Boolean).join('<br>')}
function reportTestStanding(t,kind){return (kind==='security'?(t.status==='Partial'?'Partial pass':t.status):t.grade)||'Not yet tested'}
function reportTestColor(t,kind){var st=reportTestStanding(t,kind);return st==='Pass'||st==='Contained'?'#3D6B6E':st==='Fail'||st==='Cascaded'?'#6E4A5A':st==='Partial pass'||st==='Contained with gaps'?'#7A6B4A':'#8A8278'}
function reportTestModel(kind,paper){ /* 23 Sep 2026 (Paul): the cascade report's scenario list is headed The Scenarios again, the matrix directly beneath it, as the report's first section so it can never stand alone at a page's foot */
 var sec=kind==='security',refs=reportTestRefs(kind),get=sec?secRec:casRec,area=sec?secArea:casScen,stats=sec?secTestSummary():casTestSummary();
 var any=refs.some(function(r){var t=get(r);return t.name||t.status||t.grade||t.method||t.findings||t.remediation||t.owner||t.date});
 if(!any)return report34Empty(sec?'Security and Identity Tests':'Cascade Failure Scenarios',sec?'No security or identity test has been run yet.':'No cascade failure scenario has been run yet.');
 var unresolved=refs.filter(function(r){var t=get(r);return reportTestNeedsRem(t,kind)&&reportRemStatus(t)!=='Done'});
 var incomplete=refs.filter(function(r){var t=get(r);return (sec?['Pass','Partial','Fail'].indexOf(t.status)>=0:['Contained','Contained with gaps','Cascaded'].indexOf(t.grade)>=0)&&!(String(t.method||'').trim()&&String(t.findings||'').trim())}).length;
 var figs=[{v:refs.length,l:sec?'Areas':'Scenarios'},{v:stats.tested,l:'Tested'}];
 if(sec)figs=figs.concat([{v:stats.pass,l:'Passed',vcol:'#3D6B6E'},{v:stats.partial,l:'Partial pass',vcol:'#7A6B4A'},{v:stats.fail,l:'Failed',vcol:'#6E4A5A'}]);else figs=figs.concat([{v:stats.contained,l:'Contained',vcol:'#3D6B6E'},{v:stats.gaps,l:'Contained with gaps',vcol:'#7A6B4A'},{v:stats.cascaded,l:'Cascaded',vcol:'#6E4A5A'}]);figs.push({v:stats.untested,l:'Not tested'});
 var rows=refs.map(function(r){var t=get(r),a=area(r)||{},needs=reportTestHasRem(t,kind);return [{text:a.name||'Unnamed test',sub:r.x!=null?'Organization-defined test':''},reportTestStanding(t,kind),t.remStatus||(reportTestNeedsRem(t,kind)?'Open':'—'),needs&&t.date?reportDate(t.date):'—']});
 var m={reportV2:true,reportV3:true,figs:figs,sections:[{title:sec?'Coverage and Results':'The Scenarios',sub:stats.tested+' of '+refs.length+' tested',flow:true,items:[{k:'matrix',cols:[sec?'Test area':'Scenario','Result','Remediation status','Target date'],widths:[37,21,23,19],rows:rows}]}]};
 if(!stats.tested)m.sections[0].items.unshift({k:'note',text:sec?'No security or identity test has been run yet.':'No cascade failure scenario has been run yet.'});
 if(incomplete)m.sections[0].items.push({k:'note',text:incomplete+' result'+(incomplete===1?' is':'s are')+' missing a test description or findings.'});
 var fixes=unresolved.map(function(r){var t=get(r),a=area(r)||{};return {title:a.name||'Test',tag:reportTestStanding(t,kind),col:reportTestColor(t,kind),lines:[['Findings',t.findings||'Not recorded'],['Remediation required',t.remediation||'Not recorded'],['Remediation owner',t.owner||'Not recorded'],['Target date',t.date?reportDate(t.date):'Not recorded'],['Severity',t.severity||'Not recorded'],['Remediation status',reportRemStatus(t)]]}});
 m.sections.push({title:'What Remains to Be Fixed',page:true,sub:unresolved.length+' unresolved',flow:true,items:fixes.length?[{k:'cards',cards:fixes}]:[{k:'note',text:'No unresolved remediation is recorded.'}]});
 if((UI.printDepth||'summary')==='full')m.sections.push({title:sec?'The Test Records':'The Scenario Records',sub:'Method, findings, and remedial work',items:[{k:'register',type:kind,recs:refs,groups:[{name:sec?'The Test Records':'The Scenario Records',list:refs}],recOf:get,rowStanding:function(t){return reportTestStanding(t,kind)},standCol:function(t){return reportTestColor(t,kind)},rowCol:function(t){return reportTestColor(t,kind)}}]});return m;
}
function securityModel(paper){return reportTestModel('security',paper)}
function cascadeModel(paper){return reportTestModel('cascade',paper)}
function renderOutSecurity(){var h=docHead('Security and Identity Test Report','Phase 3: Test \u00b7 how the organization\u2019s identity and security controls held when tested, area by area.','out-security');return h+omPage(securityModel(false))}
