function cascadeDoc(){installComponentMaps();return omDoc(cascadeModel(true),'Cascade Failure Report','Whether a failure in one of the organization\u2019s systems stays contained, scenario by scenario.')}

/* ── Sovereignty Validation: one model (22 Sep 2026) ── */
/* Sovereignty reporting: action status, action effectiveness and condition standing are
   distinct. Applicability changes and new answers are never counted as improvements. */
function reportSovRecord(key){return ((data.sovProgram||{}).items||{})[key]||{}}
function reportSovActions(){return (((data.sovProgram||{}).actions)||[]).filter(function(a){return a&&String(a.text||'').trim()})}
function reportSovQuestion(key){return SOV_PROGRAM.find(function(it){return it.k===key})||{k:key,t:'Condition no longer in the program',d:''}}
function reportSovMovement(r){
 var rank={No:0,Partly:1,Yes:2};if(!r.now)return {kind:'carried',label:r.status?'Not reassessed; baseline carried forward':'Not answered'};
 if(!r.status)return {kind:'new',label:'First recorded answer; no baseline comparison'};
 if(r.status==='Not applicable'||r.now==='Not applicable')return {kind:r.status===r.now?'unchanged':'applicability',label:r.status===r.now?'Still not applicable':'Applicability changed'};
 if(rank[r.status]===undefined||rank[r.now]===undefined)return {kind:'other',label:'Answer not comparable'};
 return rank[r.now]>rank[r.status]?{kind:'improved',label:'Improved'}:rank[r.now]<rank[r.status]?{kind:'deteriorated',label:'Deteriorated'}:{kind:'unchanged',label:'Unchanged'};
}
function reportSovAnswerCounts(items,current){var c={Yes:0,Partly:0,No:0,na:0,blank:0};items.forEach(function(it){var r=reportSovRecord(it.k),st=current?(r.now||r.status):r.status;if(st==='Not applicable')c.na++;else if(st==='Yes'||st==='Partly'||st==='No')c[st]++;else c.blank++});return c}
function reportSovCountText(c){return c.Yes+' Yes, '+c.Partly+' Partly, '+c.No+' No'+(c.na?', '+c.na+' not applicable':'')+(c.blank?', '+c.blank+' not answered':'')}
LAYER_MAPS.sovcondition={
 identity:function(r){var it=reportSovQuestion(r.k),rec=reportSovRecord(r.k);return {title:it.t,score:rec.now?'Revised: '+rec.now:rec.status?'Baseline: '+rec.status:'Not answered',meta:[]}},
 layers:[{id:'condition',title:'Baseline and reassessment',stage:'3.4',present:function(){return true},fields:[
 {label:'Baseline question',get:function(r){return reportSovQuestion(r.k).d},summary:true},
 {label:'Baseline answer',get:function(r){return reportSovRecord(r.k).status},summary:true},
 {label:'Reassessment question',get:function(r){var it=reportSovQuestion(r.k);return it.n||it.d}},
 {label:'Revised answer',get:function(r){var rec=reportSovRecord(r.k);return rec.now||(rec.status?'Not reassessed; baseline carried forward':'Not answered')},summary:true},
 {label:'Change',get:function(r){return reportSovMovement(reportSovRecord(r.k)).label},summary:true},
 {label:'What was the situation at the baseline?',get:function(r){return reportSovRecord(r.k).account}},
 {label:'How did you know?',get:function(r){return reportSovRecord(r.k).basis}},
 {label:'Who was responsible at the baseline?',get:function(r){var rec=reportSovRecord(r.k);return rec.resp==='Someone'?(rec.respName||'Someone, unnamed'):rec.resp==='No one'?'No one':''}},
 {label:'What was missing?',when:function(r){var rec=reportSovRecord(r.k);return rec.status==='No'||rec.status==='Partly'||!!rec.gap},get:function(r){return reportSovRecord(r.k).gap}},
 {label:'Action evidence in this report',list:true,get:function(r){return reportSovActions().map(function(a,i){return a.item===r.k?'Action '+(i+1)+': '+a.text:null}).filter(Boolean)},summary:true}
 ]}]};

function sovValModel(paper){
 report34InstallMaps();var acts=reportSovActions(),completed=acts.filter(function(a){return a.done==='Completed'}),solved=completed.filter(function(a){return a.worked==='Solved'}),revised=SOV_PROGRAM.filter(function(it){return !!reportSovRecord(it.k).now}).length;
 if(!acts.length&&!SOV_PROGRAM.some(function(it){var r=reportSovRecord(it.k);return r.status||r.now||r.account||r.basis||r.gap}))return report34Empty('Sovereignty Validation','None of the sovereignty questions has been answered yet.');
 var m={reportV2:true,reportV3:true,figs:[{v:acts.length,l:'Actions'},{v:completed.length,l:'Completed',vcol:'#3D6B6E'},{v:solved.length,l:'Completed and solved',vcol:'#3D6B6E'},{v:revised,l:'Questions asked again'}],sections:[]};
 m.sections.push({title:'Reassessment by Dimension',flow:true,items:[{k:'matrix',cols:['Dimension','In place at the baseline','At the baseline','Answer now','Change'],widths:[20,13,24,24,19],rows:SOV_DIMS.map(function(dm){var items=SOV_PROGRAM.filter(function(it){return it.dim===dm.k}),score=sovBaselineStanding(dm.k),now={Yes:0,Partly:0,No:0,na:0,blank:0};items.forEach(function(it){var r=reportSovRecord(it.k);if(!r.now)return;if(r.now==='Not applicable')now.na++;else if(now[r.now]!=null)now[r.now]++});return [dm.name,score,reportSovCountText(reportSovAnswerCounts(items,false)),items.some(function(it){return !!reportSovRecord(it.k).now})?reportSovCountText(now):'—',report34MovementText(items)]})}]});
 var standing=SOV_PROGRAM.filter(function(it){var r=reportSovRecord(it.k);return ['Yes','Not applicable'].indexOf(r.now||r.status)<0});
 m.sections.push({title:'Questions Needing Action',page:true,sub:standing.length+' questions',flow:true,items:standing.length?[{k:'matrix',cols:['Question','Answers','Actions'],widths:[40,38,22],rows:standing.map(function(it){var refs=[];acts.forEach(function(a,i){if(a.item===it.k)refs.push('Action '+(i+1))});return [{text:it.t,sub:(SOV_DIMS.find(function(d){return d.k===it.dim})||{}).name||''},report34AnswerStanding(reportSovRecord(it.k)),refs.join(', ')||'None recorded']})}]:[{k:'note',text:'No sovereignty question currently requires action.'}]});
 var cards=acts.map(function(a,i){var it=reportSovQuestion(a.item),c=a.done==='Completed'&&a.worked==='Solved'?'#3D6B6E':a.done==='Abandoned'||a.worked==='Did not solve'?'#6E4A5A':'#7A6B4A';return {title:'Action '+(i+1)+' · '+it.t,tag:a.done||'Not recorded',col:c,lines:[['Action',a.text],['Expected result',a.expected||'Not recorded'],['Owner',a.owner||'Not recorded'],['Target date',a.date?reportDate(a.date):'Not recorded'],['Action completed?',a.done||'Not recorded'],['Did it work?',a.worked||'Not recorded'],['What you found',a.found||'Not recorded'],['Answers',report34AnswerStanding(reportSovRecord(a.item))]]}});
 SOV_PROGRAM.forEach(function(it){var rc=(sovProg().items||{})[it.k]||{};var op=rc.status==='No'||rc.status==='Partly';if(op&&rc.noAction&&!sovItemActions(it.k).some(function(a){return a.text&&String(a.text).trim()}))cards.push({title:it.t,col:'#8A8278',lines:[['No action was planned',rc.noActionReason||'No reason recorded'],['Revised answer',rc.now||'Not yet given']]})}); /* 23 Sep 2026 (the Phase 3 re-audit): a considered decision not to act is reported with its reason */
  m.sections.push({title:'Actions and Their Results',page:true,flow:true,items:cards.length?[{k:'cards',cards:cards}]:[{k:'note',text:'No sovereignty actions have been recorded.'}]});
 if((UI.printDepth||'summary')==='full')SOV_DIMS.forEach(function(dm){var refs=SOV_PROGRAM.map(function(it,i){return {i:i,k:it.k,dim:it.dim}}).filter(function(r){return r.dim===dm.k});m.sections.push({title:dm.name+' · Validation Record',items:[{k:'register',type:'sovquestionReport',recs:refs,groups:[{name:dm.name+' · Validation Record',list:refs}],recOf:function(r){return reportSovRecord(r.k)},rowStanding:report34AnswerStanding,rowMeta:report34Movement}]})});return m;
}
function renderOutSovVal(){var h=docHead('Sovereignty Validation Report','Phase 3: Test \u00b7 where the organization stands on each part of sovereignty after the actions it committed to, beside where it stood at the baseline.','out-sovval');return h+omPage(sovValModel(false))}
function sovValDoc(){return omDoc(sovValModel(true),'Sovereignty Validation Report','Where the organization stands on each part of sovereignty after the actions it committed to, beside where it started.')}

/* ── Risk Map, Skills Gap Plan, Architecture Review Report, Quarterly, Data Governance Review Report, Readiness Report: one model each (22 Sep 2026) ── */
function riskMapModel(paper){var scenarios=data.riskScenarios||[];var recs=RISK_SCENARIOS.map(function(sc,i){return {i:i}});var scored=recs.filter(function(r){var d=riskOf(r);return d.likelihood&&d.impact&&d.timeHorizon});var comp=function(sc){return (+sc.likelihood||0)+(+sc.impact||0)+(+sc.timeHorizon||0)};var sev=function(c){return c>=12?'Critical':c>=8?'High':c>=5?'Medium':'Low'};var scol=function(c){return c>=12?'#6E4A5A':c>=8?'#7A6B4A':c>=5?'#4A6E8A':'#3D6B6E'};var high=scored.filter(function(r){return comp(riskOf(r))>=12}).length;
  /* 22 Sep 2026 (Paul): Step 1.4's own score and bands, likelihood plus impact plus time horizon out of 15, Critical from 12; the same on the dashboard and behind the heat map's colours */
  var m={figs:[{v:RISK_SCENARIOS.length,l:'Scenarios'},{v:scored.length,l:'Assessed'},{v:high,l:'Critical (12 or more of 15)',vcol:high?'#6E4A5A':undefined}],sections:[]};
  if(!scored.length){m.sections.push({title:'The Scenarios',sub:'',items:[{k:'note',text:'No risk scenario has been scored yet.'}]});return m}
  m.sections.push({title:'Risk Heat Map',sub:'Likelihood against impact',items:[{k:'svg',svg:riskHeatSVG(scenarios)}]});
  m.sections.push({title:'The Scenarios',sub:'',items:[{k:'register',type:'risk',recs:recs,groups:[{name:'The Scenarios',list:recs}],recOf:function(r){return (data.riskScenarios||[])[r.i]||{}},rowMeta:function(sc){return ''},rowStanding:function(sc){var c=comp(sc);return c?sev(c)+' \u00b7 '+c+' of 15':'Not scored'},standCol:function(sc){return scol(comp(sc))},rowCol:function(sc){return scol(comp(sc))}}]});
  return m}
function renderOutRiskMap(){var h=docHead('Architectural Risk Map','Phase 1: Map \u00b7 synthesized from the Architectural Risk Scenarios assessment','out-riskmap');return h+omPage(riskMapModel(false))}
function riskMapDoc(){installComponentMaps();return omDoc(riskMapModel(true),'Architectural Risk Map','The architectural risk scenarios, scored for likelihood, impact, and time horizon.')}
function skillsModel(paper){ /* 23 Sep 2026 (Paul, the 4.1 redesign): the open action plans grouped by approach (a plan with several approaches appears under each), then the gaps without a plan, then the completed plans */
  var refs=CAPABILITY_AREAS.map(function(a,i){return {i:i}}),inv=skAll();
  if(!inv.some(function(t){return t.strength||t.plans.length||(t.teamList||[]).length||(t.gapList||[]).length}))return report34Empty('The Capability Areas','No capability assessment or action plan has been recorded yet.');
  var open=[],done=[];inv.forEach(function(t,i){t.plans.filter(skPlanReal).forEach(function(p){(p.done?done:open).push({i:i,p:p})})});
  var gapsNo=refs.filter(function(r){return skGapNoPlan(inv[r.i])});
  var nm=function(i){var a=CAPABILITY_AREAS[i];return a.name||a};var ptxt=function(p){return (p.name?p.name+(p.plan?': ':''):'')+(p.plan||'')||'Not recorded'};
  var m={reportV2:true,reportV3:true,figs:[{v:refs.length,l:'Capability areas'},{v:refs.filter(function(r){return !!inv[r.i].strength}).length,l:'Assessed'},{v:open.length,l:'Open plans'},{v:done.length,l:'Plans complete',vcol:'#3D6B6E'},{v:gapsNo.length,l:'Gaps without a plan',vcol:gapsNo.length?'#6E4A5A':'#3D6B6E'}],sections:[]};
  m.sections.push({title:'Capability Strengths',sub:'Current strength, from 1 to 5',items:[{k:'bars',rows:refs.map(function(r){return {l:nm(r.i),v:Number(inv[r.i].strength)||0,max:5}})}]});
  var items=[];
  [['Hire','Hire: recruit externally','hire'],['Develop','Develop: train the existing team','develop'],['Partner','Partner: use an external provider','partner']].forEach(function(d){var L=open.filter(function(x){return x.p[d[2]]});items.push({k:'kick',text:d[1]});items.push(L.length?{k:'matrix',cols:['Capability','Action plan','Owner','Target date'],widths:[26,42,16,16],rows:L.map(function(x){return [nm(x.i),ptxt(x.p),x.p.owner||'Not recorded',x.p.date?reportDate(x.p.date):'Not recorded']})}:{k:'note',text:'No open plan takes this approach.'})});
  var none=open.filter(function(x){return !skApproaches(x.p).length});if(none.length){items.push({k:'kick',text:'No approach chosen'});items.push({k:'matrix',cols:['Capability','Action plan','Owner','Target date'],widths:[26,42,16,16],rows:none.map(function(x){return [nm(x.i),ptxt(x.p),x.p.owner||'Not recorded',x.p.date?reportDate(x.p.date):'Not recorded']})})}
  items.push({k:'kick',text:'Gaps without a plan'});items.push(gapsNo.length?{k:'matrix',cols:['Capability','Strength','What is missing?'],widths:[30,14,56],rows:gapsNo.map(function(r){var t=inv[r.i];return [nm(r.i),t.strength?t.strength+' of 5':'Not assessed',skGapText(t).join('; ')||'Not recorded']})}:{k:'note',text:'Every gap has an open plan.'});
  if(done.length){items.push({k:'kick',text:'Plans complete'});items.push({k:'matrix',cols:['Capability','Action plan','Owner','Completed'],widths:[26,42,16,16],rows:done.map(function(x){return [nm(x.i),ptxt(x.p),x.p.owner||'Not recorded',x.p.doneAt?reportDate(x.p.doneAt):'Not recorded']})})}
  m.sections.push({title:'The Capability Areas',flow:true,items:items});
  if((UI.printDepth||'summary')==='full')m.sections.push({title:'The Capability Records',sub:'Current people, gaps, and plans',items:[{k:'register',type:'skill',recs:refs,groups:[{name:'The capability areas',list:refs}],recOf:function(r){return inv[r.i]},rowMeta:function(t){return skGapText(t).join('; ')},rowStanding:function(t){return t.strength?t.strength+' of 5':'Not assessed'}}]});
  return m;
}
