/* Architecture Review report provenance. Old reviews are never silently reconstructed
   from today's estate. New logs retain a small, versioned projection of the report facts. */
function reportClone(x){return JSON.parse(JSON.stringify(x))}
function reportBoardMembers(){var org=data.rbOrg||{};return Array.isArray(org.members)?org.members:((data.reviewBoard||{}).members||[])}
function reportScoreValue(source,layer,key){var o=(source||{})[layer];if(!o||typeof o!=='object')return 0;var aliases={scaling:'scalability',scalability:'scaling',approval:'governance',governance:'approval',api:'apiReadiness',apiReadiness:'api'};var k=Object.prototype.hasOwnProperty.call(o,key)?key:aliases[key];var raw=k?o[k]:null;if(raw===null||raw===undefined||raw==='')return 0;var n=Number(raw);return isFinite(n)&&n>=1&&n<=5?n:0}
function reportReviewEntries(){return (data.archReviewLog||[]).map(function(e,i){return {key:e.id||('legacy-'+i+'-'+String(e.at||'undated')),entry:e,index:i}})}
function reportReviewSource(){
 var entries=reportReviewEntries(),ref=UI.reportReviewRef||'latest';
 if(ref==='draft'||(ref==='latest'&&!entries.length))return {kind:'draft',ref:'draft',entry:null,rr:data.reviewResults||{}};
 var found=ref==='latest'?entries[entries.length-1]:entries.find(function(e){return e.key===ref});
 if(!found)return {kind:'missing',ref:ref,entry:null,rr:{}};
 return {kind:'logged',ref:found.key,index:found.index,entry:found.entry,rr:found.entry};
}
function reportReviewLabel(ref){var old=UI.reportReviewRef;UI.reportReviewRef=ref||'latest';var src;try{src=reportReviewSource()}finally{UI.reportReviewRef=old}return src.kind==='draft'?'Current review — not logged':src.kind==='missing'?'Selected review is unavailable':('Review '+(src.index+1)+(src.entry.at?' · '+reportDate(src.entry.at):' · date not recorded'))}
function reportReviewSelectHTML(selected,handler){var options=[{v:'latest',l:'Latest logged review'},{v:'draft',l:'Current review — not logged'}];reportReviewEntries().forEach(function(x){options.push({v:x.key,l:'Review '+(x.index+1)+(x.entry.at?' · '+reportDate(x.entry.at):' · date not recorded')+(x.entry.by?' · '+x.entry.by:'')})});if(selected&&!options.some(function(x){return x.v===selected}))options.push({v:selected,l:'Selected review is unavailable'});return '<select aria-label="Choose the Architecture Review to report" onchange="'+handler+'" style="font-size:13px;padding:8px;max-width:100%;background:var(--bg-input);color:var(--paper);border:1px solid var(--rule)">'+options.map(function(o){return '<option value="'+escAttr(o.v).replace(/"/g,'&quot;')+'"'+(o.v===(selected||'latest')?' selected':'')+'>'+esc(o.l)+'</option>'}).join('')+'</select>'}
function reportReviewControl(pid){
 var entries=reportReviewEntries(),example=reportExampleReviewEntry(),demo=reportIsFullExample(),standing=pid==='archreview';
 var status=entries.length?entries.length+' logged review'+(entries.length===1?'':'s')+' available.':'No logged reviews.';
 var source=reportReviewSource();if(source.kind==='draft')status+=' Showing the current, unlogged review.';else if(source.kind==='missing')status+=' The selected review is unavailable.';
 var action=standing?"p5Print('archreview')":"printOutput('"+(pid||'out-embedreview')+"')";
 return '<div class="review-report-controls print-bar"'+(standing?' data-print-page="archreview"':'')+'><div class="review-print-row"><label class="review-print-choice">Review included in this '+(standing?'report':'output')+reportReviewSelectHTML(UI.reportReviewRef||'latest',"UI.reportReviewRef=this.value;render()")+'</label>'+reportDepthTabs(standing?'archreview':null)+'<button class="btn bg2" onclick="'+action+'">▾ Save as PDF</button></div><div class="review-selection-info"><span>'+esc(status)+'</span>'+(demo?'<button class="btn bg2" data-review-example="1" onclick="reportOpenExampleReview()">'+(reportExampleReviewComplete(example)?'View logged example review':'Load logged example review')+'</button>':'')+'</div></div>';
}
/* The example action is explicit and demo-only. It never logs or clears a real working review. */
function reportIsFullExample(){var e=data.enterprise||{};return e.name==='Meridian Components'&&e.website==='meridiancomponents.example'&&reportBoardMembers().some(function(m){return m&&m.name==='Vincent Lau'})}
function reportExampleReviewEntry(){return reportReviewEntries().find(function(x){return x.entry.id==='ar-seed-20260904'||(!x.entry.id&&x.entry.at===Date.UTC(2026,8,4,14)&&x.entry.by==='Vincent Lau, VP Engineering')})||null}
function reportExampleReviewComplete(x){var e=x&&x.entry,s=e&&e.reportSnapshot;return !!(s&&s.standing&&Array.isArray(s.agenda)&&s.agenda.length>=ARCH_REVIEW_AGENDA.length&&s.agenda.every(function(a){return !!a.covered})&&Array.isArray(s.board)&&s.board.length&&e.worked&&e.didnt&&e.risk&&RESCORE_LAYERS.every(function(l){return l[3].every(function(q){return !!reportScoreValue(e.rescores,l[0],q[0])})}))}
function reportOpenExampleReview(){
 if(!reportIsFullExample())return false;
 var existing=reportExampleReviewEntry();
 if(reportExampleReviewComplete(existing)){UI.reportReviewRef=existing.key;render();return true;}
 if(!confirm('Load a complete logged example review for Meridian Components? Only the example review is added or completed. Your other records and current working review are kept.'))return false;
 var at=Date.UTC(2026,8,4,14),by='Vincent Lau, VP Engineering',held=seedArchitectureReviewResults();
 held.decisions=[];delete held.actions; /* 23 Sep 2026 (Paul, keeping his ruling of 8 Sep 2026): the Architecture Review keeps no decisions list; the layers' plans are the record */
 if(existing){var old=existing.entry;['worked','didnt','risk'].forEach(function(k){if(old[k])held[k]=old[k]});RESCORE_LAYERS.forEach(function(l){l[3].forEach(function(q){var v=reportScoreValue(old.rescores,l[0],q[0]);if(v)held.rescores[l[0]][q[0]]=v})});}
 held.walk={};ARCH_REVIEW_AGENDA.forEach(function(a){held.walk[a.k]={by:by,at:at}});arCustomAgenda().forEach(function(a,i){held.walk[rbAgendaKey(i)]={by:by,at:at}});
 var snap=p5Read(function(){return reportReviewSnapshot(held)});snap.capturedAt=at;
 var layers={};RESCORE_LAYERS.forEach(function(l){layers[l[0]]=avgLayerScore(l[0],held.rescores)||null});
 var entry={id:'ar-seed-20260904',reportSnapshot:snap,walk:reportClone(held.walk),at:at,by:by,layers:layers,rescores:reportClone(held.rescores),worked:held.worked,didnt:held.didnt,risk:held.risk,decisions:reportClone(held.decisions)};
 var log=arLog();if(existing){if(!existing.entry.id)delete entry.id;log[existing.index]=entry;}else log.unshift(entry);
 if(entry&&entry.id)Store.commit('archReviewLog',entry.id);else Store.commit('archReviewLog');UI.reportReviewRef=existing?reportReviewEntries()[existing.index].key:entry.id;render();return true;
}
