function dgDonut(segs,total,label,paper){ /* 22 Sep 2026 (Paul): arcs drawn as paths, so every renderer draws the same ring; colours spread in luminance so the ring reads in grayscale; legend beneath its own ring */
  var R=50,W=30,cx=120,cy=120;var h='<div style="text-align:center"><svg viewBox="0 0 240 240" width="200" height="200">';var live=segs.filter(function(sg){return sg.v>0});var a0=-Math.PI/2;
  if(!total||!live.length)h+='<circle cx="'+cx+'" cy="'+cy+'" r="'+R+'" fill="none" stroke="'+(paper?'#e6e6e6':'rgba(90,125,138,.15)')+'" stroke-width="'+W+'"/>';
  else if(live.length===1)h+='<circle cx="'+cx+'" cy="'+cy+'" r="'+R+'" fill="none" stroke="'+live[0].c+'" stroke-width="'+W+'"/>';
  else live.forEach(function(sg){var a1=a0+2*Math.PI*sg.v/total;var ro=R+W/2,ri=R-W/2;var big=(a1-a0)>Math.PI?1:0;var p=function(r,a){return (cx+r*Math.cos(a)).toFixed(2)+','+(cy+r*Math.sin(a)).toFixed(2)};
    h+='<path d="M'+p(ro,a0)+' A'+ro+','+ro+' 0 '+big+',1 '+p(ro,a1)+' L'+p(ri,a1)+' A'+ri+','+ri+' 0 '+big+',0 '+p(ri,a0)+' Z" fill="'+sg.c+'"/>';a0=a1});
  h+='<text x="'+cx+'" y="115" text-anchor="middle" fill="'+(paper?'#111':'var(--paper)')+'" font-size="36" font-weight="300" font-family="'+(paper?'Georgia,serif':'var(--serif)')+'">'+total+'</text><text x="'+cx+'" y="136" text-anchor="middle" fill="'+(paper?'#666':'var(--stone)')+'" font-size="11" font-family="'+(paper?'monospace':'var(--mono)')+'">'+label+'</text></svg>';
  h+='<div style="display:flex;gap:14px;justify-content:center;margin-top:6px;flex-wrap:wrap">'+segs.filter(function(sg){return sg.v}).map(function(sg){return '<span style="font-size:12px;color:'+(paper?'#333':'var(--paper)')+'"><span style="display:inline-block;width:10px;height:10px;background:'+sg.c+';margin-right:5px;vertical-align:-1px"></span>'+sg.l+': '+sg.v+'</span>'}).join('')+'</div></div>';return h}
function dgDonutSegs(){var dg=data.dataGovernance||{},domains=dg.domains||[];var gold=0,silver=0,bronze=0,none=0;domains.forEach(function(d){if(d.qualityThreshold==='Gold')gold++;else if(d.qualityThreshold==='Silver')silver++;else if(d.qualityThreshold==='Bronze')bronze++;else none++});
  var est=componentRegisters().dataEstate||[];var gov={'Formally governed':0,'Partially governed':0,'Ungoverned':0};est.forEach(function(e){var st=dataGovStatus(e);gov[st]=(gov[st]||0)+1});
  /* luminance spread for grayscale: gold light (~66), silver mid (~47), bronze dark (~18), unset very light; governed teal (luminance ~90 of 255), partial light ochre (~194), ungoverned deep plum (~32) */
  return {domains:{segs:[{v:gold,c:'#C9A227',l:'Gold'},{v:silver,c:'#6E757C',l:'Silver'},{v:bronze,c:'#3E2A1A',l:'Bronze'},{v:none,c:'#D9D9D9',l:'Unset'}],total:domains.length,label:'DOMAINS'},systems:{segs:[{v:gov['Formally governed']||0,c:'#2F6B6E',l:'Formally governed'},{v:gov['Partially governed']||0,c:'#E0C36A',l:'Partially governed'},{v:gov['Ungoverned']||0,c:'#2B1A22',l:'Ungoverned'}],total:est.length,label:'SYSTEMS'}}}
