  if(svg)h+=erBlock(erHead('System Flow Diagram','')+'<div style="border:1px solid #ddd;border-radius:6px;padding:8px;margin:0 0 6px">'+lyStripControls(svg.replace(/<svg /,'<svg style="width:100%;height:auto;display:block" '))+'</div><p style="font-size:11px;color:#555;margin:0 0 18px">'+esc(amConnLine())+'</p>'); /* 21 Sep 2026 (Paul): the line naming what is shown and what is not */
  var reg='',li=0;COMP_KINDS.forEach(function(k){var recs=compRecs(k[0]);if(!recs.length)return;var blk=lyRegister('comp:'+k[0],recs,depth,null,k[0]==='agentRegistry'?componentAgentRecordGroups(recs):[{name:k[1],list:recs}]);reg+=(li>0?'<div style="break-before:page;page-break-before:always">'+blk+'</div>':blk);li++}); /* 21 Sep 2026 (Paul): each layer starts a fresh page; the first rides the section heading (22.4.5) */
  h+='<div style="break-before:page;page-break-before:always">'+erHeadLg('The Components','')+reg+'</div>';
