        +'<span title="'+(noted?'A note is written':'No note')+'" style="width:7px;height:7px;border-radius:50%;background:'+(noted?'var(--gold-text)':'rgba(var(--fg-rgb),.15)')+';flex-shrink:0"></span>'
        +'<span style="display:inline-flex;gap:2px;margin-left:4px">'+ico('\u2191','rcMove(\''+d.id+'\',\''+jsq((d.units[i]||{}).key)+'\',-1)','Move up',i===0)+ico('\u2193','rcMove(\''+d.id+'\',\''+jsq((d.units[i]||{}).key)+'\',1)','Move down',i===d.units.length-1)+ico('\u00d7','rcRemoveAt(\''+d.id+'\',\''+jsq((d.units[i]||{}).key)+'\')','Remove this section')+'</span></div>';
