var ARCH_PRINT_CSS='.amlayer{break-inside:avoid;page-break-inside:avoid}.amp1brk{break-after:page;page-break-after:always}'; /* the module's own print rules (AS6): the Architecture Map's whole-layer wrappers and its page-one break; carried into the shared window as its extra stylesheet */
function printPage(title,contentFn){printDocument(title,contentFn(),ARCH_PRINT_CSS)} /* 18 Sep 2026 (the family standard, §22.3.3): the module's print window is the shared one; printPage keeps its signature for its callers */
function printDocument(title,content,extraCss,opts){ /* 14 Sep 2026: opts.preview shows the document as a sheet with its forced page breaks marked and a Show as pages button, and does not open the print dialog */ /* 13 Sep 2026: the shared print window – the family styles, an optional stylesheet for bespoke report documents, the content, the footer */
var w=window.open('');if(!w){alert('The print view was blocked by the browser. Allow pop-ups for this site and try again.');return}
w.document.write('<html><head><title>'+title+'</title>'+
'<link rel="stylesheet" href="'+(function(){try{return new URL('fonts/fonts.css', location.href).href}catch(e){return 'fonts/fonts.css'}})()+'">'+ /* 2 Oct 2026 (Spec §25.1): the print window loads the site's own fonts; an absolute address, since the window is new and empty */''+
'<style>'+printThemeTokens()+'*{box-sizing:border-box;margin:0;padding:0}body{font-family:"Helvetica Neue",Arial,sans-serif;max-width:750px;margin:40px auto;padding:0 40px;line-height:1.7;font-size:14px;color:#1e2530;background:#fff}'+
'h1,h2,h3,h4{color:#1a1612;break-after:avoid;page-break-after:avoid}a{color:#2D5A8E}'+
'.btn,.btn-ghost,.bp,.bs,.bg,.bg2,.bd{display:none !important}button{display:none !important}@media screen{.preview-note button{display:inline-block !important}}'+
'.cd{background:none;border:none;border-radius:0;padding:8px 0;margin-bottom:14px;page-break-inside:avoid}'+
'select{-webkit-appearance:none;appearance:none;border:none;background:none;font-weight:600;font-size:13px;color:#1a1612}textarea{border:none;background:none;font-size:13px;color:#1e2530;resize:none}'+
'table{border-collapse:collapse;width:100%}th,td{padding:7px 8px;vertical-align:top;border-bottom:1px solid #e0e0e0;text-align:left}'+
'*{-webkit-print-color-adjust:exact;print-color-adjust:exact}[style*="#F5F2EC"],[style*="#8A8278"],[style*="rgba(245,242,236"],[style*="rgba(138,130,120"],[style*="color:var(--paper)"]{color:#1e2530 !important}[style*="color:var(--stone)"],[style*="color:var(--text-muted)"],[style*="color:var(--text-faint)"]{color:#555 !important}@media print{body{margin:0 auto;padding:0}}'+
'@page{margin:16mm 14mm 20mm 14mm;@top-left{content:""}@top-center{content:""}@top-right{content:""}@bottom-center{content:""}@bottom-left{content:"'+printFooterText()+'";font:9px "DM Mono",monospace;color:#666}@bottom-right{content:counter(page) " / " counter(pages);font:9px "DM Mono",monospace;color:#666}}'+ /* PRINT MARGINS (Paul's ruling, 12 Sep 2026; family): the document owns all six page corners — the top three empty, the copyright line bottom left, the page number bottom right — so the browser's own date, title, address, and count never print, whatever the user's Headers and footers setting */
'.print-footer{display:none}@media screen{.print-footer{display:block;margin-top:40px;padding-top:10px;border-top:1px solid #ddd;font-family:"DM Mono",monospace;font-size:9px;letter-spacing:.06em;color:#666}}'+ /* on screen, before printing, the copyright line ends the document */
(content.indexOf('report-corrected')>=0?report34WindowCss():'')+(extraCss||'')+'</style></head><body>'+((opts&&opts.preview)?'<div class="preview-note" style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;font:12px/1.5 var(--sans,sans-serif);color:#333;background:#FBF6EC;border:1px solid #E8D9B8;padding:8px 12px;margin:0 0 24px"><button onclick="window.print()" style="font:12px var(--sans,sans-serif);font-weight:600;padding:6px 14px;border:1px solid #333;border-radius:6px;background:#fff;color:#111;cursor:pointer;white-space:nowrap">Show as pages</button><span style="flex:1;min-width:240px">Preview. Dashed rules below mark where the document forces a page break; where the printer breaks a long section in the middle is set when it prints. Show as pages opens your browser\u2019s print preview, where the pages are exact, and Cancel returns here.</span></div>'+'<style>@media print{.preview-note{display:none}}@media screen{html{background:#e6e6e6}body{background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.12),0 8px 32px rgba(0,0,0,.08);padding:56px 64px !important;margin:24px auto !important}[style*="break-before:page"]::before,[style*="page-break-after:always"]:not([style*="display:flex"])::after,[style*="min-height:85vh"]+*::before{content:"page break";display:block;text-align:center;font:10px "DM Mono",monospace;letter-spacing:.14em;text-transform:uppercase;color:#999;border-top:1px dashed #bbb;padding-top:6px;margin:28px 0 24px}[style*="page-break-after:always"]+[style*="break-before:page"]::before{display:none}}</style>':'')+content+'<div class="print-footer">'+printFooterText()+'</div></body></html>');
w.document.close();if(!(opts&&opts.preview))setTimeout(function(){w.print()},500)}
function printDocumentPreview(title,content,opts){printDocument(title,content,'',opts)} /* the Report Manager's print and preview go through the shared window */


/* ═══════════════════════════════════════════════════════════════
   CLAUDE API ENDPOINT
   ─────────────────────────────────────────────────────────────
   Default: direct to Anthropic. Works inside Anthropic's hosted
   environment (Claude Artifacts), which injects the API key and
   handles CORS automatically.

   For self-hosted deployment (your own server, faisalhoque.com,
   any static host), point this at your proxy that holds the API
   key server-side. See /proxy/server.js for a minimal Express
   example, or /proxy/cloudflare-worker.js for serverless.

   Example for a proxied deployment:
     var CLAUDE_API_URL = '/api/claude';
     // or
     var CLAUDE_API_URL = 'https://your-proxy.example.com/claude';
   ═══════════════════════════════════════════════════════════════ */
var CLAUDE_API_URL = 'https://api.anthropic.com/v1/messages';

/* ═══════════════════════════════════════════════════════════════
   AUTH — identity & credential adapter (July 8)
   ═══════════════════════════════════════════════════════════════
   The one place to repoint sign-in, passcodes, and session state to a
   server. AUTH_ENDPOINT is a source constant (gov-cloud rule: no runtime
   remote configuration). '' = device-local credentials – the shipped
   behavior: member PINs live on roster records, the admin passcode in
   Store ('architecture-admin'), sessions in page state.

   Verification calls are CALLBACK-shaped. In local mode the callback
   fires synchronously in the same tick (the harness depends on this);
   a server implementation fires it from its fetch handler. Call sites
   are written for either timing, so swapping the internals needs no
   second surgery. Server contract: see the production dev doc. */
var AUTH_ENDPOINT=''; // '' = device-local (shipped). Dev team: set to the auth service base URL.
/* -- PASSWORD RULES (1 Oct 2026; Spec §25.5, Rollout item 85): the same code in every module. Architecture keeps its current local sign-in until it is deployed (ruled by Paul, 2 Oct 2026), with these rules applied within it. -- */
var PASSWORD_MIN_LENGTH = 8;
var PASSWORD_MAX_LENGTH = 128;
var COMMON_PASSWORDS = ['password1!','password123!','p@ssw0rd','p@ssword1','pa$$w0rd','pa$$word1','passw0rd!','welcome1!','welcome123!','admin123!','admin@123','qwerty123!','qwerty1!','abc123!@#','changeme1!','letmein1!','iloveyou1!','monkey123!','dragon123!','football1!','baseball1!','sunshine1!','princess1!','test123!','user123!','hello123!','secret123!','company1!','1q2w3e4r!','1qaz2wsx!','zaq1@wsx','!qaz2wsx','summer2025!','winter2025!','summer2026!','winter2026!','spring2026!','autumn2026!','fall2026!','nextchapter1!','nextchapter2026!'];
function passwordLength(pw){ return Array.from(String(pw == null ? '' : pw)).length; }
function passwordProblem(pw){
  pw = String(pw == null ? '' : pw);
  var n = passwordLength(pw);
  if (n < PASSWORD_MIN_LENGTH) return 'Use at least ' + PASSWORD_MIN_LENGTH + ' characters.';
  if (n > PASSWORD_MAX_LENGTH) return 'Use no more than ' + PASSWORD_MAX_LENGTH + ' characters.';
  if (!/[0-9]/.test(pw)) return 'Include at least one number.';
  if (!/[^\p{L}\p{N}\s]/u.test(pw)) return 'Include at least one special character, such as ! or #.';
  if (COMMON_PASSWORDS.indexOf(pw.toLowerCase()) >= 0) return 'That password is too common. Choose another.';
  return '';
}
function loginHasPassword(username){ username=(username||'').trim().toLowerCase(); var orgs=getOrgs(); for(var i=0;i<orgs.length;i++){ var d=Store.readOrg(orgs[i].id); var r=(d&&d.roster)||[]; for(var j=0;j<r.length;j++){ var u=r[j]; if(((u.username||'')+'').trim().toLowerCase()===username){ if(((u.passcode||'')+'').trim()!=='') return true; } /* the username only (Sweep 4R item 2) */ } } return false; }
var Auth=(function(){
  var DEFAULT_PASSCODE=''; /* 2 Oct 2026: no default code; a member without a password has no sign-in */

  /* -- sign-in: username + PIN, matched across every org roster (local mode) -- */
  function signIn(username, pin, cb){
    if(!AUTH_ENDPOINT){
      var m=findUserByLogin(username, pin);
      if(m) return cb({ok:true, orgId:m.orgId, userId:m.userId});
      return cb({ok:false, reason:(userExists(username)?(loginHasPassword(username)?'bad-pin':'no-credential'):'no-user')});
    }
    try{
      fetch(AUTH_ENDPOINT+'/session',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({username:username, passcode:pin})})
        .then(function(r){return r.json();}).then(function(res){cb(res||{ok:false,reason:'network'});})
        .catch(function(){cb({ok:false,reason:'network'});});
    }catch(e){cb({ok:false,reason:'network'});}
  }

  /* -- admin sign-in: first use sets the passcode (minimum 4 characters) -- */
  function signInAdmin(username, pin, cb){ if(typeof pin==='function'){ cb=pin; pin=username; username='admin'; } /* an older call with a password only reads as the default username */
    if(!AUTH_ENDPOINT){ var c=adminCreds()||{username:'admin',passcode:'NextChapter2026!',mustChange:true}; /* 5 Oct 2026 (Paul): the default account; its password works only once */
      if(String(username||'').trim().toLowerCase()!==String(c.username||'admin').trim().toLowerCase()||pin!==c.passcode) return cb({ok:false, reason:'bad-pin'});
      return cb({ok:true, mustChange:(!!c.mustChange||!!passwordProblem(c.passcode)), firstUse:!!c.mustChange}); }
    try{ fetch(AUTH_ENDPOINT+'/admin-session',{method:'POST',headers:{'Content-Type':'application/json'}, body:JSON.stringify({username:username,password:pin})})
      .then(function(r){return r.json();}).then(function(res){cb(res||{ok:false,reason:'network'});})
      .catch(function(){cb({ok:false,reason:'network'});}); }catch(e){cb({ok:false,reason:'network'});} }

  function hasAdminCreds(){ return !!adminCreds(); }
  function setAdminPasscode(np){ setAdminCreds(Object.assign({},adminCreds()||{username:'admin'},{passcode:np,mustChange:false})); }

  /* -- passcode minting: every place a PIN is defaulted routes here -- */
  function defaultPasscode(){ return DEFAULT_PASSCODE; }
  function ensurePasscode(u){ return u; } /* 2 Oct 2026: nothing is defaulted */

  /* -- session state (client-held; a server build keeps its token here too) -- */
  function setSession(userId){ currentUserId=userId; }
  function setAdminSession(on){ isAppAdmin=!!on; }
  function clearSession(){ currentUserId=null; isAppAdmin=false; try{Store.setRemember(null);}catch(e){} }

  return { signIn:signIn, signInAdmin:signInAdmin,
           hasAdminCreds:hasAdminCreds, setAdminPasscode:setAdminPasscode,
           defaultPasscode:defaultPasscode, ensurePasscode:ensurePasscode,
           setSession:setSession, setAdminSession:setAdminSession, clearSession:clearSession };
})();

/* ================= Collab: live-collaboration seam ==================
   Record locks (and, later, presence + a shared timer) for multi-user use.
   The local implementation simulates a server using per-org localStorage,
   so the feature works and is testable now (two tabs, two users, one org).
   The dev team repoints read()/write() to the server's realtime channel;
   it is deliberately separate from Store, whose adapter points at the
   durable database - realtime state and durable state want different backends. */
var TAB_ID='t'+Math.random().toString(36).slice(2,10)+Date.now().toString(36); /* 1 Oct 2026 (QA Sweep 3, TR-C1): one id per open tab */ function traceOwner(){return '__tracing:'+TAB_ID} function traceBeat(){try{if(!currentOrgId)return;var k='architecture-traces::'+currentOrgId;var o=JSON.parse(localStorage.getItem(k)||'{}');var _del=[];try{_del=JSON.parse(localStorage.getItem('architecture-deleted-orgs')||'[]')}catch(e){} if(_del.indexOf(currentOrgId)>=0){localStorage.removeItem(k);return} /* 6 Oct 2026 (final mini-batch item 3): nothing is written into a deleted organization */ if(UI.trace)o[TAB_ID]=Date.now();else delete o[TAB_ID];if(Object.keys(o).length)localStorage.setItem(k,JSON.stringify(o));else localStorage.removeItem(k)}catch(e){}} /* item 3: an empty heartbeat record is removed, not written back */ function provClearStaleTraceClaims(){try{var hb={};try{hb=JSON.parse(localStorage.getItem('architecture-traces::'+currentOrgId)||'{}')}catch(e){}var now=Date.now(),ttl=(typeof Collab!=='undefined'&&Collab.LOCK_TTL)||15000,mine=traceOwner();var lp=data.linkProvenance||{},stale=[];Object.keys(lp).forEach(function(k){(lp[k]||[]).forEach(function(o){if(typeof o!=='string'||o.indexOf('__tracing')!==0||o===mine)return;var tid=o.indexOf('__tracing:')===0?o.slice(10):'';if(!(tid&&hb[tid]&&now-hb[tid]<ttl))stale.push([o,k])})});if(!stale.length)return;var _lpb=lpSnap();stale.forEach(function(p){provReleaseKey(p[0],p[1])});lpCommit(_lpb)}catch(e){}} /* a pending trace claim whose tab has stopped beating is released, as an expired lock is */ var Collab=(function(){
  var LOCK_TTL=15000;                       // a lock whose holder stops beating auto-releases
  function lKey(){ return 'architecture-locks::'+currentOrgId; }
  function read(){ try{ return JSON.parse(localStorage.getItem(lKey())||'{}'); }catch(e){ return {}; } }   // Collab adapter -> server
  function write(o){ try{ localStorage.setItem(lKey(), JSON.stringify(o)); }catch(e){} }                    // Collab adapter -> server
  function me(){ return currentUserId; } function sid(){ return (typeof TAB_ID!=='undefined'&&TAB_ID)||'tab'; } /* the session that holds a lock */
  function fresh(t){ return t && (Date.now()-t)<LOCK_TTL; }
  function holder(rk){ if(!rk) return null; var h=read()[rk]; return (h&&fresh(h.at))?h:null; }
  function lockedByOther(rk){ var h=holder(rk); return (h&&h.sid!==sid())?h:null; }
  function acquire(rk){
    if(!currentOrgId||!me()||!rk) return true;
    var h=holder(rk); if(h&&h.sid!==sid()) return false;
    var u=getCurrentUser()||{}, L=read(); L[rk]={id:me(),sid:sid(),name:u.name||'Someone',at:Date.now()}; /* 5 Oct 2026 (Sweep 4R item 6): a lock belongs to a session (its tab), not a person */ write(L); return true;
  }
  function release(rk){ var L=read(); if(rk&&L[rk]&&L[rk].sid===sid()){ delete L[rk]; write(L); } }
  function refreshMine(){ if(!currentOrgId||!me()) return; var L=read(),ch=false; for(var k in L){ if(L.hasOwnProperty(k)&&L[k].sid===sid()){ L[k].at=Date.now(); ch=true; } } if(ch) write(L); }
  function leave(){ if(!currentOrgId||!me()) return; var L=read(),ch=false; for(var k in L){ if(L.hasOwnProperty(k)&&L[k].sid===sid()){ delete L[k]; ch=true; } } if(ch) write(L); }
  function othersLocks(){ var L=read(),out=[]; for(var k in L){ if(L.hasOwnProperty(k)&&fresh(L[k].at)&&L[k].sid!==sid()) out.push({key:k,name:L[k].name}); } return out; }
  return { acquire:acquire, release:release, holder:holder, lockedByOther:lockedByOther,
           refreshMine:refreshMine, leave:leave, othersLocks:othersLocks, LOCK_TTL:LOCK_TTL };
})();

/* Map an input id to the record scope it edits — derived 16 Jul 2026 from the
   module's 78 saveData() writers. Field-id convention here is prefix_field_ID
   (row id LAST — the reverse of Pipeline's prefix_ID_field). A returned key
   names a mutual-exclusion scope: a collection, 'collection::id' where the row
   id is recoverable from the suffix, UI.expandEdit for the inline edit forms,
   a step-scoped choice for the overloaded cp_ prefix (assessments on step 1.3,
   computePlan on 2.4), and cluster scopes for editors spanning collections
   (archmap, techstack). Chrome, roster (ru_), and entry fields return null. */
function idToRecordKey(id){ if(!id) return null; if(id==='set_aiGuide'||id==='set_voice') return 'settings'; /* 2 Oct 2026: the AI switches lock the organization's settings */   if(id==='jurHomeSel') return 'enterprise'; /* QA Sweep 3: the home jurisdiction belongs to the organization record */   if(/^cc_.+_name$/.test(id)){var _pn=idToRecordKey(id.slice(0,-5));if(_pn)return _pn} /* QA Sweep 3: a provider-name box locks its component */   if(/^(dg_(name|owner|quality|standards)|dpf_)/.test(id)||/^[a-z]+_new/i.test(id)||/^vn_/.test(id)||/^mcr_(?!e_)/.test(id)) return null; /* 5 Oct 2026 (Sweep 4R item 15): the vendor and criterion add-form drafts take no lock either */ /* QA Sweep 3: an add-form draft takes no lock */   if(/^ccrun_/.test(id)){var _cc=id.slice(6).split('_')[0];return (typeof compById==='function'&&compById(_cc))?compLockKey(_cc):null} /* QA Sweep 3: the compute rider locks its component */   if(/^sdt_/.test(id)){var _sd=id.slice(4).split('_')[0];return _sd?'aiDependencies::'+_sd:null} /* QA Sweep 3: a dependency's component tick locks the dependency it changes */   if(/^sov_nar_/.test(id)) return 'sovProgram'; /* QA Sweep 3: the no-action reason belongs to the program */
  var i=id.indexOf('_'); if(i<0) return null;
  var pre=id.slice(0,i), rest=id.slice(i+1);
  function rowKey(coll){ var j=rest.lastIndexOf('_'); var rid=(j>=0)?rest.slice(j+1):''; return rid!==''?(coll+'::'+rid):coll; }
  // inline edit forms (X_e_*) edit the row held in UI.expandEdit
  if(pre==='cmt'){var _cj=rest.indexOf('_');return (_cj>0&&/^(v|n)$/.test(rest.slice(0,_cj))&&rest.slice(_cj+1))?'commitmentChecks::'+rest.slice(_cj+1):null} /* 1 Oct 2026 (QA Sweep 3): a commitment's verdict and note lock their commitment */if(pre==='rc'&&/^(head|txt)_/.test(rest)){var _ru=rest.slice(rest.indexOf('_')+1),_rr=null;(data.reportDefs||[]).forEach(function(r){if(!_rr&&(r.units||[]).some(function(u){return u&&u.id===_ru}))_rr=r.id});return _rr?'reportDefs::'+_rr:null} /* QA Sweep 3: a text page's heading and body lock their report */if(pre==='rc'){var _rj=rest.indexOf('_');return _rj>=0?'reportDefs::'+rest.slice(_rj+1):null} /* 28 Sep 2026 (the consolidated re-audit, C01: the field layer) : a report’s title, subtitle and introduction take the report’s own lock, the name its save and rcLocked use */ if(pre==='cc'){var _sc=rest.match(/^([A-Za-z]+)_[A-Za-z0-9]+_([A-Za-z0-9]+)_std\d+$/);if(_sc&&LAYER_SCHEMAS[_sc[1]])return LAYER_SCHEMAS[_sc[1]].registerPath+'::'+_sc[2]} /* 28 Sep 2026: a standards checkbox belongs to its component */ if(pre==='mcr')return 'modelGovernance'; /* 23 Sep 2026 (the Phase 2 re-audit): every criteria field, its autosave and its Save and Remove belong to Model Governance's lock */
  if(rest.slice(0,2)==='e_'){
    var eColl={de:'dataEstate',ig:'integrations',ag:'agentRegistry',sh:'shadowRemediation',api:'apiCatalog',ret:'integrationRetirement',dgd:'dataGovernance',zt:'identityPlan',am:'modelGovernance',cr:'assessments'}[pre];
    if(eColl) return (UI.expandEdit!=null)?(eColl+'::'+(pre==='dgd'?String(UI.expandEdit).replace(/^dgd_/,''):UI.expandEdit)):eColl; /* 5 Oct 2026 (Sweep 4R item 11): a domain's fields take the domain's own key, dataGovernance::{id}, as its remove and save guards check */
  }
  var flat={ac:'assessments',cr:'assessments',id:'identities',dg:'dataGovernance',
    md:'aiModels',vn:'vendors',ds:'dataEstate',ig:'integrations',api:'apiCatalog',
    ret:'integrationRetirement',ag:'agentRegistry',sh:'shadowRemediation',
    rb:'reviewBoard',rr:'reviewResults',dpf:'deployments',ent:'enterprise',
    igh:'integrations',apio:'apiCatalog',reto:'integrationRetirement',
    cbo:'circuitBreakers',ago:'agentRegistry',sho:'shadowRemediation',
    dbRb:'reviewBoard',dbnqa:'reviewResults',cpd:'computePlan',
    nqa:'reviewResults',nqao:'reviewResults',obo:'observability',ero:'reviewResults',
    dgo:'dataGovernance',dgdo:'dataGovernance',mgo:'modelGovernance',zto:'identityPlan',amo:'modelGovernance', /* 28 Sep 2026 (Paul: lock coverage, Rollout items 10 and 53) */ cb:'circuitBreakers',apf:'apiPolicy',mg:'modelGovernance',ob:'observability',ipf:'identityPlan',cd:'assessments',agg:'agGovernance',rbsa:'reviewBoard',tp:'testPolicy',dgr:'dataGovernance'};
  if(pre==='cc'){var _oc=rest.match(/^([A-Za-z]+)_[A-Za-z0-9]+_([A-Za-z0-9]+?)_o\d+$/);if(_oc&&LAYER_SCHEMAS[_oc[1]])return LAYER_SCHEMAS[_oc[1]].registerPath+'::'+_oc[2]}
  if(pre==='cc'){var _lc=rest.match(/^([A-Za-z]+)_[A-Za-z0-9]+_([A-Za-z0-9]+?)_\d+$/);if(_lc&&LAYER_SCHEMAS[_lc[1]])return LAYER_SCHEMAS[_lc[1]].registerPath+'::'+_lc[2]} /* 23 Sep 2026 (the Phase 1 re-audit, round 3): a relationship tick belongs to its component */
  if(pre==='vr'){var _vr=rest.split('_');return 'vendors::'+_vr[_vr.length-1]} /* a vendor's fields belong to the vendor */
  if(pre==='rbm')return 'rbOrg'; /* a Board member's name and title belong to the Board */
  if(pre==='dgm')return 'dataGovernance';
  if(pre==='jpc')return 'judgmentCatalog::'+rest.split('_')[0]; /* 28 Sep 2026: by the entry's id, as its save names it */ /* 23 Sep 2026 (the Phase 4 re-audit, round 3): a custom practice's definition belongs to the catalogue */
  if(pre==='cps')return 'computePlan'; /* 23 Sep 2026 (the Phase 2 re-audit, round 3): a compute strategy step belongs to the plan */
  if(pre==='zti')return 'identityPlan'; /* a zero-trust initiative belongs to the identity plan */
  if(pre==='eaf'){var _ea=rest.split('_')[0];if(_ea&&compById&&compById(_ea))return 'agentRegistry::'+_ea} /* a process step belongs to its agent's record */ /* a forum member's belong to Data Governance */ /* 23 Sep 2026 (P1R-07): a checkbox option belongs to its component */
  if(pre==='cc'){var ccl=/^([A-Za-z]+)_[A-Za-z]+_(c\d+)$/.exec(rest);if(ccl&&typeof LAYER_SCHEMAS!=='undefined'&&LAYER_SCHEMAS[ccl[1]]){var ccp=LAYER_SCHEMAS[ccl[1]].registerPath;return ccp+'::'+ccl[2]; /* 28 Sep 2026: the component's own register (the compute mapping to assessments was stale) */}return null;}
  var _dpAt=function(ref){var d=(data.deployments||[]).find(function(x){return x.id===ref});return d?d.id:null}; /* 23 Sep 2026 (stable identity): field ids carry the deployment's id */ /* 23 Sep 2026 (the Phase 3 review): a deployment's fields lock by its stable id, not its position */
  if(pre==='dpfx'||pre==='dpra'){var _p1=rest.split('_');var _d1=_dpAt(_p1[1]);return _d1?'deployments::'+_d1:'deployments'}
  if(pre==='dpat'){var _pa=rest.split('_');var _da=_dpAt(_pa[1]);return _da?'deployments::'+_da:'deployments'} /* 23 Sep 2026 (the Phase 3 re-audit): a deployment check's answer and evidence belong to their deployment */
  if(pre==='aqd'){var _pq=rest.split('_');var _dq=_dpAt(_pq[_pq.length-1]);return _dq?'alignmentReviews::'+_dq:'alignmentReviews'} /* the alignment decision belongs to its review */
  if(pre==='sov'&&rest.slice(0,5)==='prog_'){return 'sovProgram'} /* 28 Sep 2026: the program is one grouped record (ruled D-A13), so it locks as one */ /* the revised answer belongs to its question */
  if(pre==='aq'){var _p2=rest.split('_');var _d2=_dpAt(_p2[1]);return _d2?'alignmentReviews::'+_d2:'alignmentReviews'}
  if(pre==='dp'){var _p3=rest.split('_');var _d3=_dpAt(_p3[_p3.length-1]);return _d3?'deployments::'+_d3:'deployments'}
  if(pre==='secx') return rowKey('securityTestsX');
  if(pre==='casx') return rowKey('cascadeTestsX');
  if(pre==='sov'&&rest.slice(0,4)==='act_'){return 'sovProgram'} if(pre==='sov'&&(rest.slice(0,4)==='dep_'||rest.slice(0,4)==='map_')){var _sq=rest.split('_'),_st=_sq[_sq.length-1];if(/^\d+$/.test(_st)){var _sdd=(data.aiDependencies||[])[+_st];return _sdd&&_sdd.id?'aiDependencies::'+_sdd.id:'aiDependencies'}return 'aiDependencies::'+_st} /* 28 Sep 2026 (Paul: lock coverage, Rollout items 10 and 53): a dependency's answers belong to the dependency */
  if(flat[pre]) return flat[pre];
  if(pre==='rs'||pre==='rm'){var _rn=parseInt(rest.split('_')[1],10);var _rsc=(typeof RISK_SCENARIOS!=='undefined'&&RISK_SCENARIOS[_rn])||null;return _rsc?'riskScenarios::'+_rsc.id:'riskScenarios'} /* 28 Sep 2026: by the scenario's id, as its save names it */
  if(pre==='sec') return 'securityTests'; /* 28 Sep 2026: the fixed tests carry no ids and save whole, so they lock whole */
  if(pre==='cas') return 'cascadeTests';
  
  
  if(pre==='skp'){return 'skillsInventory'} /* 28 Sep 2026: the skills list carries no ids and saves whole, so it locks whole */ /* 23 Sep 2026 (the Phase 4 re-audit): a plan belongs to its capability, so its fields and buttons share the capability\u2019s lock */
  if(pre==='sov'&&(rest.slice(0,4)==='ops_'||rest.slice(0,4)==='mon_'))return 'sovereigntyOps'; /* 23 Sep 2026 (the Phase 4 re-audit): the sovereignty owner and the dimension monitoring belong to the operating record */
  if(pre==='jp'){return 'judgmentPractices::'+rest.split('_')[0]} /* a practice's fields belong to the practice */
  if(pre==='skill'||pre==='dbsk') return 'skillsInventory';
  if(pre==='cp') return (typeof currentStep!=='undefined'&&currentStep==='1.3')?'assessments':'computePlan';
  if(pre==='ame'){var _mj=rest.lastIndexOf('_'),_mi=parseInt(rest.slice(_mj+1),10);var _mk=null,_m1=/^(dataEstate|integrations|aiModels)_(\d+)$/.exec(String(UI.archMapEdit||''));if(_m1&&+_m1[2]===_mi)_mk=_m1[1];if(!_mk){var _m2=/^stk_(dataEstate|integrations|aiModels)_(\d+)$/.exec(String(UI.expandEdit||''));if(_m2&&+_m2[2]===_mi)_mk=_m2[1]}var _mr=_mk&&(data[_mk]||[])[_mi];return (_mr&&_mr.id)?_mk+'::'+_mr.id:null} /* 28 Sep 2026: the Architecture Map panel edits a component, so it takes the component's lock (it took a lock named archmap, which no guard checked) */
  if(pre==='stk'){var _k1=/^(dataEstate|integrations|aiModels|computeResources|aiApplications|agentRegistry)_(\d+)/.exec(rest);var _kr=_k1&&(data[_k1[1]]||[])[+_k1[2]];return (_kr&&_kr.id)?_k1[1]+'::'+_kr.id:null} /* 28 Sep 2026: a stack tile edits a component, so it takes the component's lock (it took a lock named techstack, which no guard checked) */
  return null;
}

/* Guard for button-driven writes: block and tell the user who holds the record. */
function lockBlocked(rk){var h=Collab.lockedByOther(rk);if(!h)return false;try{alert('Locked \u2014 '+((h&&h.name)||'another user')+' is editing this record. Try again when the lock clears.')}catch(e){}return true}

/* Post-render pass: disable fields of records another user holds, mark who holds them.
   force=true always paints (fresh DOM after render); the tick uses force=false and skips
   when nothing changed, so it never flickers or fights typing. */
var _lockSig=''; var _readOnlyRender=0; /* 28 Sep 2026 (the consolidated re-audit, C02) : raised while a document is being generated; no store write runs while it is raised */ function dpWritable(dp){try{return !_readOnlyRender&&!(dp&&Collab.lockedByOther('deployments::'+dp.id))}catch(e){return false}} /* a deployment a reader may change: not during a document read, and not held by another person (checked silently, before any change) */
function handlerLockKey(el){try{var h=(el.getAttribute('onchange')||'')+' '+(el.getAttribute('oninput')||'')+' '+(el.getAttribute('onclick')||'');var m=/eafSet\('([^']+)'/.exec(h);if(m)return compLockKey(m[1]);if(/dgEditForumMember\(/.test(h))return 'dataGovernance';if(/rbEditMember\(/.test(h))return 'rbOrg' /* 5 Oct 2026 (Sweep 4R item 27): the key rbEditMember guards */;}catch(e){}return null} /* 1 Oct 2026 (QA Sweep 3): a control with no id locks with its record, read from its own save handler */ function applyLockUI(force){
  try{
    var others=Collab.othersLocks(), sig=JSON.stringify(others);
    if(!force && sig===_lockSig) return; _lockSig=sig;
    var lockMap={}; for(var m=0;m<others.length;m++) lockMap[others[m].key]=others[m];
    var _roots=[document.getElementById('app'),document.getElementById('modalRoot')].filter(Boolean); if(!_roots.length) return; /* 28 Sep 2026 (D-A10): the page and the open dialog both carry lockable fields */ _roots.forEach(function(root){
    var oldMarks=root.querySelectorAll('.collab-lock-mark'); for(var i=0;i<oldMarks.length;i++){ if(oldMarks[i].parentNode) oldMarks[i].parentNode.removeChild(oldMarks[i]); }
    var wasLocked=root.querySelectorAll('[data-collab-locked]'); for(var j=0;j<wasLocked.length;j++){ wasLocked[j].disabled=false; wasLocked[j].removeAttribute('data-collab-locked'); }
    var seen={}, fields=root.querySelectorAll('input,select,textarea');
    for(var k=0;k<fields.length;k++){
      var el=fields[k], rk=(el.getAttribute&&el.getAttribute('data-lock'))||idToRecordKey(el.id)||handlerLockKey(el); if(!rk) continue; var h=lockMap[rk]; if(!h) continue;
      el.disabled=true; el.setAttribute('data-collab-locked','1');
      if(!seen[rk]){ seen[rk]=true;
        var mk=document.createElement('div'); mk.className='collab-lock-mark';
        mk.style.cssText='font-size:11px;font-weight:600;color:#B8862E;margin:0 0 6px';
        mk.textContent='Locked \u00b7 '+(h.name||'Someone')+' is editing';
        if(el.parentNode) el.parentNode.insertBefore(mk, el); } } }); }catch(e){} }

/* Acquire on focus, release when focus leaves all record fields (focusin handles field-to-field). */
var _heldLock=null;
var _adoptPaint=false; /* set by Store.refreshOrg around its adoption render — see the re-inject rule in render() (item 69, entity-keyed form; Family Standard §F-13a) */
if(typeof document!=='undefined'){
  document.addEventListener('focusin', function(e){
    var t=e.target; if(!t||!/^(INPUT|SELECT|TEXTAREA)$/.test(t.tagName||'')) return;
    if(t.readOnly||t.disabled) return;
    var rk=(t.getAttribute&&t.getAttribute('data-lock'))||idToRecordKey(t.id)||handlerLockKey(t); /* Sweep 4R item 27: controls without an id lock through their handler, as applyLockUI marks them */ /* Sweep 4R item 13: a control's own data-lock first, as applyLockUI reads it */ if(!rk) return;
    if(Collab.lockedByOther(rk)){ if(t.blur)t.blur(); return; }
    if(_heldLock&&_heldLock!==rk){ Collab.release(_heldLock); _heldLock=null; }
    if(Collab.acquire(rk)) _heldLock=rk;
  });
  document.addEventListener('focusout', function(e){
    setTimeout(function(){
      var a=document.activeElement;
      var stillField=a&&/^(INPUT|SELECT|TEXTAREA)$/.test(a.tagName||'')&&idToRecordKey(a.id);
      if(_heldLock&&!stillField){ Collab.release(_heldLock); _heldLock=null; }
    },60);
  });
  window.addEventListener('beforeunload', function(){ try{Collab.leave();}catch(e){} });
  setInterval(function(){ try{ Collab.refreshMine(); applyLockUI(false); if(UI.trace)traceBeat(); }catch(e){} }, 4000);
}
/* ================= end Collab ================= */

/* ═══ ENTRY FLOW — username + PIN login · setup · admin console ═══ */
function adminCreds(){return Store.getAdmin();}
function setAdminCreds(c){Store.setAdmin(c);}

// Search every org's roster for a user matching username (or full name) + PIN
function findUserByLogin(username,pin){
  username=(username||'').trim().toLowerCase();pin=(pin||'').trim();
  var orgs=getOrgs();
  for(var i=0;i<orgs.length;i++){
    var d=Store.readOrg(orgs[i].id);if(!d)continue;
    var roster=(d&&d.roster)||[];
    for(var j=0;j<roster.length;j++){
      var u=roster[j];
      var uname=((u.username||'')+'').trim().toLowerCase();
      var fname=((u.name||'')+'').trim().toLowerCase();
      var pass=((u.passcode||'')+'').trim();
      if(username===uname&&pass!==''&&pin===pass) /* 5 Oct 2026 (Paul, Sweep 4R item 2): the username only, never the full name */return{orgId:orgs[i].id,userId:u.id};
    }
  }
  return null;
}
// True if a username (or full name) exists in any organization, ignoring PIN
function userExists(username){
  username=(username||'').trim().toLowerCase();if(!username)return false;
  var orgs=getOrgs();
  for(var i=0;i<orgs.length;i++){
    var d=Store.readOrg(orgs[i].id);if(!d)continue;
    var roster=(d&&d.roster)||[];
    for(var j=0;j<roster.length;j++){
      var u=roster[j];
      if(((u.username||'')+'').trim().toLowerCase()===username)return true; /* the username only (Sweep 4R item 2) */
    }
  }
  return false;
}

/* ── Login ── */
function loginKey(e){if(e&&e.key==='Enter')doLogin()}
function doLogin(){
  var un=$('loginUser'),pn=$('loginPin');
  var username=un?un.value.trim():'';var pin=pn?pn.value.trim():'';
  UI.entry.user=username; // preserve the typed username across re-render (ER reference form, ported 15 Aug 2026)
  UI.entry.user=username;   // preserve the typed username across re-render
  if(!username){UI.entry.err='Enter your username.';render();var u0=$('loginUser');if(u0)u0.focus();return}
  Auth.signIn(username,pin,function(res){
    if(res&&res.ok){
      switchToOrg(res.orgId);Auth.setSession(res.userId);navHistory.length=0;currentPage='home';currentStep=null;currentPhase=null; /* 30 Sep 2026 (QA Sweep 1, F-37): a sign-in starts with empty history, on the page a cold load opens */
      var rc=$('loginRemember');var remember=rc?rc.checked:!!(UI.entry&&UI.entry.remember);
      try{Store.setRemember(remember?{orgId:res.orgId,userId:res.userId}:null)}catch(e){}
      var _meP=getCurrentUser(); if(_meP&&(_meP.mustChange||passwordProblem(_meP.passcode||''))){UI.entry={step:'newpw',err:'',why:_meP.mustChange?'temp':'weak'};render();return} /* 5 Oct 2026: a stored password that breaks the rule is replaced first */ /* 2 Oct 2026 (Spec §25.5): a temporary password is replaced first */ UI.entry=null;render();return; } if(res&&res.reason==='network'){UI.entry.err='Could not reach the sign-in service. Try again.';render();return}
    if(res&&res.reason==='no-credential'){ UI.entry.err='This person has no sign-in yet. Ask your administrator to set a password.'; render();return } UI.entry.err='That username and password do not match.'; render();var p1=$('loginPin');if(p1)p1.focus();
  });
}
function gotoSetup(){UI.entry={step:'setup',presetUser:'',presetPin:'',err:''};render()}
function gotoLogin(){UI.entry={step:'login',err:''};render()}
