/* ── Setup (org + first user) ── */
function doSetup(){ var _sc=$('setupCode'); if(((_sc&&_sc.value)||'').trim()!==SETUP_CODE){ UI.entry.err='That setup code is not recognized.'; render(); return } /* 2 Oct 2026 (Paul): a new organization needs the setup code */ var org=$('setupOrg'),nm=$('setupName'),un=$('setupUser'),pn=$('setupPin');
  var orgName=org?org.value.trim():'',name=nm?nm.value.trim():'',username=un?un.value.trim():'',pin=pn?pn.value.trim():'';
  if(!orgName||!name||!username||!pin){UI.entry.err='Please complete all fields to continue.';UI.entry.presetUser=username;render();return} var _spp=passwordProblem(pin); if(_spp){UI.entry.err=_spp;UI.entry.presetUser=username;render();return} if(usernameTaken(username,null)){UI.entry.err='That username is already taken. Choose another.';render();return} /* 2 Oct 2026 (Spec §25.5) */
  resetOrgScopedUI(); /* 23 Sep 2026: before the new organization is created and loaded */
  var res=createOrg(orgName,{name:name,username:username,passcode:pin,role:'Administrator'});
  Auth.setSession(res.userId);
  var rc=$('setupRemember');var remember=rc?rc.checked:false;
  try{Store.setRemember(remember?{orgId:res.orgId,userId:res.userId}:null)}catch(e){}
  // Land in the app and open the Team panel so they can add the rest of the team
  UI.entry=null;render();openOrgSetup();
}

