    h+='<div><label class="org-flabel">Email</label><input id="ru_new_email" class="field-input" type="email" value="" placeholder="name@company.com"/></div>';
    h+='<div><label class="org-flabel">Department</label><input id="ru_new_dept" class="field-input" value="" placeholder="e.g. Strategy"/></div>';
    h+='<div><label class="org-flabel" style="display:flex;align-items:center;gap:8px;cursor:pointer"><input type="checkbox" id="ru_new_admin"'+(false?' checked':'')+'> Administrator</label></div>'; /* Sweep 4R item 3 */ h+='<div><label class="org-flabel">Temporary password</label><input id="ru_new_passcode" class="field-input" type="password" value="" autocomplete="new-password"/><div style="font-size:12px;color:var(--stone);line-height:1.5;margin-top:4px">At least 8 characters, including a number and a special character such as ! or #. The person will be asked to choose their own password the next time they sign in.</div></div>';
