      h+='<div><label class="org-flabel">Username</label><input id="ru_'+u.id+'_username" class="field-input" value="'+escAttr(u.username||'')+'" placeholder="e.g. maria" autocomplete="off"/></div>';
      h+='<div><label class="org-flabel">Role / title</label><input id="ru_'+u.id+'_role" class="field-input" value="'+escAttr(u.role||'')+'" placeholder="e.g. Architecture Owner"/></div>';
      h+='<div><label class="org-flabel">Scope / focus</label><input id="ru_'+u.id+'_scope" class="field-input" value="'+escAttr(u.scope||'')+'" placeholder="e.g. Operations"/></div>';
      h+='<div><label class="org-flabel">Email</label><input id="ru_'+u.id+'_email" class="field-input" type="email" value="'+escAttr(u.email||'')+'" placeholder="name@company.com"/></div>';
      h+='<div><label class="org-flabel">Department</label><input id="ru_'+u.id+'_dept" class="field-input" value="'+escAttr(u.dept||'')+'" placeholder="e.g. Strategy"/></div>';
      if(isOrgAdminNow())h+='<div><label class="org-flabel" style="display:flex;align-items:center;gap:8px;cursor:pointer"><input type="checkbox" id="ru_'+u.id+'_admin"'+(u.admin===true?' checked':'')+'> Administrator</label></div>'; /* Sweep 4R item 3 */ h+='<div><label class="org-flabel">'+(isMe?'Password':'Temporary password')+'</label><input id="ru_'+u.id+'_passcode" class="field-input" type="password" value="" placeholder="Leave empty to keep the current password" autocomplete="new-password"/><div style="font-size:12px;color:var(--stone);line-height:1.5;margin-top:4px">At least 8 characters, including a number and a special character such as ! or #.</div></div>'; /* 2 Oct 2026: a password is never shown */
      h+='</div>';
      h+='<div class="org-edit-actions">';
      h+='<button class="org-btn-save" onclick="saveProfile(\''+u.id+'\')">Save</button>';
      h+='<button class="org-btn-cancel" onclick="cancelEditProfile()">Cancel</button>';
      if(isOrgAdminNow())h+='<button class="org-btn-del" onclick="removeProfile(\''+u.id+'\')"'+(isMe?' disabled title="Signed-in profile \u2014 switch users to delete"':'')+'>Delete</button>';
      h+='</div>';
