/* ── Admin: manage all organizations ───────────────── */
function openAdmin(){ if(!isAppAdmin){return;} currentModal='admin'; renderAdminModal(); }
/* \u2550\u2550\u2550 MY ASSIGNMENTS + USER MENU (family widget \u2014 drop-in; built 12 Aug 2026) \u2550\u2550\u2550
   Ported to Architecture 24 Aug 2026 per Paul's ruling. Two disclosed adaptations from the
   directive: (1) this module has no renderNav \u2014 menu toggles repaint via render(), the same
   idiom as toggleNavMore; (2) this module's mgSteps() returns {id,name,phase} \u2014 the adapter
   reads s.phase where the directive's donor read s.ph. Everything else is directive bytes. */
var ASGN_ADAPTER={
  openTasks:function(userId){
    var out=[];var assigns=data.assigns||{},co=data.completedSteps||{},due=data.stepDue||{};
    mgSteps().forEach(function(s){
      if((assigns[s.id]||[]).indexOf(userId)<0)return;   /* assigned to this user */
      if(co[s.id])return;                                /* stays listed only until the step is complete */
      out.push({id:s.id,label:s.name,sub:'Phase '+s.phase.id+' \u00b7 '+s.phase.name,due:due[s.id]||null});
    });
    return out;
  },
  navigate:function(taskId){go(taskId);},
  /* assigned tasks whose step is complete \u2014 greyed at the list's foot (ruled 12 Aug 2026) */
  doneTasks:function(userId){
    var out=[];var assigns=data.assigns||{},co=data.completedSteps||{};
    mgSteps().forEach(function(s){
      if((assigns[s.id]||[]).indexOf(userId)<0)return;
      if(!co[s.id])return;
      out.push({id:s.id,label:s.name,sub:'Phase '+s.phase.id+' \u00b7 '+s.phase.name,due:null});
    });
    return out;
  }
};
function toggleUserMenu(e){if(e&&e.stopPropagation)e.stopPropagation();UI.userMenu=!UI.userMenu;refreshNavMenus();}
function closeUserMenu(){if(UI.userMenu){UI.userMenu=false;refreshNavMenus();}}
/* Due-dated tasks first (soonest first), undated after in the adapter's program order; stable. */
function asgnOpenTasks(userId){
  var t=ASGN_ADAPTER.openTasks(userId);
  return t.map(function(x,i){x._i=i;return x;}).sort(function(a,b){
    if(a.due&&b.due)return a.due<b.due?-1:a.due>b.due?1:a._i-b._i;
    if(a.due)return -1; if(b.due)return 1; return a._i-b._i;
  });
}
function asgnGo(taskId){closeModal();ASGN_ADAPTER.navigate(taskId);}
function asgnRowHtml(t,isDone,today){
  var overdue=!isDone&&!!(t.due&&t.due<today);
  return '<div onclick="asgnGo(\''+esc(t.id)+'\')" role="link" tabindex="0" style="display:flex;align-items:center;gap:12px;padding:12px 14px;border:1px solid rgba(var(--fg-rgb),.08);background:rgba(var(--fg-rgb),.03);margin-bottom:8px;cursor:pointer'+(isDone?';opacity:.55':'')+'" title="'+(isDone?'Open this step':'Open this task')+'">'
    +'<div style="flex:1"><div style="font-size:14px;font-weight:600;color:var(--paper)">'+esc(t.label)+'</div>'
    +'<div style="font-family:var(--mono);font-size:10px;color:var(--stone);margin-top:2px">'+esc(t.sub||'')+'</div></div>'
    +(isDone?'<div style="font-family:var(--mono);font-size:11px;color:#1B6B5A;white-space:nowrap">\u2713 Done</div>'
      :(t.due?'<div style="font-family:var(--mono);font-size:11px;color:'+(overdue?'#9B2D3F':'var(--stone)')+';white-space:nowrap">'+(overdue?'Overdue \u00b7 ':'Due ')+esc(fmtDate(t.due))+'</div>':''))
    +'<span style="color:var(--gold);font-size:14px">\u2192</span></div>';
}
function asgnListHtml(userId){
  var open=asgnOpenTasks(userId);
  var done=ASGN_ADAPTER.doneTasks(userId);
  if(!open.length&&!done.length)return '<div style="font-family:var(--serif);font-size:15px;color:var(--stone);font-style:italic;text-align:center;padding:28px 0">No assignments yet. Tasks assigned to you in Track Program appear here.</div>';
  var today=todayIso();
  var h='';
  open.forEach(function(t){h+=asgnRowHtml(t,false,today);});
  if(!open.length)h+='<div style="font-family:var(--serif);font-size:15px;color:var(--stone);font-style:italic;text-align:center;padding:14px 0 6px">No open assignments.</div>';
  if(done.length){
    h+='<div style="font-family:var(--mono);font-size:10px;color:var(--stone);letter-spacing:.08em;text-transform:uppercase;margin:14px 0 8px">Completed</div>';
    done.forEach(function(t){h+=asgnRowHtml(t,true,today);});
  }
  return h;
}
function openAssignments(){currentModal='assignments';renderAssignmentsModal();}
function renderAssignmentsModal(){
  var mr=$('modalRoot');if(!mr)return;
  if(currentModal!=='assignments')return; /* never clears another modal's paint */
  var cu=getCurrentUser();
  if(!cu){mr.innerHTML='';currentModal=null;return;}
  var h='<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal">';
  h+='<div style="display:flex;align-items:center;gap:12px;margin-bottom:6px">'+userAv(cu,34)+'<div><h3 class="h-sub-lg" style="margin:0">My Assignments</h3><div style="font-family:var(--mono);font-size:10px;color:var(--stone)">'+esc(cu.name)+(cu.role?' \u00b7 '+esc(cu.role):'')+'</div></div></div>';
  h+='<div style="font-size:13px;color:var(--stone);line-height:1.6;margin-bottom:16px">Tasks assigned to you in Track Program \u2014 click one to go straight to the work. Completed assignments drop to the foot of the list.</div>';
  h+=asgnListHtml(cu.id);
  h+='<div style="display:flex;justify-content:flex-end;margin-top:18px"><button class="btn-gold" onclick="closeModal()">Done</button></div>';
  h+='</div></div>';
  mr.innerHTML=h;
}
/* Renders under the 90-day timeline on the module overview; appears only when the
   signed-in user has at least one open assignment. */
function asgnOverviewCard(){
  var cu=getCurrentUser();if(!cu)return '';
  if(!asgnOpenTasks(cu.id).length)return '';
  return '<div class="mb-6" style="border:1px solid rgba(var(--fg-rgb),.08);padding:20px 24px;background:rgba(var(--fg-rgb),.02)">'
    +'<h3 class="h-sub-md" style="margin:0 0 4px">My Assignments</h3>'
    +'<p class="t-faint-sm" style="margin:0 0 12px">Assigned to you \u2014 open tasks first, completed below.</p>'
    +asgnListHtml(cu.id)
    +'</div>';
}
