  var body='font-size:14px;color:var(--stone);line-height:1.75;margin:0 0 10px';
  var h='';
  h+='<div style="position:fixed;inset:0;background:rgba(26,22,18,.92);backdrop-filter:blur(8px);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:32px 24px;overflow-y:auto" onclick="if(event.target===this)closeHelp()">';
  h+='<div style="background:var(--ink);border:1px solid rgba(90,125,138,.35);padding:40px 48px;max-width:760px;width:100%;position:relative">';
  h+='<h3 style="font-family:var(--serif);font-size:28px;font-weight:300;color:var(--paper);margin-bottom:10px">90 Days to an AI-Ready Architecture</h3>';
  h+='<p style="'+body+';margin-bottom:28px">'+esc("A step-by-step tool for building the technical architecture that enterprise AI depends on, grounded in Faisal Hoque\u2019s published frameworks. This guide explains how the module is organized and how each of its surfaces works.")+'</p>';
  h+='<div style="'+sec+'"><div style="'+sl+'">'+esc("What This Is")+'<span style="flex:0 0 20px;height:1px;background:var(--gold)"></span></div>';
  h+='<p style="'+body+'">'+esc("Four sequential phases take you from a scored assessment of your current architecture to your first full architecture review, in 90 days. A fifth phase, Manage, keeps the architecture running after that. Each phase breaks into guided steps, and every phase produces output documents you can print. Your work saves as you go.")+'</p>';
  h+='</div>';
