var _voiceActive=false,_recognition=null;
/* Voice FAB UI + toast (Pipeline-style) */
var _voiceToastTimer=null;
function setVoiceUI(active){
  var fab=document.getElementById('voiceFab');var lbl=document.getElementById('voiceLabel');var ic=document.getElementById('voiceIcon');
  if(fab)fab.className='voice-fab'+(active?' active':'');
  if(lbl)lbl.textContent=active?'Listening\u2026':'Voice';
  if(ic)ic.textContent='\u25C9';
}
function voiceToast(msg){
  var tEl=document.getElementById('voiceToast');if(!tEl)return;
  tEl.textContent=msg;tEl.className='voice-toast show';
  if(_voiceToastTimer)clearTimeout(_voiceToastTimer);
  _voiceToastTimer=setTimeout(function(){tEl.className='voice-toast'},2600);
}
function toggleVoice(){ if(!(typeof _voiceActive!=='undefined'&&_voiceActive)&&!voiceOn())return; /* 2 Oct 2026 (Spec §25.2): Voice never starts while its switch is off */ if(typeof _voiceActive!=='undefined'&&_voiceActive){
    _voiceActive=false;
    if(_recognition)try{_recognition.stop();}catch(e){}
    setVoiceUI(false);
    return;
  }
  var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){alert('Voice not supported. Use Chrome or Edge.');return;}
  _recognition=new SR();
  _recognition.continuous=true;
  _recognition.interimResults=false;
  _recognition.lang='en-US';
  _recognition.onstart=function(){
    _voiceActive=true;
    setVoiceUI(true);
  };
  _recognition.onresult=function(e){
    var t=e.results[e.results.length-1][0].transcript.trim().toLowerCase();
    voiceToast('Heard: \u201C'+t+'\u201D');
    if(t.match(/\b(home)\b/)){go('home');}
    else if(t.match(/\b(learn|library|research)\b/)){go('learn');}
    else if(t.match(/\b(readiness|journey|phase)\b/)){go('readiness');}
    else if(t.match(/\b(insight|data)\b/)){go('insights');}
    else if(t.match(/\b(lead|dashboard)\b/)){go('phase5');}
    else if(t.match(/\b(coach|guide)\b/)&&typeof coachOpen!=='undefined'&&!coachOpen){toggleCoach();}
    else if(t.match(/\b(notes?)\b/)&&!notesOpen){toggleNotes();}
    else if(t.match(/\b(chat|team)\b/)&&!gchatOpen){toggleGChat();}
    else if(t.match(/\b(help)\b/)){openHelp();}
    else if(t.match(/\b(stop|quiet|cancel)\b/)){toggleVoice();}
  };
  _recognition.onerror=function(e){
    var msg=e.error==='not-allowed'?'Microphone access denied. Check browser permissions.':
            e.error==='no-speech'?'No speech detected. Try again.':
            'Voice error: '+e.error;
    _voiceActive=false;
    setVoiceUI(false);
    voiceToast(msg);
  };
  _recognition.onend=function(){
    if(_voiceActive){try{_recognition.start();}catch(e){_voiceActive=false;setVoiceUI(false);}}
  };
  try{_recognition.start();}catch(e){alert('Could not start voice: '+e.message);}
}


