  var h='<div style="font-size:12px;color:var(--stone);line-height:1.5;margin:0 0 12px">These columns record the places where this component works, beyond those it inherits from other components on the architecture map. Where it runs on a compute host that is on the map, the host\u2019s locations are inherited and shown grayed out.</div>'; /* 11 Sep 2026 (Paul's ruling) */
  h+='<div style="margin:0 0 16px"><div style="font-size:13px;font-weight:600;color:var(--paper);margin-bottom:4px">'+esc(F.prov.label)+'</div><div style="font-size:12px;color:var(--stone);line-height:1.5;margin:0 0 8px">'+esc(F.prov.gloss)+'</div>'+jurOwnerField(layerKey,comp,F.prov,fid(F.prov),true)+'</div>';
  h+='<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 24px;align-items:start">'; /* two grid rows (Paul's ruling, 10 Sep 2026): the titles and summaries share row one, so every checklist starts on the same line in row two whatever the length of the text above it */
  var cols=[[F.storesIn,jurMultiField(layerKey,comp,F.storesIn,fid(F.storesIn),true)],[F.processesIn,jurMultiField(layerKey,comp,F.processesIn,fid(F.processesIn),true)],[F.operatedFrom,jurMultiField(layerKey,comp,F.operatedFrom,fid(F.operatedFrom),true)+jurMarkField(layerKey,comp,F.jurReachIncomplete,fid(F.jurReachIncomplete),true)]];
  cols.forEach(function(cc,ci){h+='<div style="grid-row:1;grid-column:'+(ci+1)+'">'+title(cc[0])+'</div>'});
  cols.forEach(function(cc,ci){h+='<div style="grid-row:2;grid-column:'+(ci+1)+'">'+cc[1]+'</div>'});
