function jurMarkTick(layerKey,compId,fieldId,checked){if(lockBlocked(LAYER_SCHEMAS[layerKey].registerPath+'::'+compId))return; /* 28 Sep 2026 (Paul: lock coverage, Rollout items 10 and 53) */var reg=schemaRegister(LAYER_SCHEMAS[layerKey].registerPath);for(var i=0;i<reg.length;i++){if(reg[i].id===compId){reg[i][fieldId]=!!checked;break}}Store.commit(LAYER_SCHEMAS[layerKey].registerPath,compId);render()}
function jurOtherMore(fid,shown){UI.jurPend=UI.jurPend||{};UI.jurPend[fid]=(shown||0)+1;render()}
function jurHome(){return (data.enterprise&&data.enterprise.homeJurisdiction)||''}
