          if(e.kind==='writesTo'&&e.from===a.id&&e.to===b.id){push(a,b,'write','data written across the border');any=true}
          if(e.kind==='trainedOn'&&e.from===a.id&&e.to===b.id){push(b,a,'trained','training data crosses the border');any=true}
