function jurViewBoxFor(v){
  var G=jurGeoData();if(!G)return '0 0 1000 520';
  var def=JUR_VIEWS[v];
  if(!def)return G.vb;
  var pts=[];
  def.jset.forEach(function(j){var p=G.anchors[j]||G.pts[j];if(p)pts.push(p)});
  if(def.euAll)G.eu.forEach(function(n){var p=G.pts[n];if(p)pts.push(p)});
  if(!pts.length)return G.vb;
  var xs=pts.map(function(p){return p[0]}),ys=pts.map(function(p){return p[1]});
  var x0=Math.min.apply(null,xs),x1=Math.max.apply(null,xs),y0=Math.min.apply(null,ys),y1=Math.max.apply(null,ys);
  var padX=(x1-x0)*0.14+24,padY=(y1-y0)*0.14+16;
  x0-=padX;x1+=padX;y0-=padY;y1+=padY;
  var w=x1-x0,hh=y1-y0;
  if(w<def.minW){x0-=(def.minW-w)/2;w=def.minW}
  var asp=1000/520;
  if(w/hh>asp){var nh=w/asp;y0-=(nh-hh)/2;hh=nh}else{var nw=hh*asp;x0-=(nw-w)/2;w=nw}
  if(w>1000){w=1000;hh=520;x0=0;y0=0}
  x0=Math.max(0,Math.min(1000-w,x0));y0=Math.max(0,Math.min(520-hh,y0));
  return x0.toFixed(1)+' '+y0.toFixed(1)+' '+w.toFixed(1)+' '+hh.toFixed(1);
}
