      h+='<tr><td style="padding:7px 8px;border-bottom:1px solid rgba(var(--fg-rgb),.07);color:var(--paper)"><span style="display:inline-block;width:9px;height:9px;background:'+col+';margin-right:7px"></span>'+esc(fx.flow.name||'Unnamed flow')+'</td>';
      h+='<td style="padding:7px 8px;border-bottom:1px solid rgba(var(--fg-rgb),.07);color:var(--paper)">'+(fx.jurisdictions.length?esc(fx.jurisdictions.slice().sort().join(', ')):'<span style="color:var(--stone);font-style:italic">none recorded yet</span>')+'</td>';
