      h+='<button onclick="UI.diagSel=null;render()" style="font-size:12px;padding:2px 8px;background:transparent;border:1px solid rgba(var(--fg-rgb),.15);color:var(--stone);cursor:pointer;font-family:var(--mono)">\u2715 Close</button>';
