var MAP_VIEWS=[{v:'chain',l:'Whole chain',t:'Shows the chain through this component. Components that share its path but are not directly linked to it are drawn faded.'},{v:'direct',l:'Direct connections',t:'Shows this component and only the components directly linked to it.'},{v:'reach',l:'Everything reachable',t:'Shows every chain that reaches this component or that it reaches, including chains a declared path excluded, which are drawn faint.'}]; /* 23 Sep 2026 (Paul): the map has its own view, separate from the card's */
