    var sx=LABEL_W+PAD+(CW-totalW)/2;
    /* P-3 (Paul, 26 Aug 2026): workflows HANG from their applications — each pill sits under its
       parent's x, siblings spread; the unparented fall back to the row. */
    var _hangX={};
    if(_isWf){
      var _grp={};items.forEach(function(it2){var p2=it2.comp.appId||'';(_grp[p2]=_grp[p2]||[]).push(it2.comp.id)});
      for(var _pk2 in _grp){
        var _pn=nodeMap[_pk2];if(!_pn)continue;
        var _sibs=_grp[_pk2];
        _sibs.forEach(function(_sid,_si){_hangX[_sid]=_pn.cx+(_si-(_sibs.length-1)/2)*(enw+8)});
        /* P4: clamp the GROUP by shifting it whole \u2014 squashing siblings onto one point garbled them */
        var _lo=_pn.cx-((_sibs.length-1)/2)*(enw+8)-enw/2,_hi=_pn.cx+((_sibs.length-1)/2)*(enw+8)+enw/2;
        var _sh=0;
        if(_lo<LABEL_W+PAD)_sh=(LABEL_W+PAD)-_lo;
        if(_hi+_sh>VW-PAD)_sh=(VW-PAD)-_hi;
        if(_sh)_sibs.forEach(function(_sid){_hangX[_sid]+=_sh});
      }
    }
