      items=items.filter(function(it){var cid=it.comp.id;if(cid===sel)return true;if(_mv==='direct')return !!_fsc.one[cid];if(_fsc.tier3&&_fsc.tier3[cid]&&_mv!=='reach')return false;return !!_fsc.ids[cid]}); /* Direct connections: one step; Whole chain: excluded chains hidden; Everything reachable: excluded chains shown */
      n=items.length;var _L3=bandLayout(bd,n);enw=_L3.enw;bd.perRow=_L3.perRow;
