window.addEventListener('mousemove',function(evt){
  if(!_dd)return;
  var svg=document.getElementById(_dd.svgId);
  if(!svg){_dd=null;return;}
  var sp=clientToSVGPt(svg,evt.clientX,evt.clientY);
  var dx=sp.x-_dd.startX; var dy=sp.y-_dd.startY;
  if(Math.sqrt(dx*dx+dy*dy)>3){
    _diagMoved=true;
    document.body.style.cursor='grabbing';
    document.body.style.userSelect='none';
    var elId='dn_'+_dd.mode+'_'+_dd.key;
    var el=document.getElementById(elId);
    if(el){el.setAttribute('transform','translate('+dx+','+dy+')');}
    // Draw a live ghost line from original to new position in the SVG
    var ghost=document.getElementById('dd_ghost');
    if(!ghost){
      ghost=document.createElementNS('http://www.w3.org/2000/svg','circle');
      ghost.setAttribute('id','dd_ghost');
      ghost.setAttribute('r','4');
      ghost.setAttribute('fill','none');
      ghost.setAttribute('stroke','rgba(184,137,42,0.6)');
      ghost.setAttribute('stroke-width','1');
      ghost.setAttribute('stroke-dasharray','3,2');
      try{svg.appendChild(ghost);}catch(e){}
    }
    ghost.setAttribute('cx',String(_dd.origCx+dx));
    ghost.setAttribute('cy',String(_dd.origCy+dy));
  }
});

window.addEventListener('mouseup',function(evt){
  if(!_dd)return;
  document.body.style.cursor='';
  document.body.style.userSelect='';
  var ghost=document.getElementById('dd_ghost');
  if(ghost&&ghost.parentNode)ghost.parentNode.removeChild(ghost);
  if(_diagMoved){
    var svg=document.getElementById(_dd.svgId);
    if(svg){
      var sp=clientToSVGPt(svg,evt.clientX,evt.clientY);
      var dx=sp.x-_dd.startX; var dy=sp.y-_dd.startY;
      if(!data.diagPos)data.diagPos={};
      if(!data.diagPos[_dd.mode])data.diagPos[_dd.mode]={};
      data.diagPos[_dd.mode][_dd.key]={cx:_dd.origCx+dx,cy:_dd.origCy+dy};
      saveData();
    }
    var savedKey=_dd.key; var savedMode=_dd.mode;
    var isFS=!!(document.fullscreenElement||document.webkitFullscreenElement);
    _dd=null;_diagMoved=false;
    if(isFS){
      // Rebuild SVG content in-place without exiting fullscreen
      var svgId='archDiagSVG_'+savedMode;
      var svgEl=document.getElementById(svgId);
      if(svgEl){
        var newSvg=savedMode==='flow'?buildFlowSVG(UI.diagSel):buildMindMapSVG(UI.diagSel);
        var tmp=document.createElement('div');tmp.innerHTML=newSvg;
        var newSvgEl=tmp.querySelector('svg');
        if(newSvgEl){svgEl.innerHTML=newSvgEl.innerHTML;}
      }
    }else{render();}
  } else {
    // Short movement = click: toggle selection
    var k=_dd.key;
    _dd=null;_diagMoved=false;
    var isFS2=!!(document.fullscreenElement||document.webkitFullscreenElement);
    if(!isFS2){
      UI.diagSel=UI.diagSel===k?null:k;
      render();
    }
  }
});

function exportState(){
  try{
    var org=(getOrg(currentOrgId)||{}).name||'workspace';
    var payload={app:'nextchapter-architecture',type:'architecture-state',schema:'architecture-v1',org:org,exportedAt:new Date().toISOString(),data:data};
    var blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
    var url=URL.createObjectURL(blob);
    var a=document.createElement('a');a.href=url;
    a.download='architecture-state-'+(org.replace(/[^a-z0-9]+/gi,'-').replace(/^-+|-+$/g,'').toLowerCase()||'workspace')+'-'+todayIso()+'.json';
    document.body.appendChild(a);a.click();document.body.removeChild(a);
    setTimeout(function(){URL.revokeObjectURL(url);},1500);
  }catch(e){alert('Export failed: '+((e&&e.message)||e));}
}
function importState(){
  var inp=document.createElement('input');inp.type='file';inp.accept='application/json,.json';
  inp.onchange=function(){
    var f=inp.files&&inp.files[0];if(!f)return;
    var r=new FileReader();
    r.onload=function(){applyImportedState(String(r.result));};
    r.onerror=function(){alert('Could not read that file.');};
    r.readAsText(f);
  };
  inp.click();
}
function applyImportedState(text){
  var parsed;
  try{parsed=JSON.parse(text);}catch(e){alert('That file is not valid JSON.');return;}
  var d=(parsed&&typeof parsed==='object'&&parsed.data)?parsed.data:parsed;
  if(!d||typeof d!=='object'||(d.completedSteps===undefined&&d.dataEstate===undefined&&d.enterprise===undefined)){alert('That does not look like an Architecture state file.');return;}
  if(parsed&&parsed.schema&&parsed.schema!=='architecture-v1'){if(!confirm('This file was exported from a different schema ('+parsed.schema+'). Import anyway?'))return;}
  if(!currentOrgId){alert('Open a workspace before importing a state.');return;}
  if(!confirm('Import this state? It replaces the current workspace\u2019s data. Export first if you want to keep it.'))return;
  try{
    Store.writeOrg(currentOrgId,d);
    loadData();applyTeamRoster();
    Auth.setSession((USERS[0]&&USERS[0].id)||currentUserId);
    render();
  }catch(e){alert('Import failed: '+((e&&e.message)||e));}
}

