/* -- THE SAMPLE ORGANIZATION, AS DATA (5 Oct 2026, Paul: "rely on things being right") --
   The samples are plain data in today's layout. Nothing builds or reshapes them. Every date is an
   offset from today (D: a calendar date; I: that date at midnight UTC; F: that date written out;
   T and IT: a moment in milliseconds), so the sample reads the same whenever it is loaded. */
function sampleDates(){ var now=Date.now(), base=todayIso();
  var MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
  function D(n){ return isoAddDays(base,n); }
  function I(n){ return D(n)+'T00:00:00.000Z'; }
  function F(n){ var p=D(n).split('-'); return MONTHS[+p[1]-1]+' '+(+p[2])+', '+p[0]; }
  function T(ms){ return now+ms; }
  function IT(ms){ return new Date(now+ms).toISOString(); }
  return {D:D,I:I,F:F,T:T,IT:IT}; }
