  var _own=(data&&Array.isArray(data.roster))?data.roster:[]; data=sampleMainData(); data.roster=_own; /* 5 Oct 2026 (Paul): the organization's own people stay; the sample replaces everything else */ saveData(); applyTeamRoster(); go('readiness');
