    var rdy=eafBReady(d);var onP=(mode==='fill'||mode==='path');var recv=(d.kind==='handoff'||d.kind==='escalates')&&d.target&&eafRefFilled(d.target)? /* F-19: the main sequence may end with a hand-off too */eafUc(eafWho(d.target,aid)):'';h+='<div style="margin-top:14px;display:flex;gap:8px;flex-wrap:wrap">'+(recv?'<span data-gate="'+'eafb-add0-'+aid+'">'+btn('Add this step; '+recv+' takes it from here','eafBAdd(\''+aid+'\',true,true)','bp','',!rdy)+'</span>'+btn('Add this step; '+recv+' does the next part','eafBAdd(\''+aid+'\',false)','bs','',!rdy):d.kind==='delivers'?btn(onP?'Add this step; the result lands here and the path ends':'Add this step; the result lands here and the workflow ends','eafBAdd(\''+aid+'\',true,true)','bp','',!rdy)+btn(onP?'Add this step and ask me about the next one on this path':'Add this step and ask me about the next one','eafBAdd(\''+aid+'\',false)','bs','',!rdy):d.kind==='stops'?btn(onP?'Add this stop; the path ends here':'Add this stop; the workflow ends here','eafBAdd(\''+aid+'\',true)','bp','',!rdy):(d.next&&f.steps.some(function(x){return x.id===d.next})?btn('Add this step; the work goes back to step '+(function(){var ix=f.steps.map(function(x){return x.id}).indexOf(d.next);return eafStructure(f).info[ix].no})(),'eafBAdd(\''+aid+'\',true)','bp','',!rdy):btn(onP?'Add this step and ask me about the next one on this path':'Add this step and ask me about the next one','eafBAdd(\''+aid+'\',false)','bp','',!rdy)+btn(onP?'That was the last step on this path':'That was the last step','eafBAdd(\''+aid+'\',true)','bs','',!rdy)))+(rdy?'':'<div style="font-size:12px;color:var(--stone);align-self:center">'+(!d.kind?'Choose the kind of step first.':d.kind==='decides'?'Write the question first.':d.kind==='waits'?'Say what it waits for first.':'Write what the step does first.')+'</div>')+'</div></div>'; /* on a path the buttons say so (Paul, 19 Sep 2026) */
