    var origin='';if(s.path&&s.path.dec){var di=stx.idIdx[s.path.dec];var ds=f.steps[di];var bl=ds&&ds.decision&&ds.decision.branches[s.path.bi]?ds.decision.branches[s.path.bi].label:'';if(ds)origin='Where step '+stx.info[di].no+'\u2019s \u201c'+esc(bl||'answer')+'\u201d leads'} /* 19 Sep 2026 */
    h+='<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px"><span style="font-family:var(--mono);font-size:10px;letter-spacing:.1em;color:#FFFFFF;background:#4A6E8A;padding:3px 8px">STEP '+stx.info[i].no+'</span><span style="font-size:12px;color:var(--stone)">'+(s.draft?'Not yet described. ':'')+esc(EAF_KIND_GLOSS[s.kind]||'')+(origin?(EAF_KIND_GLOSS[s.kind]?' \u00B7 ':'')+origin:'')+'</span><span style="margin-left:auto;display:inline-flex;gap:4px">'+btn('\u2191','eafMoveStep(\''+aid+'\',\''+s.id+'\',-1)','bs','font-size:11px;padding:3px 7px',i===0||eafSegKey(f.steps[i-1])!==eafSegKey(s))+btn('\u2193','eafMoveStep(\''+aid+'\',\''+s.id+'\',1)','bs','font-size:11px;padding:3px 7px',i===f.steps.length-1||eafSegKey(f.steps[i+1])!==eafSegKey(s))+btn('+ Step below','eafAddStep(\''+aid+'\',\''+s.id+'\')','bs','font-size:11px;padding:3px 7px')+btn('Remove','eafDelStep(\''+aid+'\',\''+s.id+'\')','bg2','font-size:11px;padding:3px 7px;color:#6E4A5A')+'</span></div>';
    if(s.kind!=='stops')h+='<div style="margin:0 0 12px">'+eafRefEditor(aid,'steps.#'+s.id+'.actor',s.actor,{laneLabel:'Taken by',laneTip:'Who or what takes this step: usually the agent; sometimes a person or a system.'})+'</div>'; /* a stop has no actor (19 Sep 2026) */ /* 18 Sep 2026 (Paul): who takes it first, then the kind and whom it reaches, then what it does */
