    h+='<div>'+eafKick('Kind of step','Not sure? Open \u201cWhich kind should I choose?\u201d below.')+eafKindSelect(s.kind,'eafSet(\''+aid+'\',\'steps.#'+s.id+'.kind\',this.value)',!s.kind)+'</div>';
    h+='</div>'+eafKindGlossary();
    if(EAF_USES_TARGET[s.kind])h+='<div style="margin-top:12px">'+eafRefEditor(aid,'steps.#'+s.id+'.target',s.target,{systemsOnly:true,laneLabel:'Using'})+'</div>'; /* an action or a decision may use a system (Paul, 18 Sep 2026) */
    if(takes)h+='<div style="margin-top:12px">'+eafRefEditor(aid,'steps.#'+s.id+'.target',s.target,{lanes:EAF_KIND_LANES[s.kind],laneLabel:s.kind==='requests'?'Asks':s.kind==='notifies'?'Tells':s.kind==='delivers'?'Delivers to':'Passes to',laneTip:'Whom or what this step reaches. If it is a person or party outside your organization, tick the box and name their organization.'})+'</div>';
    if(s.kind!=='decides')h+='<div style="margin-top:10px">'+eafKick(s.kind==='stops'?'Why the workflow stops here (optional)':s.kind==='waits'?'What it waits for, starting with \u201cwaits\u201d':'What it does, in one line, starting with a verb','Write what the actor does as a short present-tense clause: \u201creads the email,\u201d \u201clooks up the customer,\u201d \u201csends the draft for approval.\u201d The plain-words version of the map is built from these lines.')+'<input type="text" value="'+escAttr(s.text||'')+'" placeholder="'+(s.kind==='waits'?'For example: Waits for the payment run':'For example: Looks up the customer and order history')+'" id="eaf_'+aid+'_st_'+s.id+'" style="'+EAF_IN+'" onchange="eafSet(\''+aid+'\',\'steps.#'+s.id+'.text\',this.value)"></div>';
    if(s.kind&&s.kind!=='decides'&&s.kind!=='stops'&&!s.ends&&f.steps.length>1){var optsE=f.steps.map(function(x,xi){return xi===i||x.draft?'':'<option value="'+x.id+'"'+(s.next===x.id?' selected':'')+'>'+(xi<i?'back to':'on to')+' step '+stx.info[xi].no+(x.text?', \u201c'+esc(x.text)+'\u201d':'')+'</option>'}).join('');
      h+='<div style="margin-top:10px">'+eafKick('Then','Where the work goes after this step. Usually the next step; choose an earlier one to send it back.')+'<select style="'+EAF_IN+'" onchange="eafSet(\''+aid+'\',\'steps.#'+s.id+'.next\',this.value)"><option value=""'+(!s.next?' selected':'')+'>the next step</option>'+optsE+'</select></div>';} /* 20 Sep 2026 (Paul): a step's own Then */
    if(s.kind==='decides'){ /* 18 Sep 2026 (Paul): the decision's fields in order — question, answers, how made, accountable, depends on */
      var d=s.decision||{branches:[]};var ans='';
      (d.branches||[]).forEach(function(b,bi){
        var tgtIdx=f.steps.map(function(x){return x.id}).indexOf(b.next);var loop=tgtIdx>=0&&stx.info[tgtIdx].depth<=stx.info[i].depth;
        ans+='<div style="margin:0 0 12px"><div style="display:flex;align-items:center;gap:8px">'+eafAnsNum(bi+1)+'<input type="text" value="'+escAttr(b.label||'')+'" id="eaf_'+aid+'_br_'+s.id+'_'+b.id+'" placeholder="e.g. refund over $500" style="'+EAF_IN+';width:auto;min-width:180px" onchange="eafSet(\''+aid+'\',\'steps.#'+s.id+'.decision.branches.#'+b.id+'.label\',this.value)">'+(loop?'<span style="font-family:var(--mono);font-size:10px;letter-spacing:.06em;color:var(--gold)">LOOPS BACK</span>':'')+((d.branches||[]).length>2?btn('\u00D7','eafDelBranch(\''+aid+'\',\''+s.id+'\',\''+b.id+'\')','bs','font-size:11px;padding:2px 7px'):'')+'</div><div style="margin:6px 0 0 30px;display:flex;align-items:center;gap:8px;max-width:460px"><span style="font-size:12px;color:var(--stone);flex:none">leads to</span><select data-lock="agentRegistry::'+aid+'" style="'+EAF_IN+';flex:1" onchange="eafBranchTo(\''+aid+'\',\''+s.id+'\',\''+b.id+'\',this.value)"><option value=""'+(!b.next?' selected':'')+'>Select\u2026</option><option value="__new">A new step on this answer\u2019s path</option><option value="__meet"'+(b.next==='__meet'?' selected':'')+'>Nothing more on this answer: it goes on where the paths come back together</option>'+f.steps.map(function(x,xi){return xi===i?'':'<option value="'+x.id+'"'+(b.next===x.id?' selected':'')+'>'+stx.info[xi].no+'. '+esc(eafUc((x.text||(x.kind?EAF_KINDS.filter(function(k){return k[0]===x.kind})[0][1]:'not yet described')).slice(0,48)))+(stx.info[xi].depth<=stx.info[i].depth?' (goes back to this step)':'')+'</option>'}).join('')+'<option value="__newdeliver">A new step that delivers the result on this answer\u2019s path</option><option value="__stop"'+(b.next==='__stop'?' selected':'')+'>The workflow stops here, nothing delivered</option></select></div></div>'; /* 19 Sep 2026 (Paul): numbered, inset */
      });
      ans+=btn('+ Another answer','eafAddBranch(\''+aid+'\',\''+s.id+'\')','bs','font-size:11px;padding:3px 8px');
      h+='<div style="margin:12px 0 0;padding:12px 14px;border-left:3px solid var(--gold);background:rgba(var(--fg-rgb),.02)">'+eafDecisionForm('eafSet',aid,'steps.#'+s.id+'.',s.text,d,ans)+'</div>';
    }
