/* the worked example: a warehouse replenishment agent that is not in the seed (Paul's ruling, 11 Sep 2026) */
function eafExampleEntry(){
  var P=function(n,ext){return {lane:'people',ref:n,external:!!ext,externalOrg:ext||'',unregistered:false}};var S=function(n){return {lane:'systems',ref:n,external:false,externalOrg:'',unregistered:false}}; /* the example's systems carry no register flag (Paul, 11 Sep 2026) */var AG=function(){return {lane:'agent',ref:'',external:false,externalOrg:'',unregistered:false}};
  var st=function(id,kind,actor,text,target,decision){return {id:id,kind:kind,actor:actor,target:target||P(''),text:text,verb:'',decision:decision||{right:'',accountable:'',basis:'',branches:[{label:'',next:''},{label:'',next:''}]}}};
  var s=[
    st('x1','requests',AG(),'Reads current stock levels and open orders',S('Warehouse database')),
    st('x2','decides',AG(),'Is any item below its reorder point?',null,{right:'rule',accountable:'Warehouse manager',basis:'The reorder point set for each item',branches:[{label:'yes',next:'x3'},{label:'no',next:'__stop'}]}),
    st('x3','acts',AG(),'Drafts a reorder quantity for each low item'),
    st('x4','handoff',AG(),'Sends the draft order for approval',P('Buyer with authority to spend')),
    st('x5','decides',P('Buyer with authority to spend'),'Approve the order?',null,{right:'person',accountable:'Buyer with authority to spend',basis:'The budget for the month and what the supplier can deliver',branches:[{label:'approved',next:'x6'},{label:'needs changes',next:'x3'}]}),
    st('x6','delivers',AG(),'Places the approved order',P('The supplier','Acme Components')),
    st('x8','acts',AG(),'Records the order in the ordering system',S('Ordering system')), /* 18 Sep 2026 (Paul): an action using the application, not a request */ /* 11 Sep 2026 (Paul): the process reaches an application as well as data */
    st('x7','notifies',AG(),'Logs the order confirmation for the team',P('Ordering team')),
    (function(){var d=st('x9','delivers',AG(),'Confirms the order to the warehouse team, in the ordering system',P('Warehouse team'));d.ends=true;return d})() /* 20 Sep 2026 (Paul): the delivery is a step of its own; the flow-level delivery ("the confirmed order, in the ordering system") is withdrawn */
  ];
  return {id:'__example',name:'Replenishment agent',appId:'__example',autonomy:'Human-approved',humanLoop:'Yes',flow:{trigger:{kind:'schedule',text:'Every morning at six, before the warehouse opens',source:S('Warehouse database')},steps:s}};
}
