  h+='<div class="step-tabs" style="display:flex;gap:8px;margin-bottom:24px;flex-wrap:wrap">';
  [{id:'governance',l:'Governance',k:'2.4_governance'},{id:'review',l:'Applications and agents',k:'2.4_review'}] /* 11 Sep 2026: two tabs; Enterprise Architecture Fit is Step 2.5 */.forEach(function(t){
    h+='<button onclick="UI.expandEdit=null;UI.step24Part=\''+t.id+'\';render()" class="btn '+(part===t.id?'bp':'bs')+'">'+(ct[t.k]?'\u2713 ':'')+t.l+'</button>';
  });
