  if(!_sh.length)h+='<div style="padding:18px;border:1px solid var(--rule);text-align:center"><p style="color:var(--stone);font-size:14px;margin:0">No shadow or ungoverned tools in the census. Anything discovered later is recorded here.</p></div>';
  else{var _dc={d:0,p:0};_sh.forEach(function(m){if(m.shadowDecision)_dc.d++;else _dc.p++});
    h+='<div style="display:flex;gap:14px;flex-wrap:wrap;margin:0 0 12px;font-size:13px"><span style="color:#3D6B6E;font-weight:600">Decided '+_dc.d+'</span><span style="color:#6E4A5A;font-weight:600">Pending '+_dc.p+'</span></div>';
    _sh.forEach(function(m){var _sd=m.shadowDecision?[m.shadowDecision.toUpperCase(),m.shadowDecision==='Prohibit'?'#6E4A5A':m.shadowDecision==='Monitor'?'#7A6B4A':'#3D6B6E']:['NO VERDICT','#8A8278'];h+=audRow('aiModels',m,ctx==='dashboard'?'dashboard':'2.4',null,'<span style="font-size:10px;padding:2px 7px;background:'+_sd[1]+';color:#fff;font-weight:600">'+_sd[0]+'</span>','gov24s')})}
  h+='<div style="margin-top:12px">'+btn('+ Record a shadow tool','(function(){sweepBlankInline(true);var c=addComponent(\'aiModels\',{name:\'\',modelType:\'Unknown\',usage:\'Shadow\',governance:\'Ungoverned\',_inlineDraft:true});UI.expandEdit=\'aud_\'+c.id;UI.inlineAdd={hostLayer:null,host:null,layer:\'aiModels\',field:\'__aud\',id:c.id,_ctx:inlineCtx()};render()})()','bs')+'</div>';
