       var SH=function(t,sub){return '<div style="display:flex;align-items:baseline;gap:10px;margin:0 0 10px"><div style="font-size:13.5px;font-weight:700;color:var(--paper)">'+t+'</div>'+(sub?'<div style="font-size:12px;color:var(--stone)">'+sub+'</div>':'')+'</div>'};
