    h+='<div style="background:var(--ink);padding:14px 16px;box-shadow:inset 0 -3px 0 '+(set?'#3D6B6E':'rgba(var(--fg-rgb),.15)')+'">';
    h+='<div style="font-size:13px;font-weight:600;color:var(--paper);text-align:center;min-height:36px;line-height:1.35">'+dm.name+'</div>'; /* 4 Sep 2026 (Paul's ruling): a two-line title no longer pushes the editors out of line */
    h+='<div style="font-size:12px;color:'+(att.n?'#6E4A5A':'#3D6B6E')+';text-align:center;margin:4px 0 10px;min-height:36px;line-height:1.5">'+att.n+' of '+att.total+' question'+(att.total===1?'':'s')+' require'+(att.n===1?'s':'')+' further exploration</div>';
    h+=sel('Review cadence','sov_mon_'+dm.k+'_cadence',m.cadence||'',SOV_CADENCE_OPTS)+ta('Dimension owner','sov_mon_'+dm.k+'_owner',m.owner||'','Who reviews this dimension',1)+dateField('Next review','sov_mon_'+dm.k+'_next',m.next||'','');
