function rbShortName(m){var p=(m.name||'').split(' ');return p.length>1?p[0]+' '+p[1].charAt(0)+'.':m.name}
function rbOrgChartSVG(mode,membersArg){ /* P21 (Paul's ruling, 30 Aug 2026): optional members array — the Data Governance Forum reuses the tidy tree */
  // mode: 'app' (dark tokens) or 'print' (dark-on-white)
  rbEnsure();var members=membersArg||data.rbOrg.members;
  var ink=mode==='print'?'#1E2530':'var(--paper)',stone=mode==='print'?'#303C4A':'var(--stone)',line=mode==='print'?'#9DAAB9':'rgba(138,130,120,.5)',bg=mode==='print'?'#FFFFFF':'transparent';
  // depth by parent chain
  var byId={};members.forEach(function(m){byId[m.id]=m});
  function depth(m,seen){if(!m.parent||!byId[m.parent])return 0;seen=seen||{};if(seen[m.id])return 0;seen[m.id]=1;return 1+depth(byId[m.parent],seen)}
  var levels=[];
  members.forEach(function(m){var d=depth(m);levels[d]=levels[d]||[];levels[d].push(m)});
  /* Q4 (Paul, 28 Aug 2026): the old layout spread each level independently across the full
     width, so a second layer landed nowhere near its parents \u2014 crossing connectors and an
     unusable picture. This is a tidy tree: each subtree claims leaf slots, children sit
     under their parents, parents center over their children. Any depth. */
  var NW=158,NH=54,VG=44,HG=22;
  var kids={};members.forEach(function(m){if(m.parent&&byId[m.parent]){(kids[m.parent]=kids[m.parent]||[]).push(m)}});
  var roots=members.filter(function(m){return !m.parent||!byId[m.parent]});
  function leaves(m,seen){seen=seen||{};if(seen[m.id])return 1;seen[m.id]=1;var k=kids[m.id]||[];if(!k.length)return 1;var n=0;k.forEach(function(c){n+=leaves(c,seen)});return n}
  var totalLeaves=0;roots.forEach(function(r){totalLeaves+=leaves(r)});
  var W=Math.max(640,totalLeaves*(NW+HG)+40);
  var H=(levels.length||1)*(NH+VG)+30;
  var pos={};var slotW=(W-40)/Math.max(1,totalLeaves);var cursor={x:20};
  function place(m,d,seen){
    seen=seen||{};if(seen[m.id])return;seen[m.id]=1;
    var k=(kids[m.id]||[]);
    if(!k.length){pos[m.id]={x:cursor.x+slotW/2,y:26+d*(NH+VG)};cursor.x+=slotW;return}
    k.forEach(function(c){place(c,d+1,seen)});
    var xs=k.filter(function(c){return pos[c.id]}).map(function(c){return pos[c.id].x});
    pos[m.id]={x:xs.length?(Math.min.apply(null,xs)+Math.max.apply(null,xs))/2:(cursor.x+slotW/2),y:26+d*(NH+VG)};
  }
  roots.forEach(function(r){place(r,0)});
  var h='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;max-width:'+W+'px;background:'+bg+'">';
  // connectors
  members.forEach(function(m){if(m.parent&&pos[m.parent]&&pos[m.id]){var p=pos[m.parent],c=pos[m.id];var my=(p.y+NH+c.y)/2;
    h+='<path d="M'+p.x+' '+(p.y+NH)+' V'+my+' H'+c.x+' V'+c.y+'" fill="none" stroke="'+line+'" stroke-width="1.5"/>'}});
  // nodes
  members.forEach(function(m){var p=pos[m.id];if(!p)return;var col=RB_ROLE_COLORS[m.role]||'#4A6E8A';
    h+='<g><rect x="'+(p.x-NW/2)+'" y="'+p.y+'" width="'+NW+'" height="'+NH+'" rx="6" fill="'+(mode==='print'?'#FFFFFF':'rgba(90,125,138,.08)')+'" stroke="'+col+'" stroke-width="2"'+(m.role==='Advisor'?' stroke-dasharray="5,3"':'')+'/>';
    h+='<text x="'+p.x+'" y="'+(p.y+20)+'" text-anchor="middle" font-size="12" font-weight="600" fill="'+ink+'">'+esc(m.name||'')+'</text>';
    h+='<text x="'+p.x+'" y="'+(p.y+35)+'" text-anchor="middle" font-size="10" fill="'+stone+'">'+esc(m.title||'')+'</text>';
    var _so=(data.sovereigntyOps||{}).ownerId===m.id; /* 3 Sep 2026 (Paul's ruling): the sovereignty owner is marked on the chart */
    h+='<text x="'+p.x+'" y="'+(p.y+48)+'" text-anchor="middle" font-size="9" fill="'+col+'" font-family="ui-monospace,Menlo,Consolas,monospace" letter-spacing=".08em">'+(m.role||'').toUpperCase()+'</text>';
    if(_so){h+='<path d="M '+(p.x-NW/2)+' '+(p.y+NH-2)+' H '+(p.x+NW/2)+' V '+(p.y+NH+8)+' Q '+(p.x+NW/2)+' '+(p.y+NH+14)+' '+(p.x+NW/2-6)+' '+(p.y+NH+14)+' H '+(p.x-NW/2+6)+' Q '+(p.x-NW/2)+' '+(p.y+NH+14)+' '+(p.x-NW/2)+' '+(p.y+NH+8)+' Z" fill="'+(mode==='print'?'#C9A96E':'var(--gold)')+'" stroke="'+(mode==='print'?'#C9A96E':'var(--gold)')+'" stroke-width="2" stroke-linejoin="round"/>';
      h+='<text x="'+p.x+'" y="'+(p.y+NH+10)+'" text-anchor="middle" font-size="9" font-weight="700" fill="'+(mode==='print'?'#1E2530':'#12181F')+'" font-family="ui-monospace,Menlo,Consolas,monospace" letter-spacing=".06em">SOVEREIGNTY OWNER</text>'}
    h+='</g>'});
  h+='</svg>';
  return h;
}
