     data.rbOrg.members.splice(i,1);   data.rbOrg.members.forEach(function(x){if(x.parent===m.id)x.parent=''});   if(data.sovereigntyOps&&data.sovereigntyOps.ownerId===m.id){data.sovereigntyOps.ownerId='';data.sovereigntyOps.owner='';Store.commit('sovereigntyOps')} /* 23 Sep 2026 (the Phase 4 review): the current owner leaves with the member; logged reviews keep theirs */
  var ng={};Object.keys(data.rbRaci.grid).forEach(function(k){if(k.split('_')[1]!==m.id)ng[k]=data.rbRaci.grid[k]});
