/* Phase 5 reporting — scoped to standing pages. Approved sprint outputs keep their own builders. */
function p5Definitions(){return [
 {id:'5.1',name:'Architecture Dashboard',lead:'Architecture readiness, the reviews ahead, both the stack and mind map, and the standing responsibilities and plans.',all:'Complete dashboard',depth:true,scopes:[['stack','AI Tech Stack'],['mindmap','Mind Map'],['board','Architecture Review Board'],['skills','Skills Plan'],['zerotrust','Zero-Trust Initiatives'],['architecture-settings','Architecture Review Settings'],['data-settings','Data Governance Review Settings']]},
 {id:'5.2',name:'Architecture Map',lead:'The system flow diagram and the component records, as they stand today.',all:'Map and component records',depth:true,scopes:[['flow','System Flow Diagram'],['stack','AI Tech Stack'],['mindmap','Mind Map'],['explorer','Component Explorer']]},
 {id:'5.3',name:'Sovereignty Center',lead:'All four sovereignty dimensions, their actions and results, dependencies and mitigations, ownership, monitoring, human judgment, and vendor roadmaps.',scopes:[['questions','All sovereignty questions'],['questions-dataSov','Data sovereignty'],['questions-infraSov','Infrastructure sovereignty'],['questions-decisionSov','Decisional sovereignty'],['questions-adaptSov','Adaptive sovereignty'],['inventory','Dependency Inventory'],['adapt','Adapting to Dependencies'],['mitigations','Sovereignty Mitigations'],['judgment','Conditions for Human Judgment'],['own','Sovereignty Ownership'],['vendors','Vendor Roadmaps'],['jurmap','Jurisdiction Map']]},
 {id:'5.4',name:'Testing Log',lead:'Testing policy, deployment tests, security and cascade scenarios, risk assessments, and the recorded remediation plans.',scopes:[['policy','Testing Policies and Tools'],['deploy','Deployment Tests'],['security','Security and Identity Tests'],['cascade','Cascade Failure Scenarios'],['risk','Architectural Risk Scenarios'],['remediation','Remediation Plans']]},
 {id:'5.5',name:'Analytics',lead:'The program’s figures and charts as they stand today.',scopes:[]},
 {id:'stdData',name:'Data Domains and Standards',lead:'Data domains and their owners, quality standards, platform strategy, and the assessment of each data system.',depth:true,scopes:[['domains','Data Domains'],['platform','Data Platform'],['systems','Review Data Systems']]},
 {id:'stdCompute',name:'Compute Goals and Strategy',lead:'The compute goals, each source judged against them, and the dated strategy plan.',depth:true,scopes:[['goals','Compute and Infrastructure Goals'],['assess','Review Compute Sources'],['plan','Compute Strategy Plan']]},
 {id:'stdModel',name:'Model Rules',lead:'Evaluation criteria and their evidence owners, guardrails, retirement policy, observability principles, and the model reviews.',depth:true,scopes:[['rules','Model Rules and Observability Principles'],['review','Review Models']]},
 {id:'stdInteg',name:'Integration Standards',lead:'The API-first policy, the circuit-breaker design, and the recorded assessment of each integration.',depth:true,scopes:[['standards','Integration Standards'],['review','Review Integrations']]},
 {id:'stdApp',name:'Application and Agent Governance',lead:'The organization’s rules and principles, its applications, workflows, and agents, and its decisions on shadow tools.',depth:true,scopes:[['governance','Governance Rules'],['review','Applications, Agents, and Shadow Tools']]},
 {id:'archscores',name:'Architecture Scores',lead:'The fourteen baseline questions, current answers, and the archive of logged scoring rounds.',scopes:[['current','Current Architecture Scores'],['archive','Architecture Score Archive']]},
 {id:'archreview',name:'Architecture Review',lead:'The Architecture Review Board’s agenda, findings, and architecture scores.',all:'Selected Architecture Review',depth:true,scopes:[['latest','Latest Logged Architecture Review'],['current','Current review — not logged']]},
 {id:'dgreview',name:'Data Governance Review',lead:'The current agenda and decisions, followed by the logged review reports.',all:'Current review and review reports',scopes:[['current','Current Data Governance Review'],['latest','Latest Data Governance Review Report']]},
 {id:'jurmap',name:'Jurisdiction Map',lead:'Where systems hold data and compute on it, and the additional legal jurisdictions recorded for their providers.',scopes:[]},
 {id:'mgmt-hub',name:'Module Management',lead:'Every shared step, its ownership and dates, together with the program’s pace and workload.',all:'Assignments and analytics',scopes:[]}
]}
function p5Definition(id){return p5Definitions().find(function(d){return d.id===String(id).split('/')[0]})||null}
function p5UnitName(id){var d=p5Definition(id);if(!d)return String(id);var sub=String(id).split('/')[1];var s=(d.scopes||[]).find(function(x){return x[0]===sub});return s?s[1]:d.name}
function p5PrintBar(id){
 if(UI._printing)return '';if(id==='5.1')return dashboardPrintControls();if(id==='archreview')return reportReviewControl(id);
 var d=p5Definition(id);if(!d)return printBar();var sc=(UI.p5PrintScope||{})[id]||'',depth=(UI.p5PrintDepth||{})[id]||'summary';
 var _plain=id!=='5.2'; /* 29 Sep 2026 (Paul): the box stays only on the Architecture Map, whose bar carries the connections control; every other print bar is plain, the five standards pages included */var h='<div class="print-bar p5-print-bar'+(_plain?' p5-print-plain':'')+'" data-print-page="'+esc(id)+'"><div class="p5-print-fields">'; /* 29 Sep 2026 (Paul's rule): a bar holding only Print content and Save as PDF (or Save alone) carries no box; a bar with more (the Record detail chooser, the Architecture Map's connections control) keeps it */
 if((d.scopes||[]).length)h+='<label class="p5-print-choice">Print content<select aria-label="Print content for '+esc(d.name)+'" onchange="UI.p5PrintScope=UI.p5PrintScope||{};UI.p5PrintScope[\''+id+'\']=this.value"><option value="">'+esc(d.all||'Complete page — all tabs')+'</option>'+d.scopes.map(function(s){return '<option value="'+s[0]+'"'+(sc===s[0]?' selected':'')+'>'+esc(s[1])+'</option>'}).join('')+'</select></label>';
 if(d.depth)h+='<label class="p5-print-choice">Record detail<select aria-label="Record detail for '+esc(d.name)+'" onchange="UI.p5PrintDepth=UI.p5PrintDepth||{};UI.p5PrintDepth[\''+id+'\']=this.value">'+[['summary','Summary'],['full','Full']].map(function(x){return '<option value="'+x[0]+'"'+(depth===x[0]?' selected':'')+'>'+x[1]+'</option>'}).join('')+'</select></label>';
 if(id==='5.2')h+='<button type="button" class="p5-connection-toggle" aria-expanded="'+!!UI.p5ConnOpen+'" aria-controls="p5-connection-options" onclick="UI.p5ConnOpen=!UI.p5ConnOpen;render()">'+(UI.p5ConnOpen?'▾':'▸')+' Connections shown in the PDF</button>';
 h+='<button class="btn bg2" onclick="p5Print(\''+id+'\')">▾ Save as PDF</button></div>';
 if(id==='5.2'&&UI.p5ConnOpen)h+='<div class="p5-print-connection-panel" id="p5-connection-options">'+amConnBar()+'</div>';
 return h+'</div>';
}
function p5Print(id){var sub=id==='5.1'||id==='archreview'?'':(UI.p5PrintScope||{})[id]||'',unit=id+(sub?'/'+sub:''),depth=(UI.p5PrintDepth||{})[id]||'summary';printDocument(p5UnitName(unit),p5Document(unit,depth),'')}
function p5Read(fn){/* Existing view helpers may normalize their inputs. Render against a copy, never the working record. */  _readOnlyRender++; /* 28 Sep 2026 (the consolidated re-audit, C02) : and nothing written while the copy is in place */ var oldData=data,oldUI=UI;data=reportClone(data);var copy={};Object.keys(UI).forEach(function(k){try{copy[k]=UI[k]&&typeof UI[k]==='object'?reportClone(UI[k]):UI[k]}catch(e){copy[k]=null}});UI=copy;UI._printing=1;UI._docAll=1;
 try{return fn()}finally{data=oldData;UI=oldUI;_readOnlyRender--} }
