/* Phase 5 paper-only pagination: measure content rather than markup, and let a
   single long evidence field flow. Other phases' document renderers stay intact. */
function p5Paginate(body){return String(body).replace(/<table\b[^>]*class="[^"]*(?:ly-rec|report-table)[^"]*"[^>]*>[\s\S]*?<\/table>/g,function(table){var long=false;var out=table.replace(/<tr\b([^>]*)>([\s\S]*?)<\/tr>/g,function(row,attrs,inner){var n=inner.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').length;if(n<900)return row;long=true;return '<tr'+(/\bclass=/.test(attrs)?attrs.replace(/class="([^"]*)"/,'class="$1 p5-long-row"'):attrs+' class="p5-long-row"')+'>'+inner+'</tr>'});if(long)out=out.replace(/(<table\b[^>]*class=")([^"]*)"/,'$1$2 p5-long-table"');return out})}
/* A selected wide subsection keeps its report-manager title on the same page.
   Replace an identical local title, otherwise retain both levels of hierarchy. */
function p5CompileHead(body,head,title){var a=body.indexOf('<section class="p5-section');if(a<0)return head+body;var tagEnd=body.indexOf('>',a)+1;var b=body.indexOf('<div class="ly-group"',tagEnd);if(b!==tagEnd)return body.slice(0,tagEnd)+head+body.slice(tagEnd);var re=/<\/?div\b[^>]*>/g;re.lastIndex=b;var depth=0,m,end=b;while((m=re.exec(body))){depth+=/^<\/div/.test(m[0])?-1:1;if(depth===0){end=re.lastIndex;break}}var local=body.slice(b,end).replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();var same=local===esc(title);return body.slice(0,b)+head+(same?'':body.slice(b,end))+body.slice(end)}

